CH.append(dict(ch=4,
 title=("Violations and suspensions","Vyolasyon ak sispansyon","Infractions et suspensions","Infracciones y suspensiones"),
 bp=("Manual chapter 3, pages 56–68. On the RMV test: suspensions and JOL violations.","Chapit 3 nan mànyèl la, paj 56–68. Nan egzamen RMV a: sispansyon ak vyolasyon JOL.","Chapitre 3 du manuel, pages 56–68. À l'examen du RMV : suspensions et infractions JOL.","Capítulo 3 del manual, páginas 56–68. En el examen del RMV: suspensiones e infracciones JOL."),
 sections=[
  dict(h=("Civil and criminal violations","Vyolasyon sivil ak kriminèl","Infractions civiles et pénales","Infracciones civiles y penales"), pg="56–58", b=[
   ("li",("Civil violations, like speeding or ignoring a signal, are settled with fines. You have 20 days to pay or to request a hearing ($25 filing fee, refunded if you are found not responsible on all violations).","Vyolasyon sivil, tankou depase limit vitès oswa pa respekte yon siyal, regle ak amann. Ou gen 20 jou pou w peye oswa mande yon odyans (frè $25, yo remèt li si yo jwenn ou pa responsab pou tout vyolasyon yo).","Les infractions civiles, comme l'excès de vitesse ou le non-respect d'un feu, se règlent par une amende. Vous avez 20 jours pour payer ou demander une audience (frais de 25 $, remboursés si vous êtes jugé non responsable de toutes les infractions).","Las infracciones civiles, como exceso de velocidad o no obedecer una señal, se resuelven con multas. Tiene 20 días para pagar o pedir una audiencia (tarifa de $25, que se devuelve si lo declaran no responsable de todas).")),
   ("li",("If you ignore a citation for 20 days, you are found responsible, charged a late fee, and your license can be suspended.","Si w inyore yon kontravansyon pandan 20 jou, yo jwenn ou responsab, yo fè w peye yon frè reta, epi yo ka sispann lisans ou.","Si vous ignorez une contravention pendant 20 jours, vous êtes jugé responsable, payez des frais de retard et votre permis peut être suspendu.","Si ignora una multa por 20 días, lo declaran responsable, le cobran un recargo por atraso y le pueden suspender la licencia.")),
   ("li",("Criminal violations include driving with a suspended license, operating under the influence (OUI) and leaving the scene of a crash. You can be arrested on the spot.","Vyolasyon kriminèl gen ladan kondui ak yon lisans sispann, kondui anba enfliyans (OUI), ak kite sèn yon aksidan. Yo ka arete w sou plas.","Les infractions pénales incluent la conduite avec un permis suspendu, la conduite sous influence (OUI) et le délit de fuite. Vous pouvez être arrêté sur-le-champ.","Las infracciones penales incluyen manejar con licencia suspendida, manejar bajo la influencia (OUI) y huir del lugar de un choque. Lo pueden arrestar en el acto.")),
   ("li",("You can be arrested if you refuse to give your name and address, show your license or registration, or sign your name for an officer. Out-of-state violations count as if they happened in Massachusetts.","Yo ka arete w si w refize bay non w ak adrès ou, montre lisans oswa anrejistreman w, oswa siyen non w devan yon polisye. Vyolasyon nan lòt eta konte menm jan ak si yo te fèt nan Massachusetts.","Vous pouvez être arrêté si vous refusez de donner nom et adresse, de montrer permis ou certificat d'immatriculation, ou de signer devant un policier. Les infractions hors de l'État comptent comme si elles avaient eu lieu au Massachusetts.","Lo pueden arrestar si se niega a dar su nombre y dirección, mostrar licencia o registro, o firmar ante un policía. Las infracciones en otros estados cuentan como si fueran en Massachusetts."))]),
  dict(h=("Speeding fines","Amann pou vitès","Amendes pour excès de vitesse","Multas por velocidad"), pg="57, 59", b=[
   ("li",("The lowest speeding fine is $100, plus a $5 public safety surcharge. Above 10 mph over the limit, add $10 for each extra mph. The manual's example: 73 mph in a 55 zone costs $185.","Pi piti amann pou vitès se $100, plis $5 pou sekirite piblik. Lè w depase limit lan plis pase 10 mph, ajoute $10 pou chak mph anplis. Egzanp mànyèl la: 73 mph nan yon zòn 55 koute $185.","L'amende minimale pour excès de vitesse est de 100 $, plus 5 $ de surtaxe de sécurité publique. Au-delà de 10 mph au-dessus de la limite, ajoutez 10 $ par mph. Exemple du manuel : 73 mph dans une zone à 55 coûte 185 $.","La multa mínima por velocidad es de $100, más $5 de recargo de seguridad pública. Pasando 10 mph sobre el límite, se suman $10 por cada mph extra. Ejemplo del manual: 73 mph en zona de 55 cuesta $185.")),
   ("li",("Speeding fines are doubled in a posted work zone.","Amann pou vitès double nan yon zòn travay ki make.","Les amendes pour excès de vitesse sont doublées dans une zone de travaux signalée.","Las multas por velocidad se duplican en una zona de obras señalizada.")),
   ("li",("Three speeding violations within 12 months: automatic 30-day suspension.","Twa vyolasyon vitès nan 12 mwa: sispansyon otomatik 30 jou.","Trois excès de vitesse en 12 mois : suspension automatique de 30 jours.","Tres infracciones de velocidad en 12 meses: suspensión automática de 30 días."))]),
  dict(h=("Surchargeable events and at-fault crashes","Evènman ki ka fè w peye plis ak aksidan kote w an tò","Événements entraînant une majoration et accidents responsables","Eventos con recargo y choques con culpa"), pg="58–60, 62", b=[
   ("li",("Moving violations and at-fault crashes are surchargeable events. They count toward suspension and raise your insurance rate.","Vyolasyon pandan w ap kondui ak aksidan kote w an tò se evènman ki ka fè w peye plis. Yo konte pou sispansyon epi yo fè asirans ou monte.","Les infractions de conduite et les accidents responsables sont des événements entraînant une majoration. Ils comptent pour la suspension et font monter l'assurance.","Las infracciones de manejo y los choques con culpa son eventos con recargo. Cuentan para una suspensión y suben el seguro.")),
   ("li",("You are usually at fault in a rear-end crash, a crash on the wrong side of the road, or while backing up, among other standards of fault.","Anjeneral ou an tò nan yon aksidan kote w frape yon machin pa dèyè, yon aksidan sou move bò wout la, oswa pandan w ap fè bak, pami lòt règ.","Vous êtes généralement responsable d'une collision par l'arrière, d'une collision du mauvais côté de la route ou en marche arrière, entre autres critères.","Por lo general usted tiene la culpa en un choque por detrás, en un choque en el lado equivocado del camino o al retroceder, entre otros criterios.")),
   ("li",("Three surchargeable events in two years: complete the Driver Retraining course within 90 days or your license is suspended. Seven in three years: automatic 60-day suspension.","Twa evènman nan dezan: fè Kou Refòmasyon pou Chofè a nan 90 jou, sinon lisans ou sispann. Sèt nan twazan: sispansyon otomatik 60 jou.","Trois événements en deux ans : suivre le cours de réadaptation des conducteurs dans les 90 jours, sinon suspension. Sept en trois ans : suspension automatique de 60 jours.","Tres eventos en dos años: tomar el curso de reentrenamiento de conductores en 90 días o le suspenden la licencia. Siete en tres años: suspensión automática de 60 días.")),
   ("li",("Habitual traffic offender (3 major violations, or 12 major or minor, within 5 years): four-year suspension.","Moun ki abitye vyole lwa sikilasyon (3 gwo vyolasyon, oswa 12 gwo oswa piti, nan 5 an): sispansyon kat an.","Contrevenant d'habitude (3 infractions graves, ou 12 graves ou mineures, en 5 ans) : suspension de quatre ans.","Infractor habitual (3 infracciones graves, o 12 graves o menores, en 5 años): suspensión de cuatro años."))]),
  dict(h=("Junior operator suspensions","Sispansyon pou jèn chofè","Suspensions des conducteurs juniors","Suspensiones de conductores menores"), pg="63–65", b=[
   ("li",("Permit holders under 18 who drive without a licensed driver, or during the night restriction: 60 days the first time, 180 days the second, one year after that, and they must retake the permit exam.","Moun ki gen pèmi, ki poko gen 18 an, epi ki kondui san yon chofè ki gen lisans, oswa pandan restriksyon lannwit lan: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa, epi yo dwe repase egzamen pèmi a.","Titulaires d'un permis d'apprenti de moins de 18 ans qui conduisent sans conducteur titulaire d'un permis, ou pendant la restriction de nuit : 60 jours la première fois, 180 jours la deuxième, un an ensuite, et ils doivent repasser l'examen du permis.","Menores de 18 con permiso que manejan sin un conductor con licencia, o durante la restricción nocturna: 60 días la primera vez, 180 la segunda, un año después, y deben repetir el examen del permiso.")),
   ("li",("Using a phone or texting while driving (junior operator): 60 days and a $100 fine the first time, plus a Driver Attitudinal Retraining course and a new permit exam.","Sèvi ak telefòn oswa voye tèks pandan w ap kondui (jèn chofè): 60 jou ak $100 amann premye fwa, plis yon kou refòmasyon atitid chofè ak yon nouvo egzamen pèmi.","Téléphone ou textos au volant (conducteur junior) : 60 jours et 100 $ d'amende la première fois, plus un cours de réadaptation comportementale et un nouvel examen du permis.","Usar el teléfono o enviar textos al manejar (conductor menor): 60 días y $100 de multa la primera vez, más un curso de reentrenamiento de actitud y un nuevo examen del permiso.")),
   ("li",("Junior operators: speeding 90 days (then one year); drag racing one year (then three years). An extra 180 days applies for offenses such as OUI, leaving the scene, or lending your license. Parents are notified.","Jèn chofè: vitès 90 jou (apre sa yon ane); kous machin yon ane (apre sa twazan). Gen 180 jou anplis pou vyolasyon tankou OUI, kite sèn aksidan, oswa prete lisans ou. Yo avèti paran yo.","Conducteurs juniors : vitesse 90 jours (puis un an) ; course de rue un an (puis trois ans). 180 jours de plus s'appliquent pour des infractions comme l'OUI, le délit de fuite ou le prêt du permis. Les parents sont avertis.","Conductores menores: velocidad 90 días (luego un año); carreras ilegales un año (luego tres). Se suman 180 días por infracciones como OUI, huir de un choque o prestar la licencia. Se avisa a los padres."))]),
  dict(h=("When your license is suspended","Lè lisans ou sispann","Quand votre permis est suspendu","Cuando su licencia está suspendida"), pg="61–62, 66–68", b=[
   ("li",("Stop driving immediately. Driving with a suspended or revoked license is a criminal violation, here or in any other state.","Sispann kondui touswit. Kondui ak yon lisans sispann oswa revoke se yon vyolasyon kriminèl, isit la oswa nan nenpòt lòt eta.","Arrêtez de conduire immédiatement. Conduire avec un permis suspendu ou révoqué est une infraction pénale, ici ou dans tout autre État.","Deje de manejar de inmediato. Manejar con licencia suspendida o revocada es una infracción penal, aquí o en cualquier otro estado.")),
   ("li",("To get it back you pay a reinstatement fee (usually $100, up to $1,200). After a suspension of two years or more, you must pass the permit exam and road test again.","Pou w jwenn li ankò, ou peye yon frè reyentegrasyon (souvan $100, jiska $1,200). Apre yon sispansyon dezan oswa plis, ou dwe repase egzamen pèmi a ak Egzamen Pratik la.","Pour le récupérer, vous payez des frais de rétablissement (souvent 100 $, jusqu'à 1 200 $). Après une suspension de deux ans ou plus, il faut repasser l'examen du permis et l'examen routier.","Para recuperarla paga una tarifa de restablecimiento (casi siempre $100, hasta $1,200). Tras una suspensión de dos años o más, debe aprobar otra vez el examen del permiso y el práctico.")),
   ("li",("Using a fake ID, someone else's license or false information can bring a suspension of up to six months without a conviction, and one year after a conviction.","Sèvi ak yon fo kat idantite, lisans yon lòt moun, oswa fo enfòmasyon ka lakoz yon sispansyon jiska sis mwa san kondanasyon, ak yon ane apre yon kondanasyon.","Utiliser une fausse pièce d'identité, le permis d'autrui ou de fausses informations peut entraîner jusqu'à six mois de suspension sans condamnation, et un an après une condamnation.","Usar una identificación falsa, la licencia de otra persona o información falsa puede causar hasta seis meses de suspensión sin condena, y un año después de una condena."))])],
 terms=[("civil motor vehicle infraction (CMVI)","vyolasyon sivil","infraction civile","infracción civil"),("surchargeable event","evènman ki ka fè w peye plis","événement entraînant une majoration","evento con recargo"),
        ("Driver Retraining course","Kou Refòmasyon pou Chofè","cours de réadaptation des conducteurs","curso de reentrenamiento de conductores"),("reinstatement fee","frè reyentegrasyon","frais de rétablissement","tarifa de restablecimiento"),("revoked","revoke","révoqué","revocada")],
 qs=[
  ("pm401",1,0,("citation","kontravansyon","contravention","multa"),
   ("You receive a citation for a civil violation. How long do you have to pay it or request a hearing?","Ou resevwa yon kontravansyon pou yon vyolasyon sivil. Konbyen tan ou genyen pou w peye l oswa mande yon odyans?","Vous recevez une contravention pour une infraction civile. De combien de temps disposez-vous pour payer ou demander une audience ?","Recibe una multa por una infracción civil. ¿Cuánto tiempo tiene para pagarla o pedir una audiencia?"),
   ("10 days","10 jou","10 jours","10 días"),("20 days","20 jou","20 jours","20 días"),("60 days","60 jou","60 jours","60 días"),("Six months","Sis mwa","Six mois","Seis meses"),
   ("You have 20 days to pay or request a hearing. If you do nothing, you are found responsible, charged a late fee, and your license can be suspended.","Ou gen 20 jou pou w peye oswa mande yon odyans. Si w pa fè anyen, yo jwenn ou responsab, yo fè w peye frè reta, epi yo ka sispann lisans ou.","Vous avez 20 jours pour payer ou demander une audience. Sinon, vous êtes jugé responsable, payez des frais de retard et le permis peut être suspendu.","Tiene 20 días para pagar o pedir audiencia. Si no hace nada, lo declaran responsable, le cobran recargo y le pueden suspender la licencia.")),
  ("pm402",3,0,("hearing","odyans","audience","audiencia"),
   ("You request a hearing to dispute a civil citation. What happens to the $25 filing fee if you are found not responsible for all violations?","Ou mande yon odyans pou w konteste yon kontravansyon sivil. Kisa k ap rive ak frè $25 la si yo jwenn ou pa responsab pou tout vyolasyon yo?","Vous demandez une audience pour contester une contravention civile. Qu'advient-il des 25 $ de frais si vous êtes jugé non responsable de toutes les infractions ?","Pide audiencia para disputar una multa civil. ¿Qué pasa con la tarifa de $25 si lo declaran no responsable de todas?"),
   ("It is kept","Yo kenbe l","Ils sont conservés","Se la quedan"),("It doubles","Li double","Ils doublent","Se duplica"),("It goes toward your insurance","Li ale nan asirans ou","Ils vont à votre assurance","Va a su seguro"),("It is refunded","Yo remèt ou li","Ils sont remboursés","Se la devuelven"),
   ("A hearing request costs $25. The fee is refunded if the court finds you not responsible for all violations on the citation.","Mande yon odyans koute $25. Yo remèt ou frè a si tribinal la jwenn ou pa responsab pou tout vyolasyon ki sou kontravansyon an.","Une demande d'audience coûte 25 $. Les frais sont remboursés si le tribunal vous juge non responsable de toutes les infractions.","Pedir audiencia cuesta $25. Se devuelve si el tribunal lo declara no responsable de todas las infracciones de la multa.")),
  ("pm403",0,0,("criminal violation","vyolasyon kriminèl","infraction pénale","infracción penal"),
   ("Which of these is a criminal motor vehicle violation?","Kiyès nan sa yo ki yon vyolasyon kriminèl?","Laquelle de ces infractions est pénale ?","¿Cuál de estas es una infracción penal?"),
   ("Leaving the scene of a crash","Kite sèn yon aksidan","Quitter les lieux d'un accident","Huir del lugar de un choque"),
   ("Going 5 mph over the limit","Depase limit vitès la 5 mph","Dépasser la limite de 5 mph","Ir 5 mph sobre el límite"),
   ("Failing to signal","Pa mete siyal","Ne pas signaler","No poner la direccional"),
   ("A parking ticket","Yon kontravansyon pakin","Une contravention de stationnement","Una multa de estacionamiento"),
   ("Criminal violations include leaving the scene of a crash, operating under the influence and driving with a suspended license. Speeding and failing to signal are civil.","Vyolasyon kriminèl gen ladan kite sèn yon aksidan, kondui anba enfliyans, ak kondui ak lisans sispann. Vitès ak pa mete siyal se vyolasyon sivil.","Les infractions pénales incluent le délit de fuite, la conduite sous influence et la conduite avec permis suspendu. La vitesse et l'absence de signal sont civiles.","Las infracciones penales incluyen huir de un choque, manejar bajo la influencia y manejar con licencia suspendida. La velocidad y no señalar son civiles.")),
  ("pm404",2,0,("arrest","arestasyon","arrestation","arresto"),
   ("A police officer stops you and asks for your license. You refuse to show it. What can happen?","Yon polisye kanpe w epi l mande lisans ou. Ou refize montre l. Kisa ki ka rive?","Un policier vous arrête et demande votre permis. Vous refusez de le montrer. Que peut-il se passer ?","Un policía lo detiene y le pide la licencia. Se niega a mostrarla. ¿Qué puede pasar?"),
   ("Nothing, if you were not speeding","Anyen, si w pa t ap fè vitès","Rien, si vous n'étiez pas en excès de vitesse","Nada, si no iba con exceso de velocidad"),
   ("Only a written warning","Sèlman yon avètisman ekri","Seulement un avertissement écrit","Solo una advertencia escrita"),
   ("You can be arrested and face criminal charges","Yo ka arete w epi ou ka fè fas ak akizasyon kriminèl","Vous pouvez être arrêté et faire face à des accusations pénales","Lo pueden arrestar y enfrentar cargos penales"),
   ("The officer must let you go","Polisye a oblije kite w ale","Le policier doit vous laisser partir","El policía debe dejarlo ir"),
   ("Refusing to give your name and address, show your license or registration, or sign your name can lead to arrest and criminal charges.","Refize bay non ak adrès ou, montre lisans oswa anrejistreman, oswa siyen non w ka mennen nan arestasyon ak akizasyon kriminèl.","Refuser de donner nom et adresse, de montrer permis ou immatriculation, ou de signer peut entraîner une arrestation et des accusations pénales.","Negarse a dar nombre y dirección, mostrar licencia o registro, o firmar puede llevar a arresto y cargos penales.")),
  ("pm405",1,0,("out-of-state violation","vyolasyon nan lòt eta","infraction hors de l'État","infracción en otro estado"),
   ("You get a speeding ticket in New Hampshire. How does it affect your Massachusetts record?","Ou jwenn yon kontravansyon vitès nan New Hampshire. Kijan sa afekte dosye w nan Massachusetts?","Vous recevez une contravention pour vitesse au New Hampshire. Quel effet sur votre dossier au Massachusetts ?","Recibe una multa por velocidad en New Hampshire. ¿Cómo afecta su historial en Massachusetts?"),
   ("It does not count in Massachusetts","Li pa konte nan Massachusetts","Elle ne compte pas au Massachusetts","No cuenta en Massachusetts"),
   ("It counts as if it happened in Massachusetts","Li konte menm jan ak si l te rive nan Massachusetts","Elle compte comme si elle avait eu lieu au Massachusetts","Cuenta como si hubiera ocurrido en Massachusetts"),
   ("It counts only if you were under 18","Li konte sèlman si w te poko gen 18 an","Elle compte seulement si vous aviez moins de 18 ans","Solo cuenta si era menor de 18"),
   ("It counts only after three tickets","Li konte sèlman apre twa kontravansyon","Elle compte seulement après trois contraventions","Solo cuenta después de tres multas"),
   ("Out-of-state violations affect your record as if they happened in Massachusetts. Ignoring them can lead to a suspension here.","Vyolasyon nan lòt eta afekte dosye w menm jan ak si yo te fèt nan Massachusetts. Si w inyore yo, yo ka sispann lisans ou isit la.","Les infractions hors de l'État comptent comme si elles avaient eu lieu au Massachusetts. Les ignorer peut entraîner une suspension ici.","Las infracciones de otros estados afectan su historial como si fueran en Massachusetts. Ignorarlas puede causar una suspensión aquí.")),
  ("pm406",3,1,("work zone","zòn travay","zone de travaux","zona de obras"),
   ("You are caught speeding in a posted work zone. What happens to the fine?","Yo kenbe w ap fè vitès nan yon zòn travay ki make. Kisa k ap rive ak amann lan?","Vous êtes pris en excès de vitesse dans une zone de travaux signalée. Qu'advient-il de l'amende ?","Lo sorprenden con exceso de velocidad en una zona de obras señalizada. ¿Qué pasa con la multa?"),
   ("It is the same as anywhere else","Li menm jan ak tout lòt kote","Elle est la même qu'ailleurs","Es igual que en cualquier otro lugar"),("It is cut in half","Yo koupe l an de","Elle est réduite de moitié","Se reduce a la mitad"),("It becomes a warning","Li tounen yon avètisman","Elle devient un avertissement","Se convierte en advertencia"),("It is doubled","Li double","Elle est doublée","Se duplica"),
   ("Speeding fines are doubled in posted work zones.","Amann pou vitès double nan zòn travay ki make.","Les amendes pour vitesse sont doublées dans les zones de travaux signalées.","Las multas por velocidad se duplican en zonas de obras señalizadas.")),
  ("pm407",0,1,("speeding fine","amann vitès","amende pour vitesse","multa por velocidad"),
   ("Using the manual's example, what is the total fine for driving 73 mph where the limit is 55 mph?","Dapre egzanp mànyèl la, konbyen amann total la ye si w kondui 73 mph kote limit lan se 55 mph?","D'après l'exemple du manuel, quelle est l'amende totale pour 73 mph où la limite est de 55 ?","Según el ejemplo del manual, ¿cuál es la multa total por manejar a 73 mph donde el límite es 55?"),
   ("$185","$185","185 $","$185"),("$100","$100","100 $","$100"),("$73","$73","73 $","$73"),("$360","$360","360 $","$360"),
   ("You were 18 mph over. In the manual's example the first 10 mph cost $105 (the $100 minimum plus a $5 public safety surcharge), plus $10 for each of the next 8 mph ($80): $185.","Ou te depase limit lan 18 mph. Nan egzanp mànyèl la, 10 premye mph yo koute $105 (minimòm $100 plis $5 pou sekirite piblik), plis $10 pou chak nan 8 mph ki vin apre yo ($80): $185.","Vous étiez à 18 mph au-dessus. Dans l'exemple du manuel, les 10 premiers mph coûtent 105 $ (minimum de 100 $ plus 5 $ de surtaxe de sécurité publique), plus 10 $ pour chacun des 8 mph suivants (80 $) : 185 $.","Iba 18 mph sobre el límite. En el ejemplo del manual, las primeras 10 mph cuestan $105 (el mínimo de $100 más $5 de recargo de seguridad pública), más $10 por cada una de las 8 mph siguientes ($80): $185.")),
  ("pm408",2,1,("speeding violation","vyolasyon vitès","excès de vitesse","infracción de velocidad"),
   ("You are an adult driver found responsible for three speeding violations within 12 months. What happens?","Ou se yon chofè granmoun yo jwenn responsab pou twa vyolasyon vitès nan 12 mwa. Kisa k ap rive?","Vous êtes un conducteur adulte reconnu responsable de trois excès de vitesse en 12 mois. Que se passe-t-il ?","Usted es un conductor adulto declarado responsable de tres infracciones de velocidad en 12 meses. ¿Qué pasa?"),
   ("Nothing more than the fines","Anyen anplis amann yo","Rien de plus que les amendes","Nada más que las multas"),("A one-year suspension","Yon sispansyon yon ane","Une suspension d'un an","Una suspensión de un año"),("An automatic 30-day suspension","Yon sispansyon otomatik 30 jou","Une suspension automatique de 30 jours","Una suspensión automática de 30 días"),("You must retake the road test","Ou dwe repase Egzamen Pratik la","Vous devez repasser l'examen routier","Debe repetir el examen práctico"),
   ("Three speeding violations within 12 months bring an automatic 30-day suspension. The 12 months start when you pay or are found responsible for the first one.","Twa vyolasyon vitès nan 12 mwa bay yon sispansyon otomatik 30 jou. 12 mwa yo kòmanse lè w peye oswa yo jwenn ou responsab pou premye a.","Trois excès de vitesse en 12 mois entraînent une suspension automatique de 30 jours. Les 12 mois commencent au paiement ou à la décision sur la première.","Tres infracciones de velocidad en 12 meses traen una suspensión automática de 30 días. Los 12 meses empiezan al pagar o ser declarado responsable de la primera.")),
  ("pm409",1,2,("surchargeable event","evènman ki ka fè w peye plis","événement entraînant une majoration","evento con recargo"),
   ("What is a surchargeable event?","Kisa yon evènman ki ka fè w peye plis ye?","Qu'est-ce qu'un événement entraînant une majoration ?","¿Qué es un evento con recargo?"),
   ("Any trip on a toll road or highway","Nenpòt vwayaj sou yon wout peyaj oswa gran wout","Tout trajet sur une route à péage ou une autoroute","Cualquier viaje por una carretera de peaje o autopista"),
   ("A moving violation or an at-fault crash","Yon vyolasyon pandan w ap kondui oswa yon aksidan kote w an tò","Une infraction de conduite ou un accident responsable","Una infracción de manejo o un choque con culpa"),
   ("A parking ticket","Yon kontravansyon pakin","Une contravention de stationnement","Una multa de estacionamiento"),
   ("Renewing your license after it expires","Renouvle lisans ou apre l fin ekspire","Renouveler votre permis après son expiration","Renovar su licencia después de que vence"),
   ("Moving violations and at-fault crashes are surchargeable events. Each one counts toward a possible suspension and can raise your insurance.","Vyolasyon pandan w ap kondui ak aksidan kote w an tò se evènman ki ka fè w peye plis. Chak konte pou yon sispansyon posib epi yo ka fè asirans ou monte.","Les infractions de conduite et accidents responsables entraînent une majoration. Chacun compte pour une éventuelle suspension et peut faire monter l'assurance.","Las infracciones de manejo y los choques con culpa son eventos con recargo. Cada uno cuenta para una posible suspensión y puede subir el seguro.")),
  ("pm410",3,2,("Driver Retraining course","Kou Refòmasyon pou Chofè","cours de réadaptation des conducteurs","curso de reentrenamiento de conductores"),
   ("You have three surchargeable events within two years. What must you do?","Ou gen twa evènman ki ka fè w peye plis nan dezan. Kisa ou dwe fè?","Vous avez trois événements entraînant une majoration en deux ans. Que devez-vous faire ?","Tiene tres eventos con recargo en dos años. ¿Qué debe hacer?"),
   ("Nothing yet; it takes seven events","Anyen pou kounye a; fòk gen sèt evènman","Rien pour l'instant ; il en faut sept","Nada todavía; hacen falta siete"),("Pay a $500 fine to the RMV within 30 days","Peye yon amann $500 bay RMV nan 30 jou","Payer une amende de 500 $ au RMV dans les 30 jours","Pagar una multa de $500 al RMV dentro de 30 días"),("Retake the road test within 30 days","Repase egzamen sou wout la nan 30 jou","Repasser l'examen de conduite dans les 30 jours","Volver a tomar el examen de manejo dentro de 30 días"),("Complete the Driver Retraining course within 90 days","Fè Kou Refòmasyon pou Chofè a nan 90 jou","Suivre le cours de réadaptation dans les 90 jours","Tomar el curso de reentrenamiento en 90 días"),
   ("Three surchargeable events in two years: finish the Driver Retraining course within 90 days, or your license stays suspended until you do. Seven events in three years bring an automatic 60-day suspension.","Twa evènman nan dezan: fini Kou Refòmasyon pou Chofè a nan 90 jou, sinon lisans ou rete sispann jiskaske w fè l. Sèt evènman nan twazan bay yon sispansyon otomatik 60 jou.","Trois événements en deux ans : terminez le cours de réadaptation en 90 jours, sinon le permis reste suspendu jusqu'à ce que vous le fassiez. Sept en trois ans : suspension automatique de 60 jours.","Tres eventos en dos años: termine el curso en 90 días, o la licencia queda suspendida hasta que lo haga. Siete en tres años traen una suspensión automática de 60 días.")),
  ("pm411",0,2,("at-fault crash","aksidan kote w an tò","accident responsable","choque con culpa"),
   ("Which crash is usually counted as your fault?","Ki aksidan yo konn konte kòm se fòt ou?","Quel accident est généralement considéré comme votre faute ?","¿Qué choque suele contarse como culpa suya?"),
   ("You hit the car in front of you from behind","Ou frape machin ki devan w lan pa dèyè","Vous heurtez par l'arrière la voiture devant vous","Choca por detrás al auto de adelante"),
   ("A driver runs a red light and hits you","Yon chofè pase limyè wouj epi l frape w","Un conducteur brûle un feu rouge et vous heurte","Otro conductor se pasa el rojo y lo choca"),
   ("Someone hits your parked car","Yon moun frape machin ou ki pake","Quelqu'un heurte votre voiture garée","Alguien choca su auto estacionado"),
   ("A car rear-ends you at a stop sign","Yon machin frape w pa dèyè nan yon siy STOP","Une voiture vous heurte par l'arrière à un arrêt","Un auto lo choca por detrás en un PARE"),
   ("A rear-end collision is one of the standards of fault. So are crashing on the wrong side of the road, while backing up, or into a parked car.","Frape yon machin pa dèyè se youn nan règ ki di w an tò. Menm jan pou frape sou move bò wout la, pandan w ap fè bak, oswa frape yon machin ki pake.","La collision par l'arrière est un critère de responsabilité, tout comme la collision du mauvais côté, en marche arrière ou contre un véhicule garé.","El choque por detrás es uno de los criterios de culpa, igual que chocar en el lado equivocado, al retroceder o contra un auto estacionado.")),
  ("pm412",2,3,("night restriction","restriksyon lannwit","restriction de nuit","restricción nocturna"),
   ("A 17-year-old with a permit is caught driving with no licensed driver in the car. What happens for a first offense?","Yo kenbe yon jèn 17 an ki gen pèmi ap kondui san okenn chofè ki gen lisans nan machin nan. Kisa k ap rive pou premye fwa?","Un jeune de 17 ans avec un permis d'apprenti est pris à conduire sans conducteur titulaire d'un permis. Que se passe-t-il la première fois ?","Un joven de 17 años con permiso maneja sin ningún conductor con licencia. ¿Qué pasa la primera vez?"),
   ("A warning only, since it is a first offense","Yon avètisman sèlman, paske se premye fwa","Un avertissement seulement, puisque c'est la première fois","Solo una advertencia, porque es la primera vez"),
   ("A $25 fine and a note on their record","Yon amann $25 ak yon nòt nan dosye yo","Une amende de 25 $ et une note au dossier","Una multa de $25 y una nota en su historial"),
   ("A 60-day suspension, and they must retake the permit exam","Yon sispansyon 60 jou, epi li dwe repase egzamen pèmi a","Une suspension de 60 jours, et il doit repasser l'examen du permis","Una suspensión de 60 días, y debe repetir el examen del permiso"),
   ("A three-year suspension","Yon sispansyon twazan","Une suspension de trois ans","Una suspensión de tres años"),
   ("For permit holders under 18, driving without a licensed driver brings a 60-day suspension the first time (180 days, then one year), and every offense requires retaking the permit exam.","Pou moun ki gen pèmi epi ki poko gen 18 an, kondui san chofè ki gen lisans bay yon sispansyon 60 jou premye fwa (180 jou, apre sa yon ane), epi chak fwa yo dwe repase egzamen pèmi a.","Pour les titulaires d'un permis d'apprenti de moins de 18 ans, conduire sans conducteur titulaire d'un permis entraîne 60 jours la première fois (180 jours, puis un an), et chaque infraction exige de repasser l'examen.","Para menores de 18 con permiso, manejar sin un conductor con licencia trae 60 días la primera vez (180 días, luego un año), y cada vez deben repetir el examen del permiso.")),
  ("pm413",1,3,("Driver Attitudinal Retraining","kou refòmasyon atitid chofè","réadaptation comportementale","reentrenamiento de actitud"),
   ("A junior operator is convicted of texting while driving for the first time. What is the suspension?","Yo kondane yon jèn chofè pou voye tèks pandan l ap kondui, premye fwa. Konbyen tan sispansyon an?","Un conducteur junior est condamné pour textos au volant pour la première fois. Quelle suspension ?","Un conductor menor es condenado por enviar textos al manejar por primera vez. ¿Cuál es la suspensión?"),
   ("None, only a $100 fine and a warning letter","Okenn, se amann $100 ak yon lèt avètisman sèlman","Aucune, seulement 100 $ d'amende et une lettre d'avertissement","Ninguna, solo una multa de $100 y una carta de advertencia"),
   ("60 days, a $100 fine, retraining and a new permit exam","60 jou, $100 amann, refòmasyon ak yon nouvo egzamen pèmi","60 jours, 100 $ d'amende, une réadaptation et un nouvel examen","60 días, $100 de multa, reentrenamiento y un nuevo examen del permiso"),
   ("Five years, with no hardship license","Senk an, san lisans espesyal pou travay","Cinq ans, sans permis restreint pour le travail","Cinco años, sin licencia especial para trabajar"),
   ("Seven days, with no other penalty","Sèt jou, san lòt penalite","Sept jours, sans autre sanction","Siete días, sin otra sanción"),
   ("Junior operators: 60 days the first time, 180 days the second, one year after that. The first offense also brings a $100 fine, a Driver Attitudinal Retraining course and a new permit exam.","Jèn chofè: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa. Premye fwa a gen $100 amann tou, yon kou refòmasyon atitid ak yon nouvo egzamen pèmi.","Conducteurs juniors : 60 jours la première fois, 180 la deuxième, un an ensuite. La première fois entraîne aussi 100 $ d'amende, un cours de réadaptation comportementale et un nouvel examen.","Conductores menores: 60 días la primera vez, 180 la segunda, un año después. La primera vez también trae $100 de multa, un curso de reentrenamiento de actitud y un nuevo examen del permiso.")),
  ("pm414",0,3,("drag racing","kous machin","course de rue","carreras ilegales"),
   ("A junior operator is convicted of drag racing for the first time. How long is the suspension?","Yo kondane yon jèn chofè pou kous machin premye fwa. Konbyen tan sispansyon an?","Un conducteur junior est condamné pour course de rue la première fois. Combien de temps de suspension ?","Un conductor menor es condenado por carreras ilegales la primera vez. ¿Cuánto dura la suspensión?"),
   ("One year","Yon ane","Un an","Un año"),("30 days","30 jou","30 jours","30 días"),("90 days","90 jou","90 jours","90 días"),("Lifetime","Pou tout lavi","À vie","De por vida"),
   ("Drag racing: one year for a junior operator's first offense, three years for a later one, plus a new permit exam and retraining.","Kous machin: yon ane pou premye fwa yon jèn chofè, twazan pou pwochen fwa, plis yon nouvo egzamen pèmi ak refòmasyon.","Course de rue : un an pour la première infraction d'un conducteur junior, trois ans ensuite, plus un nouvel examen et une réadaptation.","Carreras ilegales: un año la primera vez para un conductor menor, tres años la siguiente, más un nuevo examen y reentrenamiento.")),
  ("pm415",3,4,("suspended license","lisans sispann","permis suspendu","licencia suspendida"),
   ("Your license is suspended. What is true?","Lisans ou sispann. Kisa ki vre?","Votre permis est suspendu. Qu'est-ce qui est vrai ?","Su licencia está suspendida. ¿Qué es cierto?"),
   ("You may drive to work","Ou ka kondui pou w ale travay","Vous pouvez conduire pour aller au travail","Puede manejar al trabajo"),
   ("You may drive in another state","Ou ka kondui nan yon lòt eta","Vous pouvez conduire dans un autre État","Puede manejar en otro estado"),
   ("You may drive with a licensed adult beside you","Ou ka kondui ak yon granmoun ki gen lisans bò kote w","Vous pouvez conduire avec un adulte titulaire d'un permis à côté","Puede manejar con un adulto con licencia a su lado"),
   ("You must stop driving; driving now is a criminal violation","Ou dwe sispann kondui; si w kondui kounye a se yon vyolasyon kriminèl","Vous devez cesser de conduire ; conduire maintenant est une infraction pénale","Debe dejar de manejar; hacerlo ahora es una infracción penal"),
   ("A suspended or revoked license is not valid anywhere. Driving with it is a criminal violation that can bring a large fine or jail.","Yon lisans ki sispann oswa revoke pa valab okenn kote. Kondui ak li se yon vyolasyon kriminèl ki ka bay gwo amann oswa prizon.","Un permis suspendu ou révoqué n'est valable nulle part. Conduire avec est une infraction pénale passible d'une forte amende ou de prison.","Una licencia suspendida o revocada no es válida en ninguna parte. Manejar con ella es una infracción penal con multa alta o cárcel.")),
  ("pm416",2,4,("reinstatement","reyentegrasyon","rétablissement","restablecimiento"),
   ("Your license was suspended for two years. What must you do to get it back?","Yo te sispann lisans ou pou dezan. Kisa ou dwe fè pou w jwenn li ankò?","Votre permis a été suspendu deux ans. Que devez-vous faire pour le récupérer ?","Le suspendieron la licencia por dos años. ¿Qué debe hacer para recuperarla?"),
   ("Just wait; it comes back automatically when the two years end","Tann sèlman; li tounen otomatikman lè dezan yo fini","Attendre ; il revient automatiquement à la fin des deux ans","Solo esperar; vuelve automáticamente al terminar los dos años"),
   ("Pay a fee only, online","Peye yon frè sèlman, sou entènèt","Payer seulement des frais, en ligne","Solo pagar una tarifa, en línea"),
   ("Pay the reinstatement fee and pass the permit exam and road test again","Peye frè reyentegrasyon an epi repase egzamen pèmi a ak Egzamen Pratik la","Payer les frais de rétablissement et repasser l'examen du permis et l'examen routier","Pagar la tarifa de restablecimiento y aprobar otra vez el examen del permiso y el práctico"),
   ("Take a vision test only, at any RMV service center","Pase yon tès je sèlman, nan nenpòt sant sèvis RMV","Passer seulement un test de vue, dans n'importe quel centre du RMV","Solo pasar un examen de la vista, en cualquier centro del RMV"),
   ("After a suspension of two years or more, you must pass the permit exam and the road test again, and pay a reinstatement fee.","Apre yon sispansyon dezan oswa plis, ou dwe repase egzamen pèmi a ak Egzamen Pratik la, epi peye yon frè reyentegrasyon.","Après une suspension de deux ans ou plus, il faut repasser l'examen du permis et l'examen routier, et payer des frais de rétablissement.","Tras una suspensión de dos años o más, debe aprobar otra vez el examen del permiso y el práctico, y pagar una tarifa de restablecimiento.")),
  ("pm417",1,4,("fake ID","fo kat idantite","fausse pièce d'identité","identificación falsa"),
   ("Someone uses a friend's license to try to get into a bar. Even without a conviction, what can the RMV do?","Yon moun sèvi ak lisans yon zanmi pou l eseye antre nan yon ba. Menm san kondanasyon, kisa RMV ka fè?","Quelqu'un utilise le permis d'un ami pour entrer dans un bar. Même sans condamnation, que peut faire le RMV ?","Alguien usa la licencia de un amigo para entrar a un bar. Aun sin condena, ¿qué puede hacer el RMV?"),
   ("Nothing without a conviction","Anyen san kondanasyon","Rien sans condamnation","Nada sin condena"),
   ("Suspend their license for up to six months","Sispann lisans li pou jiska sis mwa","Suspendre son permis jusqu'à six mois","Suspenderle la licencia hasta seis meses"),
   ("Give a warning only","Bay yon avètisman sèlman","Donner seulement un avertissement","Solo dar una advertencia"),
   ("Take away the friend's license only","Retire lisans zanmi an sèlman","Retirer seulement le permis de l'ami","Quitarle solo la licencia al amigo"),
   ("Using someone else's license or a fake ID can bring a suspension of up to six months without a conviction, and one year after a conviction.","Sèvi ak lisans yon lòt moun oswa yon fo kat idantite ka bay yon sispansyon jiska sis mwa san kondanasyon, ak yon ane apre yon kondanasyon.","Utiliser le permis d'autrui ou une fausse pièce peut valoir jusqu'à six mois de suspension sans condamnation, et un an après condamnation.","Usar la licencia de otra persona o una identificación falsa puede traer hasta seis meses de suspensión sin condena, y un año con condena."))]))

# ---------------------------------------------------------------- P5
CH.append(dict(ch=5,
 title=("Alcohol, drugs and driving","Alkòl, dwòg ak kondui","Alcool, drogues et conduite","Alcohol, drogas y manejo"),
 bp=("Manual chapter 3, pages 68–75. On the RMV test: alcohol misuse.","Chapit 3 nan mànyèl la, paj 68–75. Nan egzamen RMV a: move itilizasyon alkòl.","Chapitre 3 du manuel, pages 68–75. À l'examen du RMV : mauvais usage de l'alcool.","Capítulo 3 del manual, páginas 68–75. En el examen del RMV: mal uso del alcohol."),
 sections=[
  dict(h=("How alcohol affects driving","Kijan alkòl afekte jan w kondui","Les effets de l'alcool sur la conduite","Cómo afecta el alcohol al manejo"), pg="71–72", b=[
   ("li",("Alcohol is a depressant. It slows your reflexes and reaction time and distorts your vision and judgment, while making you feel more confident.","Alkòl se yon depresè. Li ralanti reflèks ou ak tan reyaksyon w, li twouble vizyon ak jijman w, pandan l fè w santi w gen plis konfyans.","L'alcool est un dépresseur. Il ralentit les réflexes et le temps de réaction, fausse la vue et le jugement, tout en donnant plus d'assurance.","El alcohol es un depresor. Hace más lentos los reflejos y la reacción y distorsiona la vista y el juicio, mientras le da más confianza.")),
   ("li",("Alcohol makes a crash five times more likely; alcohol plus marijuana makes it twelve times more likely. Alcohol causes about 30% of U.S. highway deaths.","Alkòl fè risk aksidan an senk fwa pi gwo; alkòl ak mariwana fè l douz fwa pi gwo. Alkòl lakoz anviwon 30% lanmò sou wout Etazini.","L'alcool rend un accident cinq fois plus probable ; alcool et marijuana, douze fois plus. L'alcool cause environ 30 % des décès routiers aux États-Unis.","El alcohol hace un choque cinco veces más probable; alcohol y marihuana, doce veces más. El alcohol causa cerca del 30 % de las muertes en carreteras de EE. UU.")),
   ("li",("If you will drink, plan a safe way home: a designated driver, a taxi, a rideshare app, or a ride from family or friends.","Si w ap bwè, planifye yon fason san danje pou w rive lakay: yon chofè ki p ap bwè, yon taksi, yon aplikasyon transpò, oswa yon moun nan fanmi oswa yon zanmi.","Si vous allez boire, prévoyez un retour sûr : conducteur désigné, taxi, application de covoiturage, ou un proche.","Si va a beber, planee cómo volver seguro: un conductor designado, un taxi, una aplicación de viajes o alguien de su familia o amigos."))]),
  dict(h=("Blood alcohol content (BAC)","Kantite alkòl nan san (BAC)","Taux d'alcool dans le sang (BAC)","Contenido de alcohol en la sangre (BAC)"), pg="72", b=[
   ("li",("A 12-ounce beer, a 5-ounce glass of wine and a 1.5-ounce shot of 80-proof liquor hold about the same amount of alcohol. Each can raise an average person's BAC by about 0.02.","Yon bwat byè 12 ons, yon vè diven 5 ons ak yon ti vè 1.5 ons kleren 80 pwouf gen anviwon menm kantite alkòl. Chak ka fè BAC yon moun nòmal monte anviwon 0.02.","Une bière de 12 onces, un verre de vin de 5 onces et 1,5 once d'alcool fort à 80 degrés contiennent à peu près la même quantité d'alcool. Chacun peut faire monter le BAC d'environ 0,02.","Una cerveza de 12 onzas, una copa de vino de 5 onzas y un trago de 1.5 onzas de licor de 80 grados tienen casi la misma cantidad de alcohol. Cada uno puede subir el BAC unos 0.02.")),
   ("li",("BAC depends on your weight, how much you drank, food, how long you drank and your body. The type of drink does not matter.","BAC depann de pwa w, konbyen ou bwè, manje, pandan konbyen tan ou bwè ak kò w. Kalite bwason an pa enpòtan.","Le BAC dépend du poids, de la quantité bue, de la nourriture, de la durée et de votre corps. Le type de boisson n'a pas d'importance.","El BAC depende de su peso, cuánto bebió, la comida, cuánto tiempo bebió y su cuerpo. El tipo de bebida no importa.")),
   ("li",("Only time removes alcohol. Black coffee, a cold shower, exercise or food do not sober you up.","Se tan sèlman ki retire alkòl. Kafe nwa, yon douch frèt, egzèsis oswa manje pa fè w vin pa sou.","Seul le temps élimine l'alcool. Café noir, douche froide, exercice ou repas ne font pas dessoûler.","Solo el tiempo elimina el alcohol. Café negro, ducha fría, ejercicio o comida no le quitan la borrachera."))]),
  dict(h=("Legal limits and chemical tests","Limit lalwa ak tès chimik","Limites légales et tests chimiques","Límites legales y pruebas químicas"), pg="69–70, 72–73", b=[
   ("li",("You are over the legal limit at a BAC of 0.08 or higher. Drivers under 21 face penalties at 0.02 or higher: the zero-tolerance law.","Ou depase limit lalwa a lè BAC ou 0.08 oswa plis. Chofè ki poko gen 21 an jwenn penalite depi 0.02 oswa plis: se lwa zewo tolerans lan.","Vous dépassez la limite légale à un BAC de 0,08 ou plus. Les moins de 21 ans sont sanctionnés dès 0,02 : c'est la loi de tolérance zéro.","Está sobre el límite legal con un BAC de 0.08 o más. Los menores de 21 tienen sanciones desde 0.02: la ley de tolerancia cero.")),
   ("li",("Implied consent: by driving in Massachusetts you agree to a breath or blood test if you are arrested for OUI. Officers may also ask for a field sobriety test.","Konsantman implisit: lè w kondui nan Massachusetts, ou dakò fè yon tès souf oswa san si yo arete w pou OUI. Polisye a ka mande yon tès sobriyete sou plas tou.","Consentement implicite : en conduisant au Massachusetts, vous acceptez un test d'haleine ou sanguin si vous êtes arrêté pour OUI. Le policier peut aussi demander un test de sobriété sur place.","Consentimiento implícito: al manejar en Massachusetts acepta una prueba de aliento o sangre si lo arrestan por OUI. El policía también puede pedir una prueba de sobriedad en el lugar.")),
   ("li",("If your BAC is over the limit or you refuse the test, the officer takes your license on the spot. Failed test: 30 days (adults), plus 180 days (ages 18–21) or plus one year (under 18).","Si BAC ou depase limit lan oswa ou refize tès la, polisye a pran lisans ou sou plas. Si w echwe tès la: 30 jou (granmoun), plis 180 jou (18–21 an) oswa plis yon ane (anba 18 an).","Si votre BAC dépasse la limite ou si vous refusez le test, le policier prend votre permis sur-le-champ. Test échoué : 30 jours (adultes), plus 180 jours (18 à 21 ans) ou plus un an (moins de 18 ans).","Si su BAC pasa el límite o se niega a la prueba, el policía le quita la licencia en el acto. Prueba fallada: 30 días (adultos), más 180 días (18 a 21) o más un año (menores de 18).")),
   ("li",("Refusing the test with no prior OUI: 180 days over 21; three years plus 180 days for ages 18–21; three years plus one year under 18.","Refize tès la san okenn OUI anvan: 180 jou si w gen plis pase 21 an; twazan plis 180 jou pou 18–21 an; twazan plis yon ane si w poko gen 18 an.","Refus du test sans OUI antérieure : 180 jours après 21 ans ; trois ans plus 180 jours de 18 à 21 ans ; trois ans plus un an avant 18 ans.","Negarse a la prueba sin OUI previo: 180 días mayores de 21; tres años más 180 días de 18 a 21; tres años más un año menores de 18."))]),
  dict(h=("OUI penalties","Penalite pou OUI","Sanctions pour OUI","Sanciones por OUI"), pg="68", b=[
   ("li",("First OUI conviction: $500 to $5,000 fine, up to 2½ years in prison, and a one-year license suspension (an alcohol education program may shorten it).","Premye kondanasyon OUI: amann $500 a $5,000, jiska 2 an edmi prizon, ak yon sispansyon lisans yon ane (yon pwogram edikasyon sou alkòl ka diminye l).","Première condamnation pour OUI : amende de 500 à 5 000 $, jusqu'à 2 ans et demi de prison et un an de suspension (un programme d'éducation sur l'alcool peut la réduire).","Primera condena por OUI: multa de $500 a $5,000, hasta 2 años y medio de cárcel y un año de suspensión (un programa de educación sobre alcohol puede reducirla).")),
   ("li",("Second OUI: two years. Third: eight years (a felony). Fourth: ten years. Fifth: lifetime. The same penalties apply to driving under the influence of marijuana or other drugs.","Dezyèm OUI: dezan. Twazyèm: uit an (yon krim grav). Katriyèm: dis an. Senkyèm: pou tout lavi. Menm penalite yo aplike pou kondui anba enfliyans mariwana oswa lòt dwòg.","Deuxième OUI : deux ans. Troisième : huit ans (crime). Quatrième : dix ans. Cinquième : à vie. Les mêmes sanctions s'appliquent sous l'influence de la marijuana ou d'autres drogues.","Segundo OUI: dos años. Tercero: ocho años (delito grave). Cuarto: diez años. Quinto: de por vida. Las mismas sanciones aplican bajo los efectos de marihuana u otras drogas."))]),
  dict(h=("Under 21: alcohol laws","Anba 21 an: lwa sou alkòl","Moins de 21 ans : lois sur l'alcool","Menores de 21: leyes sobre el alcohol"), pg="73–74", b=[
   ("li",("Under 21, it is illegal to buy alcohol, have someone buy it for you, or carry it unless a parent or guardian is with you: 90 days to one year suspension. Buying or trying to buy: 180 days.","Si w poko gen 21 an, li ilegal pou w achte alkòl, fè yon moun achte l pou ou, oswa pote l sof si yon paran oswa gadyen avè w: sispansyon 90 jou a yon ane. Achte oswa eseye achte: 180 jou.","Avant 21 ans, il est illégal d'acheter de l'alcool, d'en faire acheter ou d'en transporter sans parent ou tuteur : suspension de 90 jours à un an. Acheter ou tenter d'acheter : 180 jours.","Menores de 21 no pueden comprar alcohol, pedir que se lo compren ni llevarlo salvo con un padre o tutor: suspensión de 90 días a un año. Comprar o intentar comprar: 180 días.")),
   ("li",("Open container law: no open alcoholic drink anywhere inside the vehicle, even if a passenger holds it. Fine $100 to $500; under 21, arrest and suspension.","Lwa sou veso ki louvri: pa gen okenn bwason alkòl ki louvri anndan machin nan, menm si se yon pasaje ki kenbe l. Amann $100 a $500; anba 21 an, arestasyon ak sispansyon.","Loi sur les contenants ouverts : aucune boisson alcoolisée ouverte dans le véhicule, même tenue par un passager. Amende de 100 à 500 $ ; avant 21 ans, arrestation et suspension.","Ley de envases abiertos: ninguna bebida alcohólica abierta dentro del vehículo, aunque la lleve un pasajero. Multa de $100 a $500; menores de 21, arresto y suspensión."))]),
  dict(h=("Marijuana, medicine and other drugs","Mariwana, medikaman ak lòt dwòg","Marijuana, médicaments et autres drogues","Marihuana, medicinas y otras drogas"), pg="74–75", b=[
   ("li",("Driving under the influence of marijuana is still a crime in Massachusetts. Marijuana slows your response to sudden events and harms night vision.","Kondui anba enfliyans mariwana toujou yon krim nan Massachusetts. Mariwana ralanti jan w reyaji devan sa k rive sanzatann epi li fè w wè mal lannwit.","Conduire sous l'influence de la marijuana reste un crime au Massachusetts. La marijuana ralentit la réaction aux imprévus et nuit à la vision de nuit.","Manejar bajo los efectos de la marihuana sigue siendo un delito en Massachusetts. La marihuana hace más lenta la reacción ante imprevistos y daña la visión nocturna.")),
   ("li",("Prescription and over-the-counter medicines, like many cold, allergy or pain medicines, can make you drowsy. You can be charged with OUI on prescription drugs. Read labels and ask a pharmacist.","Medikaman preskripsyon ak medikaman san preskripsyon, tankou anpil medikaman pou grip, alèji oswa doulè, ka ba w dòmi. Yo ka akize w de OUI ak medikaman preskripsyon. Li etikèt yo epi mande yon famasyen.","Les médicaments sur ordonnance ou en vente libre, comme beaucoup contre le rhume, les allergies ou la douleur, peuvent endormir. On peut être accusé d'OUI avec des médicaments prescrits. Lisez les étiquettes et demandez au pharmacien.","Las medicinas con o sin receta, como muchas para el resfriado, la alergia o el dolor, pueden dar sueño. Lo pueden acusar de OUI con medicinas recetadas. Lea las etiquetas y pregunte al farmacéutico.")),
   ("li",("Mixing alcohol with other drugs makes the effects much worse.","Melanje alkòl ak lòt dwòg fè efè yo vin pi grav anpil.","Mélanger l'alcool et d'autres drogues aggrave fortement les effets.","Mezclar alcohol con otras drogas empeora mucho los efectos."))])],
 terms=[("blood alcohol content (BAC)","kantite alkòl nan san (BAC)","taux d'alcool dans le sang (BAC)","contenido de alcohol en la sangre (BAC)"),("operating under the influence (OUI)","kondui anba enfliyans (OUI)","conduite sous influence (OUI)","manejar bajo la influencia (OUI)"),
        ("implied consent","konsantman implisit","consentement implicite","consentimiento implícito"),("zero tolerance","zewo tolerans","tolérance zéro","tolerancia cero"),("open container","veso ki louvri","contenant ouvert","envase abierto")],
 qs=[
  ("p11",1,2,("blood alcohol (BAC)","alkòl nan san (BAC)","taux d'alcool (BAC)","alcohol en la sangre (BAC)"),
   ("What is the blood alcohol limit for a driver under 21 in Massachusetts?","Ki limit alkòl nan san (BAC) pou yon chofè ki poko gen 21 an nan Massachusetts?","Quelle est la limite d'alcool dans le sang pour un conducteur de moins de 21 ans au Massachusetts ?","¿Cuál es el límite de alcohol en la sangre para un conductor menor de 21 en Massachusetts?"),
   ("0.00%","0.00%","0,00 %","0.00 %"),("0.02%","0.02%","0,02 %","0.02 %"),("0.05%","0.05%","0,05 %","0.05 %"),("0.08%","0.08%","0,08 %","0.08 %"),
   ("Drivers under 21 face penalties starting at a BAC of 0.02 (zero tolerance). For drivers 21 and older, the limit is 0.08.","Chofè ki poko gen 21 an jwenn penalite depi BAC 0.02 (zewo tolerans). Pou chofè 21 an oswa plis, limit lan se 0.08.","Les moins de 21 ans sont sanctionnés dès un BAC de 0,02 (tolérance zéro). Pour les 21 ans et plus, la limite est de 0,08.","Los menores de 21 tienen sanciones desde un BAC de 0.02 (tolerancia cero). Para los de 21 o más, el límite es 0.08.")),
  ("pm501",3,2,("legal limit","limit lalwa","limite légale","límite legal"),
   ("For drivers 21 and older, at what BAC are you over the legal limit?","Pou chofè 21 an oswa plis, nan ki BAC ou depase limit lalwa a?","Pour les conducteurs de 21 ans et plus, à quel BAC dépasse-t-on la limite légale ?","Para conductores de 21 años o más, ¿con qué BAC se pasa del límite legal?"),
   ("0.02","0.02","0,02","0.02"),("0.05","0.05","0,05","0.05"),("0.10","0.10","0,10","0.10"),("0.08","0.08","0,08","0.08"),
   ("You are over the legal limit at 0.08 or higher. Even one drink can affect your driving.","Ou depase limit lalwa a depi 0.08 oswa plis. Menm yon sèl vè ka afekte jan w kondui.","Vous dépassez la limite à 0,08 ou plus. Même un seul verre peut nuire à la conduite.","Se pasa del límite con 0.08 o más. Incluso una sola bebida puede afectar su manejo.")),
  ("pm502",0,1,("standard drink","yon vè alkòl","verre standard","bebida estándar"),
   ("Which drinks hold about the same amount of alcohol?","Ki bwason ki gen anviwon menm kantite alkòl?","Quelles boissons contiennent à peu près la même quantité d'alcool ?","¿Qué bebidas tienen casi la misma cantidad de alcohol?"),
   ("A 12-ounce beer, a 5-ounce glass of wine and 1.5 ounces of 80-proof liquor","Yon byè 12 ons, yon vè diven 5 ons ak 1.5 ons kleren 80 pwouf","Une bière de 12 onces, un verre de vin de 5 onces et 1,5 once d'alcool fort à 80 degrés","Una cerveza de 12 onzas, una copa de vino de 5 onzas y 1.5 onzas de licor de 80 grados"),
   ("A 12-ounce beer and a 12-ounce glass of wine","Yon byè 12 ons ak yon vè diven 12 ons","Une bière de 12 onces et un verre de vin de 12 onces","Una cerveza de 12 onzas y una copa de vino de 12 onzas"),
   ("Beer always has less alcohol than liquor, so it is safer","Byè toujou gen mwens alkòl pase kleren, kidonk li pi san danje","La bière a toujours moins d'alcool que l'alcool fort, donc elle est plus sûre","La cerveza siempre tiene menos alcohol que el licor, así que es más segura"),
   ("A mixed drink with soda has no effect on BAC","Yon bwason melanje ak soda pa gen efè sou BAC","Un cocktail avec du soda n'a pas d'effet sur le BAC","Un trago mezclado con refresco no afecta el BAC"),
   ("A 12-ounce beer, a 5-ounce glass of wine and a 1.5-ounce serving of 80-proof liquor (even mixed with soda) each hold about half an ounce of alcohol. The type of drink does not matter; the amount does.","Yon byè 12 ons, yon vè diven 5 ons ak 1.5 ons kleren 80 pwouf (menm melanje ak soda) chak gen anviwon mwatye yon ons alkòl. Kalite bwason an pa enpòtan; se kantite a ki enpòtan.","Une bière de 12 onces, un verre de vin de 5 onces et 1,5 once d'alcool à 80 degrés (même avec du soda) contiennent chacun environ une demi-once d'alcool. Le type de boisson ne compte pas ; la quantité, si.","Una cerveza de 12 onzas, una copa de vino de 5 onzas y 1.5 onzas de licor de 80 grados (aun con refresco) tienen cada una media onza de alcohol. No importa el tipo de bebida; importa la cantidad.")),
  ("pm503",2,1,("sober up","dezoule","dessoûler","quitarse la borrachera"),
   ("What is the only thing that removes alcohol from your body?","Ki sèl bagay ki retire alkòl nan kò w?","Quelle est la seule chose qui élimine l'alcool du corps ?","¿Qué es lo único que elimina el alcohol del cuerpo?"),
   ("Black coffee","Kafe nwa","Le café noir","El café negro"),("A cold shower","Yon douch frèt","Une douche froide","Una ducha fría"),("Time","Tan","Le temps","El tiempo"),("Eating a big meal","Manje yon gwo plat","Un gros repas","Una comida grande"),
   ("Your liver and kidneys need time to process alcohol. Coffee, a cold shower, exercise or food may make you feel more alert but do not lower your BAC.","Fwa w ak ren w bezwen tan pou yo trete alkòl la. Kafe, yon douch frèt, egzèsis oswa manje ka fè w santi w pi reveye, men yo pa bese BAC ou.","Le foie et les reins ont besoin de temps pour éliminer l'alcool. Café, douche froide, exercice ou repas peuvent vous sentir plus alerte mais ne font pas baisser le BAC.","El hígado y los riñones necesitan tiempo para procesar el alcohol. El café, una ducha fría, el ejercicio o la comida pueden hacerlo sentir más despierto, pero no bajan el BAC.")),
  ("pm504",1,1,("BAC","BAC","BAC","BAC"),
   ("About how much can one standard drink raise an average person's BAC?","Anviwon konbyen yon vè alkòl ka fè BAC yon moun nòmal monte?","De combien un verre standard peut-il environ faire monter le BAC d'une personne moyenne ?","¿Más o menos cuánto puede subir el BAC de una persona promedio una bebida estándar?"),
   ("0.08","0.08","0,08","0.08"),("0.02","0.02","0,02","0.02"),("0.10","0.10","0,10","0.10"),("It has no measurable effect","Li pa gen efè ou ka mezire","Aucun effet mesurable","No tiene efecto medible"),
   ("Each standard drink can raise an average person's BAC by about 0.02. More than one drink an hour makes it rise; only time brings it down.","Chak vè ka fè BAC yon moun nòmal monte anviwon 0.02. Plis pase yon vè pa èdtan fè l monte; se tan sèlman ki fè l desann.","Chaque verre standard peut faire monter le BAC d'environ 0,02. Plus d'un verre par heure le fait grimper ; seul le temps le fait baisser.","Cada bebida estándar puede subir el BAC unos 0.02. Más de una por hora lo sube; solo el tiempo lo baja.")),
  ("pm505",0,2,("implied consent","konsantman implisit","consentement implicite","consentimiento implícito"),
   ("What does the Implied Consent Law mean?","Kisa Lwa Konsantman Implisit la vle di?","Que signifie la loi sur le consentement implicite ?","¿Qué significa la Ley de Consentimiento Implícito?"),
   ("By driving, you agree to a breath or blood test if arrested for OUI","Lè w kondui, ou dakò fè yon tès souf oswa san si yo arete w pou OUI","En conduisant, vous acceptez un test d'haleine ou sanguin si vous êtes arrêté pour OUI","Al manejar, acepta una prueba de aliento o sangre si lo arrestan por OUI"),
   ("Police need a court order before any breath or blood test","Lapolis bezwen yon lòd tribinal anvan nenpòt tès souf oswa san","La police a besoin d'une ordonnance du tribunal avant tout test d'haleine ou de sang","La policía necesita una orden judicial antes de cualquier prueba de aliento o de sangre"),
   ("You may refuse the test with no penalty","Ou ka refize tès la san penalite","Vous pouvez refuser le test sans sanction","Puede negarse a la prueba sin sanción"),
   ("Passengers must also be tested","Pasaje yo dwe fè tès tou","Les passagers doivent aussi être testés","Los pasajeros también deben hacerse la prueba"),
   ("Every licensed driver agrees to a breath or blood test if arrested on suspicion of OUI. Refusing brings an immediate license suspension.","Chak chofè ki gen lisans dakò fè yon tès souf oswa san si yo arete l paske yo sispèk OUI. Si w refize, yo sispann lisans ou touswit.","Tout conducteur accepte un test d'haleine ou sanguin s'il est arrêté pour soupçon d'OUI. Refuser entraîne une suspension immédiate.","Todo conductor con licencia acepta una prueba de aliento o sangre si lo arrestan por sospecha de OUI. Negarse trae suspensión inmediata.")),
  ("pm506",2,2,("chemical test","tès chimik","test chimique","prueba química"),
   ("You are 30, with no prior OUI, and you refuse a breath test after an OUI arrest. How long is your license suspended?","Ou gen 30 an, ou pa janm gen OUI, epi ou refize yon tès souf apre yo arete w pou OUI. Pandan konbyen tan lisans ou sispann?","Vous avez 30 ans, sans OUI antérieure, et refusez le test d'haleine après une arrestation pour OUI. Combien de temps de suspension ?","Tiene 30 años, sin OUI previo, y se niega a la prueba de aliento tras un arresto por OUI. ¿Cuánto dura la suspensión?"),
   ("30 days","30 jou","30 jours","30 días"),("No suspension","Pa gen sispansyon","Aucune suspension","Sin suspensión"),("180 days","180 jou","180 jours","180 días"),("Lifetime","Pou tout lavi","À vie","De por vida"),
   ("Refusing a chemical test with no prior OUI means 180 days for drivers over 21. The officer takes your license on the spot.","Refize yon tès chimik san okenn OUI anvan vle di 180 jou pou chofè ki gen plis pase 21 an. Polisye a pran lisans ou sou plas.","Refuser un test chimique sans OUI antérieure entraîne 180 jours pour les plus de 21 ans. Le policier prend votre permis sur-le-champ.","Negarse a la prueba química sin OUI previo significa 180 días para mayores de 21. El policía le quita la licencia en el acto.")),
  ("pm507",1,2,("refusal","refi","refus","negativa"),
   ("A 17-year-old with no prior OUI refuses a chemical test. What is the suspension?","Yon jèn 17 an ki pa janm gen OUI refize yon tès chimik. Konbyen tan sispansyon an?","Un jeune de 17 ans sans OUI antérieure refuse un test chimique. Quelle suspension ?","Un joven de 17 años sin OUI previo se niega a la prueba química. ¿Cuál es la suspensión?"),
   ("180 days","180 jou","180 jours","180 días"),("Three years plus one year","Twazan plis yon ane","Trois ans plus un an","Tres años más un año"),("30 days","30 jou","30 jours","30 días"),("No suspension because of age","Pa gen sispansyon akoz laj li","Aucune suspension à cause de l'âge","Ninguna por su edad"),
   ("Under 18, refusing with no prior OUI means three years plus one year. The extra year can be cut to 180 days with an approved alcohol education program if this is a first OUI case.","Anba 18 an, refize san OUI anvan vle di twazan plis yon ane. Ane anplis la ka desann a 180 jou ak yon pwogram edikasyon sou alkòl apwouve si se premye ka OUI.","Avant 18 ans, refuser sans OUI antérieure vaut trois ans plus un an. L'année supplémentaire peut passer à 180 jours avec un programme d'éducation approuvé s'il s'agit d'une première affaire.","Menores de 18 que se niegan sin OUI previo: tres años más un año. El año extra puede bajar a 180 días con un programa aprobado de educación sobre alcohol si es el primer caso.")),
  ("pm508",3,3,("OUI","OUI","OUI","OUI"),
   ("What is the license suspension for a first OUI conviction?","Konbyen tan yo sispann lisans pou premye kondanasyon OUI?","Quelle est la suspension pour une première condamnation pour OUI ?","¿Cuál es la suspensión por una primera condena por OUI?"),
   ("30 days","30 jou","30 jours","30 días"),("Six months","Sis mwa","Six mois","Seis meses"),("Lifetime","Pou tout lavi","À vie","De por vida"),("One year","Yon ane","Un an","Un año"),
   ("A first OUI brings a one-year suspension, a $500 to $5,000 fine and up to 2½ years in prison. The court may allow an alcohol education program to shorten the suspension.","Premye OUI bay yon sispansyon yon ane, amann $500 a $5,000 ak jiska 2 an edmi prizon. Tribinal la ka pèmèt yon pwogram edikasyon sou alkòl pou diminye sispansyon an.","Une première OUI entraîne un an de suspension, 500 à 5 000 $ d'amende et jusqu'à 2 ans et demi de prison. Le tribunal peut accepter un programme d'éducation pour réduire la suspension.","Un primer OUI trae un año de suspensión, multa de $500 a $5,000 y hasta 2 años y medio de cárcel. El tribunal puede permitir un programa de educación para reducir la suspensión.")),
  ("pm509",0,0,("crash risk","risk aksidan","risque d'accident","riesgo de choque"),
   ("According to the manual, drinking alcohol makes a crash how much more likely?","Dapre mànyèl la, bwè alkòl fè risk aksidan an konbyen fwa pi gwo?","Selon le manuel, boire de l'alcool rend un accident combien de fois plus probable ?","Según el manual, beber alcohol hace un choque ¿cuántas veces más probable?"),
   ("Five times","Senk fwa","Cinq fois","Cinco veces"),("Twice","De fwa","Deux fois","Dos veces"),("It does not change the risk if you are careful","Li pa chanje risk la si w fè atansyon","Cela ne change rien si on est prudent","No cambia el riesgo si tiene cuidado"),("Fifty times","Senkant fwa","Cinquante fois","Cincuenta veces"),
   ("Alcohol makes a crash five times more likely; alcohol combined with marijuana, twelve times more likely.","Alkòl fè risk aksidan an senk fwa pi gwo; alkòl ak mariwana ansanm, douz fwa pi gwo.","L'alcool rend un accident cinq fois plus probable ; avec la marijuana, douze fois plus.","El alcohol hace un choque cinco veces más probable; con marihuana, doce veces más.")),
  ("pm510",2,4,("open container","veso ki louvri","contenant ouvert","envase abierto"),
   ("Your 25-year-old passenger is holding an open can of beer while you drive. What is true?","Pasaje w ki gen 25 an ap kenbe yon bwat byè ki louvri pandan w ap kondui. Kisa ki vre?","Votre passager de 25 ans tient une canette de bière ouverte pendant que vous conduisez. Qu'est-ce qui est vrai ?","Su pasajero de 25 años lleva una lata de cerveza abierta mientras usted maneja. ¿Qué es cierto?"),
   ("It is legal, because you are not the one drinking","Li legal, paske se pa ou k ap bwè","C'est légal, puisque ce n'est pas vous qui buvez","Es legal, porque usted no es quien bebe"),
   ("It is legal if the can is inside a paper bag","Li legal si bwat la nan yon sache papye","C'est légal si la canette est dans un sac en papier","Es legal si la lata está en una bolsa de papel"),
   ("It is illegal: no open alcohol may be inside the vehicle","Sa ilegal: pa dwe gen okenn alkòl ki louvri anndan machin nan","C'est illégal : aucun alcool ouvert ne doit être dans le véhicule","Es ilegal: no puede haber alcohol abierto dentro del vehículo"),
   ("It is illegal only at night","Sa ilegal sèlman lannwit","C'est illégal seulement la nuit","Es ilegal solo de noche"),
   ("You may not have an open alcoholic drink inside the vehicle, even if someone else holds it. The fine is $100 to $500.","Ou pa gen dwa gen yon bwason alkòl ki louvri anndan machin nan, menm si se yon lòt moun ki kenbe l. Amann lan se $100 a $500.","Aucune boisson alcoolisée ouverte dans le véhicule, même tenue par quelqu'un d'autre. Amende de 100 à 500 $.","No puede haber una bebida alcohólica abierta dentro del vehículo, aunque la lleve otra persona. Multa de $100 a $500.")),
  ("pm511",3,4,("underage purchase","achte anba laj","achat avant l'âge","compra siendo menor"),
   ("A 19-year-old tries to buy alcohol. What happens to their license?","Yon jèn 19 an eseye achte alkòl. Kisa k ap rive ak lisans li?","Un jeune de 19 ans essaie d'acheter de l'alcool. Qu'arrive-t-il à son permis ?","Un joven de 19 años intenta comprar alcohol. ¿Qué pasa con su licencia?"),
   ("Nothing, because they did not drive","Anyen, paske li pa t ap kondui","Rien, puisqu'il ne conduisait pas","Nada, porque no estaba manejando"),("A warning only","Yon avètisman sèlman","Un avertissement seulement","Solo una advertencia"),("A 30-day suspension","Yon sispansyon 30 jou","Une suspension de 30 jours","Una suspensión de 30 días"),("A 180-day suspension","Yon sispansyon 180 jou","Une suspension de 180 jours","Una suspensión de 180 días"),
   ("Under 21, buying or trying to buy alcohol brings a 180-day license suspension, even though no driving was involved.","Anba 21 an, achte oswa eseye achte alkòl bay yon sispansyon lisans 180 jou, menm si pa t gen kondui.","Avant 21 ans, acheter ou tenter d'acheter de l'alcool entraîne 180 jours de suspension, même sans conduire.","Menores de 21 que compran o intentan comprar alcohol reciben 180 días de suspensión, aunque no hayan manejado.")),
  ("pm512",1,5,("marijuana","mariwana","marijuana","marihuana"),
   ("Which statement about marijuana and driving in Massachusetts is true?","Ki deklarasyon sou mariwana ak kondui nan Massachusetts ki vre?","Quelle affirmation sur la marijuana et la conduite au Massachusetts est vraie ?","¿Qué afirmación sobre marihuana y manejo en Massachusetts es cierta?"),
   ("It is legal to drive after using it, since it is legal to possess","Li legal pou w kondui apre w fin sèvi avè l, paske posede l legal","On peut conduire après en avoir consommé, puisqu'en posséder est légal","Es legal manejar después de usarla, ya que poseerla es legal"),
   ("Driving under its influence is a crime, with the same penalties as alcohol OUI","Kondui anba enfliyans li se yon krim, ak menm penalite ak OUI alkòl","Conduire sous son influence est un crime, avec les mêmes sanctions que l'OUI liée à l'alcool","Manejar bajo sus efectos es un delito, con las mismas sanciones que el OUI por alcohol"),
   ("It improves night vision","Li amelyore vizyon lannwit","Elle améliore la vision de nuit","Mejora la visión nocturna"),
   ("It only matters for drivers under 21","Li enpòtan sèlman pou chofè ki poko gen 21 an","Cela ne concerne que les moins de 21 ans","Solo importa para menores de 21"),
   ("Some marijuana possession is decriminalized, but driving under its influence is still a criminal offense. The OUI penalty chart applies to marijuana. It also harms night vision.","Posede kèk mariwana pa yon krim ankò, men kondui anba enfliyans li toujou yon krim. Tablo penalite OUI a aplike pou mariwana. Li fè w wè mal lannwit tou.","La possession de marijuana est en partie décriminalisée, mais conduire sous son influence reste un crime. Le barème des sanctions OUI s'applique. Elle nuit aussi à la vision de nuit.","Parte de la posesión de marihuana ya no es delito, pero manejar bajo sus efectos sí lo es. La tabla de sanciones OUI aplica a la marihuana. También daña la visión nocturna.")),
  ("pm513",0,5,("over-the-counter medicine","medikaman san preskripsyon","médicament en vente libre","medicina sin receta"),
   ("You took a cold medicine that warns it can cause drowsiness. What should you do?","Ou pran yon medikaman grip ki di li ka ba w dòmi. Kisa ou dwe fè?","Vous avez pris un médicament contre le rhume qui peut endormir. Que devez-vous faire ?","Tomó una medicina para el resfriado que advierte que da sueño. ¿Qué debe hacer?"),
   ("Not drive; you can be impaired and even charged with OUI","Pa kondui; ou ka pa an kondisyon e yo ka menm akize w de OUI","Ne pas conduire ; vous pouvez être affaibli et même accusé d'OUI","No manejar; puede estar afectado e incluso acusado de OUI"),
   ("Drive, since cold medicine is legal to buy","Kondui, paske medikaman grip legal pou achte","Conduire, puisque le médicament contre le rhume est en vente libre","Manejar, ya que la medicina para el resfriado es legal"),
   ("Drink a strong coffee and then drive","Bwè yon kafe fò epi kondui","Boire un café fort, puis conduire","Tomar un café cargado y luego manejar"),
   ("Drive only on highways","Kondui sèlman sou otowout","Conduire seulement sur l'autoroute","Manejar solo en autopista"),
   ("Many cold, allergy and pain medicines cause drowsiness. It is illegal to drive impaired by any substance, including prescription and over-the-counter drugs.","Anpil medikaman pou grip, alèji ak doulè ba w dòmi. Li ilegal pou w kondui lè yon sibstans, menm medikaman preskripsyon oswa san preskripsyon, afekte w.","Beaucoup de médicaments contre le rhume, les allergies ou la douleur endorment. Il est illégal de conduire affaibli par toute substance, même un médicament prescrit ou en vente libre.","Muchas medicinas para resfriado, alergia o dolor dan sueño. Es ilegal manejar afectado por cualquier sustancia, incluidas medicinas con o sin receta.")),
  ("pm514",2,2,("failed test","echwe tès la","test échoué","prueba fallada"),
   ("A 17-year-old fails a breath test with a BAC of 0.03 (first OUI case). What is the license suspension?","Yon jèn 17 an echwe yon tès souf ak BAC 0.03 (premye ka OUI). Konbyen tan sispansyon an?","Un jeune de 17 ans échoue au test d'haleine avec un BAC de 0,03 (première affaire). Quelle suspension ?","Un joven de 17 años falla la prueba de aliento con BAC de 0.03 (primer caso). ¿Cuál es la suspensión?"),
   ("None, because 0.03 is under the 0.08 limit","Okenn, paske 0.03 pi ba pase limit 0.08 la","Aucune, car 0,03 est sous la limite de 0,08","Ninguna, porque 0.03 está por debajo del límite de 0.08"),("Seven days, then the license comes back automatically","Sèt jou, apre sa lisans lan tounen otomatikman","Sept jours, puis le permis revient automatiquement","Siete días, y luego la licencia vuelve automáticamente"),("30 days plus one year, or 180 days with an alcohol program","30 jou plis yon ane, oswa 180 jou ak yon pwogram sou alkòl","30 jours plus un an, ou 180 jours avec un programme sur l'alcool","30 días más un año, o 180 días con un programa sobre alcohol"),("A lifetime loss of the license","Li pèdi lisans lan pou tout lavi","La perte du permis à vie","La pérdida de la licencia de por vida"),
   ("Under 21, a BAC of 0.02 or higher brings penalties. Under 18: 30 days plus one year, which can be cut to 180 days with a DPH-approved alcohol education program in a first OUI case.","Anba 21 an, yon BAC 0.02 oswa plis bay penalite. Anba 18 an: 30 jou plis yon ane, ki ka desann a 180 jou ak yon pwogram edikasyon sou alkòl DPH apwouve nan yon premye ka OUI.","Avant 21 ans, un BAC de 0,02 ou plus est sanctionné. Avant 18 ans : 30 jours plus un an, réductible à 180 jours avec un programme approuvé par le DPH lors d'une première affaire.","Menores de 21 con BAC de 0.02 o más tienen sanciones. Menores de 18: 30 días más un año, que puede bajar a 180 días con un programa aprobado por el DPH en un primer caso."))]))

# ---------------------------------------------------------------- P6
CH.append(dict(ch=6,
 title=("Signals, signs and pavement markings","Limyè sikilasyon, siy ak liy sou wout","Feux, panneaux et marquages au sol","Semáforos, señales y marcas en el pavimento"),
 bp=("Manual chapter 4, pages 80–92. On the RMV test: rules of the road and identifying road signs. Sign drawings follow the federal sign standards (MUTCD).","Chapit 4 nan mànyèl la, paj 80–92. Nan egzamen RMV a: règ wout yo ak idantifye siy wout yo. Desen siy yo swiv estanda federal pou siy (MUTCD).","Chapitre 4 du manuel, pages 80–92. À l'examen du RMV : règles de la route et identification des panneaux. Les dessins suivent les normes fédérales (MUTCD).","Capítulo 4 del manual, páginas 80–92. En el examen del RMV: reglas del camino e identificación de señales. Los dibujos siguen las normas federales (MUTCD)."),
 sections=[
  dict(h=("Traffic lights","Limyè sikilasyon","Feux de circulation","Semáforos"), pg="80–82", b=[
   ("li",("Steady red: stop. You may turn right on red after a complete stop, yielding to pedestrians and traffic, unless a NO TURN ON RED sign is posted. You may turn left on red only from a one-way street onto another one-way street.","Wouj fiks: kanpe. Ou ka vire adwat nan wouj apre w fin kanpe nèt epi bay pyeton ak machin yo dwa de pasaj, sof si gen yon siy NO TURN ON RED. Ou ka vire agoch nan wouj sèlman soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans.","Rouge fixe : arrêt. Vous pouvez tourner à droite au rouge après un arrêt complet, en cédant aux piétons et aux véhicules, sauf panneau NO TURN ON RED. À gauche au rouge seulement d'une rue à sens unique vers une autre rue à sens unique.","Rojo fijo: alto. Puede girar a la derecha en rojo después de parar por completo y ceder el paso a peatones y vehículos, salvo que haya un letrero NO TURN ON RED. A la izquierda en rojo solo de una calle de un sentido a otra de un sentido.")),
   ("li",("Flashing red: same as a STOP sign. Steady yellow: the light is about to turn red; stop if you can do so safely. Flashing yellow: slow down and go with caution.","Wouj k ap limen etèn: menm jan ak yon siy STOP. Jòn fiks: limyè a pral vin wouj; kanpe si w ka fè l san danje. Jòn k ap limen etèn: ralanti epi pase avèk prekosyon.","Rouge clignotant : comme un panneau STOP. Jaune fixe : le feu va passer au rouge ; arrêtez-vous si vous pouvez le faire sans danger. Jaune clignotant : ralentissez et passez avec prudence.","Rojo intermitente: igual que un PARE. Amarillo fijo: va a cambiar a rojo; pare si puede hacerlo con seguridad. Amarillo intermitente: baje la velocidad y pase con cuidado.")),
   ("li",("Flashing yellow arrow: you may turn, but only when there is a safe gap in oncoming traffic and no pedestrians. Green arrow: a protected turn.","Flèch jòn k ap limen etèn: ou ka vire, men sèlman lè gen yon espas san danje nan machin k ap vini yo epi pa gen pyeton. Flèch vèt: yon vire pwoteje.","Flèche jaune clignotante : vous pouvez tourner, seulement s'il y a un espace sûr dans la circulation en face et aucun piéton. Flèche verte : virage protégé.","Flecha amarilla intermitente: puede girar, solo si hay un espacio seguro en el tráfico de frente y no hay peatones. Flecha verde: giro protegido.")),
   ("li",("Steady green: go, but first yield to vehicles, bicycles and pedestrians already in the road, and never block the intersection. Turning left on a green circle, yield to oncoming traffic.","Vèt fiks: ale, men anvan, bay machin, bisiklèt ak pyeton ki deja nan wout la dwa de pasaj, epi pa janm bloke kafou a. Lè w ap vire agoch sou yon limyè vèt won, bay machin k ap vini yo dwa de pasaj.","Vert fixe : allez, mais cédez d'abord aux véhicules, vélos et piétons déjà sur la chaussée, et ne bloquez jamais l'intersection. En tournant à gauche au feu vert rond, cédez à la circulation en face.","Verde fijo: avance, pero primero ceda el paso a vehículos, bicicletas y peatones que ya están en la vía, y nunca bloquee la intersección. Al girar a la izquierda con luz verde redonda, ceda al tráfico de frente.")),
   ("li",("If a signal is completely dark, treat the intersection as if there were a stop sign in every direction.","Si yon limyè sikilasyon fin etenn nèt, trete kafou a kòmsi te gen yon siy STOP nan chak direksyon.","Si un feu est complètement éteint, traitez l'intersection comme s'il y avait un arrêt dans toutes les directions.","Si un semáforo está totalmente apagado, trate la intersección como si hubiera un PARE en todas las direcciones."))]),
  dict(h=("Pedestrian signals and crossings","Siyal ak pasaj pou pyeton","Signaux et passages pour piétons","Señales y cruces peatonales"), pg="82–83", b=[
   ("li",("Yield to pedestrians entering or using a crosswalk in your path, and never block a crosswalk.","Bay pyeton k ap antre oswa ki sou yon pasaj pyeton nan chemen w dwa de pasaj, epi pa janm bloke yon pasaj pyeton.","Cédez aux piétons qui s'engagent ou se trouvent sur un passage sur votre trajet, et ne bloquez jamais un passage.","Ceda el paso a los peatones que entran o están en un cruce en su camino, y nunca bloquee un cruce.")),
   ("li",("Never pass a vehicle that is stopped or slowing for a pedestrian. Yield to pedestrians when you turn into a driveway or parking lot.","Pa janm depase yon machin ki kanpe oswa k ap ralanti pou yon pyeton. Bay pyeton dwa de pasaj lè w ap vire antre nan yon antre kay oswa yon pakin.","Ne dépassez jamais un véhicule arrêté ou qui ralentit pour un piéton. Cédez aux piétons en entrant dans une allée ou un stationnement.","Nunca rebase un vehículo detenido o que frena por un peatón. Ceda a los peatones al entrar a una entrada de casa o estacionamiento.")),
   ("li",("Pedestrians already in the crosswalk when the countdown reaches zero have the right-of-way.","Pyeton ki deja nan pasaj la lè kontaj la rive a zewo gen dwa de pasaj.","Les piétons déjà engagés quand le compte à rebours atteint zéro ont la priorité.","Los peatones que ya están en el cruce cuando la cuenta llega a cero tienen el derecho de paso.")),
   ("li",("A rectangular rapid flashing beacon (amber lights flashing in an irregular pattern) means stop for pedestrians. At a pedestrian hybrid beacon, solid red means stop; flashing red means stop, then go if clear.","Yon limyè rektang ki kliyote vit (limyè jòn zoranj ki limen etèn san ritm) vle di kanpe pou pyeton. Nan yon limyè ibrid pou pyeton, wouj fiks vle di kanpe; wouj k ap limen etèn vle di kanpe, apre sa ale si pa gen moun.","Un feu rectangulaire à clignotement rapide (lumières ambre irrégulières) signifie arrêt pour les piétons. Avec un feu hybride piéton, rouge fixe : arrêt ; rouge clignotant : arrêt, puis repartir si la voie est libre.","Una baliza rectangular de destello rápido (luces ámbar que destellan sin ritmo) significa parar para peatones. En una baliza híbrida peatonal, rojo fijo es alto; rojo intermitente es parar y luego seguir si está libre."))]),
  dict(h=("Sign colors and shapes","Koulè ak fòm siy yo","Couleurs et formes des panneaux","Colores y formas de las señales"), pg="83–86", b=[
   ("li",("Red: stop or not allowed. Black and white: regulation. Yellow: general warning. Orange: construction or maintenance. Fluorescent yellow-green: school, pedestrian, bicycle and curve warnings.","Wouj: kanpe oswa entèdi. Nwa ak blan: règleman. Jòn: avètisman jeneral. Zoranj: konstriksyon oswa antretyen. Jòn-vèt fliyoresan: avètisman pou lekòl, pyeton, bisiklèt ak koub.","Rouge : arrêt ou interdiction. Noir et blanc : réglementation. Jaune : avertissement général. Orange : travaux ou entretien. Jaune-vert fluorescent : école, piétons, vélos et virages.","Rojo: alto o prohibido. Negro y blanco: reglamentación. Amarillo: advertencia general. Naranja: construcción o mantenimiento. Amarillo verdoso fluorescente: escuela, peatones, bicicletas y curvas.")),
   ("li",("Green: directions. Blue: motorist services such as gas, food and lodging. Brown: parks, recreation and scenic or historic sites.","Vèt: direksyon. Ble: sèvis pou chofè tankou gaz, manje ak lojman. Mawon: pak, lwazi ak sit istorik oswa bèl peyizaj.","Vert : directions. Bleu : services aux automobilistes comme essence, restauration et hébergement. Brun : parcs, loisirs et sites historiques ou panoramiques.","Verde: direcciones. Azul: servicios como gasolina, comida y hospedaje. Café: parques, recreación y sitios históricos o escénicos.")),
   ("li",("A red circle with a diagonal slash means something is prohibited, such as NO U-TURN.","Yon sèk wouj ak yon ba an dyagonal vle di yon bagay entèdi, tankou NO U-TURN (pa fè demi-tou).","Un cercle rouge barré en diagonale signifie une interdiction, comme NO U-TURN (demi-tour interdit).","Un círculo rojo con una raya diagonal significa que algo está prohibido, como NO U-TURN (prohibido dar vuelta en U).")),
   ("li",("Know signs by shape: an eight-sided octagon is STOP; a downward triangle is YIELD; a five-sided pentagon is a school zone or crossing; a diamond is a warning; a round yellow sign warns of a railroad crossing ahead; a sideways pennant marks a no-passing zone.","Konnen siy yo pa fòm yo: yon oktagòn uit kote se STOP; yon triyang ki pwent anba se YIELD (bay dwa de pasaj); yon pantagòn senk kote se zòn oswa pasaj lekòl; yon dyaman se yon avètisman; yon siy jòn won avèti gen yon wout tren devan; yon fanyon kouche make yon zòn kote w pa ka depase.","Reconnaissez les panneaux à leur forme : l'octogone à huit côtés est STOP ; le triangle pointe en bas est YIELD (cédez) ; le pentagone à cinq côtés signale une école ; le losange est un avertissement ; le rond jaune annonce un passage à niveau ; le fanion couché marque une zone de dépassement interdit.","Reconozca las señales por su forma: el octágono de ocho lados es PARE (STOP); el triángulo con la punta hacia abajo es CEDA (YIELD); el pentágono de cinco lados indica zona o cruce escolar; el rombo es advertencia; la señal amarilla redonda avisa de un cruce de tren; el banderín de lado marca zona de no rebasar.")),
   ("li",("Massachusetts state routes use white rectangles with black letters. Interstate routes use a blue, red and white shield.","Wout leta Massachusetts yo sèvi ak rektang blan ak lèt nwa. Wout entèetatik yo sèvi ak yon pwotèj ble, wouj ak blan.","Les routes d'État du Massachusetts utilisent des rectangles blancs à lettres noires. Les autoroutes inter-États, un écusson bleu, rouge et blanc.","Las rutas estatales de Massachusetts usan rectángulos blancos con letras negras. Las interestatales, un escudo azul, rojo y blanco."))], sign="stop"),
  dict(h=("STOP and YIELD","STOP ak YIELD","STOP et YIELD (cédez)","PARE (STOP) y CEDA (YIELD)"), pg="86, 91", b=[
   ("li",("At a STOP sign, come to a complete stop before the stop line or crosswalk. Just slowing down is not enough. Then yield and go carefully.","Nan yon siy STOP, kanpe nèt anvan liy stop la oswa pasaj pyeton an. Ralanti sèlman pa ase. Apre sa bay dwa de pasaj epi ale avèk prekosyon.","À un panneau STOP, arrêtez-vous complètement avant la ligne d'arrêt ou le passage. Ralentir ne suffit pas. Puis cédez et repartez prudemment.","En un PARE, deténgase por completo antes de la línea de alto o el cruce. Solo bajar la velocidad no basta. Luego ceda el paso y avance con cuidado.")),
   ("li",("At an all-way (4-WAY) stop, every vehicle stops, and the first vehicle to reach the intersection goes first.","Nan yon kafou STOP nan tout direksyon (4-WAY), tout machin kanpe, epi premye machin ki rive nan kafou a pase anvan.","À un arrêt toutes directions (4-WAY), tous les véhicules s'arrêtent et le premier arrivé passe en premier.","En un alto en todas las direcciones (4-WAY), todos paran y el primer vehículo en llegar pasa primero.")),
   ("li",("At a YIELD sign, slow down and be ready to stop. Let vehicles, bicyclists and pedestrians go first, and stop completely if traffic requires it. A yield line looks like a row of triangles.","Nan yon siy YIELD, ralanti epi pare pou kanpe. Kite machin, siklis ak pyeton pase anvan, epi kanpe nèt si sikilasyon an mande l. Yon liy yield sanble ak yon ranje triyang.","À un panneau YIELD, ralentissez et préparez-vous à vous arrêter. Laissez passer véhicules, cyclistes et piétons, et arrêtez-vous complètement si nécessaire. Une ligne « cédez » ressemble à une rangée de triangles.","En un CEDA (YIELD), baje la velocidad y esté listo para parar. Deje pasar vehículos, ciclistas y peatones, y pare por completo si hace falta. Una línea de ceda parece una fila de triángulos."))], sign="yield"),
  dict(h=("Railroad crossings and work zones","Wout tren ak zòn travay","Passages à niveau et zones de travaux","Cruces de tren y zonas de obras"), pg="86–89", b=[
   ("li",("A round yellow warning sign comes before a railroad crossing: slow down and be ready to stop. The crossing itself is marked with a white X-shaped crossbuck. Never try to beat a train.","Yon siy avètisman jòn won vini anvan yon wout tren: ralanti epi pare pou kanpe. Kote tren an travèse a make ak yon kwa blan an fòm X. Pa janm eseye pase devan yon tren.","Un panneau jaune rond précède un passage à niveau : ralentissez et préparez-vous à vous arrêter. Le passage lui-même est marqué d'une croix blanche en X. N'essayez jamais de devancer un train.","Una señal amarilla redonda anuncia un cruce de tren: baje la velocidad y esté listo para parar. El cruce se marca con una cruz blanca en forma de X. Nunca intente ganarle al tren.")),
   ("li",("When the lights flash, stop at least 15 feet from the gate or light post and stay stopped until the gate rises and the lights stop. Never drive around a lowered gate.","Lè limyè yo ap limen etèn, kanpe omwen 15 pye de baryè a oswa poto limyè a epi rete kanpe jiskaske baryè a leve epi limyè yo sispann. Pa janm fè wonn yon baryè ki desann.","Quand les feux clignotent, arrêtez-vous à au moins 15 pieds de la barrière ou du poteau, et restez arrêté jusqu'à ce que la barrière se lève et que les feux s'éteignent. Ne contournez jamais une barrière baissée.","Cuando destellan las luces, pare al menos a 15 pies de la barrera o el poste y quédese hasta que suba la barrera y se apaguen las luces. Nunca rodee una barrera baja.")),
   ("li",("In a work zone, the first thing to do is slow down. Obey flaggers and police officers, even when their directions overrule signs or signals.","Nan yon zòn travay, premye bagay pou w fè se ralanti. Obeyi moun ki gen drapo ak polisye yo, menm lè sa yo di diferan de siy oswa limyè yo.","Dans une zone de travaux, la première chose à faire est de ralentir. Obéissez aux signaleurs et aux policiers, même quand leurs ordres contredisent panneaux ou feux.","En una zona de obras, lo primero es bajar la velocidad. Obedezca a los banderilleros y policías, aunque sus indicaciones contradigan señales o semáforos."))], sign="rr"),
  dict(h=("Pavement markings","Liy ak mak sou wout la","Marquages au sol","Marcas en el pavimento"), pg="89–92", b=[
   ("li",("White lines separate lanes going the same way. Broken white: you may cross it to change lanes after signaling. Solid white: do not cross unless you must avoid danger. Double solid white: never cross.","Liy blan separe vwa ki ale menm direksyon. Blan an tire: ou ka travèse l pou chanje vwa apre w fin mete siyal. Blan solid: pa travèse l sof pou evite danje. De liy blan solid: pa janm travèse.","Les lignes blanches séparent les voies de même sens. Blanche discontinue : on peut la franchir pour changer de voie après avoir signalé. Blanche continue : ne pas franchir sauf pour éviter un danger. Double ligne blanche continue : jamais.","Las líneas blancas separan carriles del mismo sentido. Blanca discontinua: puede cruzarla para cambiar de carril tras señalar. Blanca continua: no la cruce salvo para evitar peligro. Doble blanca continua: nunca.")),
   ("li",("Yellow lines separate traffic going opposite ways. You may cross a broken yellow line to pass when safe. If a solid yellow line is on your side, do not cross it. Double solid yellow: no passing; you may cross only to turn left when safe.","Liy jòn separe machin k ap ale nan direksyon opoze. Ou ka travèse yon liy jòn an tire pou depase lè l san danje. Si yon liy jòn solid sou bò kote w, pa travèse l. De liy jòn solid: pa gen depase; ou ka travèse sèlman pou vire agoch lè l san danje.","Les lignes jaunes séparent les sens opposés. On peut franchir une jaune discontinue pour dépasser quand c'est sûr. Si la jaune continue est de votre côté, ne la franchissez pas. Double jaune continue : pas de dépassement ; seulement pour tourner à gauche en sécurité.","Las líneas amarillas separan sentidos opuestos. Puede cruzar una amarilla discontinua para rebasar si es seguro. Si la amarilla continua está de su lado, no la cruce. Doble amarilla continua: no se rebasa; solo se cruza para girar a la izquierda con seguridad.")),
   ("li",("A white diamond marks a special lane, such as HOV or bus only. Red pavement is for buses and transit. Bike lanes are about five feet wide; cars may enter them only to turn on or off the road, after checking for bicyclists. Do not stop on green pavement at a red light.","Yon dyaman blan make yon vwa espesyal, tankou HOV oswa bis sèlman. Wout wouj se pou bis ak transpò piblik. Vwa bisiklèt yo gen anviwon senk pye lajè; machin ka antre ladan yo sèlman pou vire antre oswa soti nan wout la, apre yo fin gade si gen siklis. Pa kanpe sou wout vèt la nan limyè wouj.","Un losange blanc marque une voie spéciale, comme VMO ou autobus seulement. La chaussée rouge est réservée aux autobus et au transport en commun. Les bandes cyclables font environ cinq pieds ; les voitures n'y entrent que pour tourner, après avoir vérifié les cyclistes. Ne vous arrêtez pas sur la chaussée verte au feu rouge.","Un rombo blanco marca un carril especial, como HOV o solo autobuses. El pavimento rojo es para autobuses y transporte público. Los carriles para bicicleta miden unos cinco pies; los autos solo entran para girar, después de buscar ciclistas. No se detenga en pavimento verde con luz roja.")),
   ("li",("Do not drive over or park on a channelizing island unless a police officer tells you to.","Pa kondui sou yon zile ki dirije sikilasyon an ni pake sou li sof si yon polisye di w fè l.","Ne roulez pas et ne stationnez pas sur un îlot de canalisation, sauf ordre d'un policier.","No maneje ni se estacione sobre una isla de canalización salvo que un policía se lo indique."))])],
 terms=[("flashing","k ap limen etèn","clignotant","intermitente"),("crosswalk","pasaj pyeton","passage pour piétons","cruce peatonal"),("YIELD","bay dwa de pasaj (YIELD)","cédez le passage (YIELD)","ceda el paso (YIELD)"),
        ("crossbuck","kwa wout tren","croix de Saint-André","cruz de ferrocarril"),("work zone","zòn travay","zone de travaux","zona de obras"),("no-passing zone","zòn kote w pa ka depase","zone de dépassement interdit","zona de no rebasar")],
 qs=[
  ("p9",0,0,("flashing red light","limyè wouj k ap limen etèn","feu rouge clignotant","luz roja intermitente"),
   ("What does a flashing red traffic light mean?","Kisa yon limyè wouj k ap limen etèn vle di?","Que signifie un feu rouge clignotant ?","¿Qué significa un semáforo en rojo intermitente?"),
   ("Stop completely, then go when it is safe","Kanpe nèt, apre sa ale lè l san danje","Arrêt complet, puis repartir quand c'est sûr","Pare por completo y luego siga cuando sea seguro"),
   ("Slow down and go through","Ralanti epi pase","Ralentir et passer","Baje la velocidad y pase"),
   ("The light is broken; ignore it","Limyè a pete; pa okipe l","Le feu est en panne ; l'ignorer","El semáforo está roto; ignórelo"),
   ("Stop only if cars are coming","Kanpe sèlman si gen machin k ap vini","S'arrêter seulement si des voitures arrivent","Pare solo si vienen autos"),
   ("A flashing red light means the same as a STOP sign: come to a complete stop, follow the right-of-way rules, and go when it is safe.","Yon limyè wouj k ap limen etèn vle di menm bagay ak yon siy STOP: kanpe nèt, swiv règ dwa de pasaj yo, epi ale lè l san danje.","Un feu rouge clignotant équivaut à un STOP : arrêt complet, respect des priorités, puis repartir quand c'est sûr.","Una luz roja intermitente equivale a un PARE: pare por completo, respete el derecho de paso y siga cuando sea seguro.")),
  ("pm601",2,0,("turn on red","vire nan wouj","tourner au rouge","girar en rojo"),
   ("When may you turn right on a steady red light in Massachusetts?","Kilè ou ka vire adwat nan yon limyè wouj fiks nan Massachusetts?","Quand pouvez-vous tourner à droite au feu rouge fixe au Massachusetts ?","¿Cuándo puede girar a la derecha con luz roja fija en Massachusetts?"),
   ("Any time, as long as you slow down and look first","Nenpòt lè, toutotan w ralanti epi gade anvan","À tout moment, du moment que vous ralentissez et regardez d'abord","En cualquier momento, siempre que reduzca la velocidad y mire primero"),
   ("Never; right on red is not allowed in Massachusetts","Janmen; vire adwat nan wouj pa pèmèt nan Massachusetts","Jamais ; tourner à droite au rouge est interdit au Massachusetts","Nunca; girar a la derecha en rojo no se permite en Massachusetts"),
   ("After a full stop and yielding, unless a sign forbids it","Apre w kanpe nèt epi bay priyorite, sof si yon siy entèdi l","Après un arrêt complet en cédant le passage, sauf panneau contraire","Tras detenerse por completo y ceder el paso, salvo que una señal lo prohíba"),
   ("Only when a police officer waves you on","Sèlman lè yon polisye fè w siy pou w pase","Seulement quand un policier vous fait signe de passer","Solo cuando un policía le hace señas para avanzar"),
   ("Right on red is allowed after a complete stop and yielding to pedestrians and other vehicles, but not where a NO TURN ON RED sign is posted.","Ou ka vire adwat nan wouj apre w fin kanpe nèt epi bay pyeton ak lòt machin dwa de pasaj, men pa kote gen yon siy NO TURN ON RED.","Le virage à droite au rouge est permis après un arrêt complet et en cédant aux piétons et véhicules, mais pas là où un panneau NO TURN ON RED est posé.","Girar a la derecha en rojo se permite tras parar por completo y ceder a peatones y vehículos, pero no donde haya un letrero NO TURN ON RED.")),
  ("pm602",1,0,("one-way street","wout yon sèl sans","rue à sens unique","calle de un sentido"),
   ("When is a left turn on a red light allowed in Massachusetts?","Kilè yo pèmèt vire agoch nan yon limyè wouj nan Massachusetts?","Quand le virage à gauche au feu rouge est-il permis au Massachusetts ?","¿Cuándo se permite girar a la izquierda en rojo en Massachusetts?"),
   ("Never, anywhere in Massachusetts","Janmen, okenn kote nan Massachusetts","Jamais, nulle part au Massachusetts","Nunca, en ningún lugar de Massachusetts"),
   ("From a one-way street onto another one-way street, after a complete stop","Soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans, apre w fin kanpe nèt","D'une rue à sens unique vers une autre rue à sens unique, après un arrêt complet","De una calle de un sentido a otra de un sentido, después de parar por completo"),
   ("Any time there is no oncoming traffic, after slowing down","Nenpòt lè pa gen machin k ap vin an fas, apre w ralanti","Chaque fois qu'il n'y a pas de circulation en sens inverse, après avoir ralenti","Siempre que no venga tráfico de frente, después de reducir la velocidad"),
   ("Only at night","Sèlman lannwit","Seulement la nuit","Solo de noche"),
   ("You may turn left on red only from a one-way street onto another one-way street, after stopping and yielding to pedestrians and other vehicles.","Ou ka vire agoch nan wouj sèlman soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans, apre w fin kanpe epi bay pyeton ak lòt machin dwa de pasaj.","Le virage à gauche au rouge n'est permis que d'une rue à sens unique vers une autre, après un arrêt et en cédant aux piétons et véhicules.","Solo puede girar a la izquierda en rojo de una calle de un sentido a otra de un sentido, tras parar y ceder a peatones y vehículos.")),
  ("pm603",3,0,("steady yellow","jòn fiks","jaune fixe","amarillo fijo"),
   ("The light ahead turns steady yellow. What should you do?","Limyè devan w lan vin jòn fiks. Kisa ou dwe fè?","Le feu devant vous passe au jaune fixe. Que faire ?","El semáforo de adelante cambia a amarillo fijo. ¿Qué debe hacer?"),
   ("Speed up to get through","Akselere pou w pase","Accélérer pour passer","Acelerar para pasar"),
   ("Go, because yellow means caution only","Ale, paske jòn vle di prekosyon sèlman","Passer, car le jaune signifie seulement prudence","Avanzar, porque amarillo solo significa precaución"),
   ("Stop even if you are already in the intersection","Kanpe menm si w deja nan kafou a","S'arrêter même si vous êtes déjà dans l'intersection","Parar aunque ya esté en la intersección"),
   ("Stop if you can do so safely","Kanpe si w ka fè l san danje","S'arrêter si on peut le faire sans danger","Parar si puede hacerlo con seguridad"),
   ("A steady yellow means the light is changing from green to red. Stop if it is safe. If you are already stopped, you may not go.","Yon jòn fiks vle di limyè a ap chanje soti vèt pou l vin wouj. Kanpe si l san danje. Si w deja kanpe, ou pa ka ale.","Le jaune fixe annonce le passage du vert au rouge. Arrêtez-vous si c'est sûr. Si vous êtes déjà arrêté, ne repartez pas.","El amarillo fijo indica que cambia de verde a rojo. Pare si es seguro. Si ya está detenido, no puede avanzar.")),
  ("pm604",0,0,("flashing yellow","jòn k ap limen etèn","jaune clignotant","amarillo intermitente"),
   ("What does a flashing yellow light mean?","Kisa yon limyè jòn k ap limen etèn vle di?","Que signifie un feu jaune clignotant ?","¿Qué significa una luz amarilla intermitente?"),
   ("Slow down and go with caution","Ralanti epi pase avèk prekosyon","Ralentir et passer avec prudence","Baje la velocidad y pase con cuidado"),
   ("Stop and wait for green","Kanpe epi tann vèt","S'arrêter et attendre le vert","Pare y espere el verde"),
   ("The road is closed","Wout la fèmen","La route est fermée","El camino está cerrado"),
   ("Pedestrians must stop","Pyeton yo dwe kanpe","Les piétons doivent s'arrêter","Los peatones deben parar"),
   ("A flashing yellow is a warning: proceed with caution, stay alert and look both ways at the intersection.","Yon jòn k ap limen etèn se yon avètisman: pase avèk prekosyon, rete vijilan epi gade de bò nan kafou a.","Le jaune clignotant est un avertissement : passez prudemment, restez attentif et regardez des deux côtés.","El amarillo intermitente es una advertencia: avance con cuidado, atento, y mire a ambos lados.")),
  ("pm605",2,0,("flashing yellow arrow","flèch jòn k ap limen etèn","flèche jaune clignotante","flecha amarilla intermitente"),
   ("You want to turn left and see a flashing yellow arrow. What does it mean?","Ou vle vire agoch epi ou wè yon flèch jòn k ap limen etèn. Kisa sa vle di?","Vous voulez tourner à gauche et voyez une flèche jaune clignotante. Que signifie-t-elle ?","Quiere girar a la izquierda y ve una flecha amarilla intermitente. ¿Qué significa?"),
   ("Oncoming traffic must stop so you can turn","Machin k ap vin an fas yo dwe kanpe pou w ka vire","La circulation en sens inverse doit s'arrêter pour vous laisser tourner","El tráfico de frente debe detenerse para que usted gire"),
   ("Left turns are not allowed until the arrow turns green","Ou pa ka vire agoch jiskaske flèch la tounen vèt","Tourner à gauche est interdit jusqu'à ce que la flèche passe au vert","No se permite girar a la izquierda hasta que la flecha se ponga verde"),
   ("When there is a safe gap, yielding to oncoming traffic and pedestrians","Lè gen yon bon espas, epi w bay machin k ap vini ak pyeton priyorite","Quand il y a un espace sûr, en cédant aux véhicules en face et aux piétons","Cuando hay un espacio seguro, cediendo el paso al tráfico de frente y a los peatones"),
   ("You must turn quickly before the light changes to red","Ou dwe vire vit anvan limyè a tounen wouj","Vous devez tourner vite avant que le feu passe au rouge","Debe girar rápido antes de que la luz cambie a rojo"),
   ("A flashing yellow arrow lets you turn while oncoming traffic has a green light, only when there is an adequate gap and no pedestrians in your path.","Yon flèch jòn k ap limen etèn pèmèt ou vire pandan machin k ap vini yo gen limyè vèt, sèlman lè gen ase espas epi pa gen pyeton nan chemen w.","La flèche jaune clignotante permet de tourner pendant que la circulation en face a le vert, seulement s'il y a un espace suffisant et aucun piéton.","La flecha amarilla intermitente le deja girar mientras el tráfico de frente tiene verde, solo si hay espacio suficiente y no hay peatones.")),
  ("pm606",1,0,("dark signal","limyè etenn","feu éteint","semáforo apagado"),
   ("You reach an intersection where the traffic lights are completely dark. What should you do?","Ou rive nan yon kafou kote limyè sikilasyon yo etenn nèt. Kisa ou dwe fè?","Vous arrivez à une intersection où les feux sont complètement éteints. Que faire ?","Llega a una intersección con los semáforos totalmente apagados. ¿Qué debe hacer?"),
   ("Go through; you have the right-of-way","Pase; ou gen dwa de pasaj","Passer ; vous avez la priorité","Pase; usted tiene el derecho de paso"),
   ("Act as if there is a stop sign in all directions","Aji kòmsi gen yon siy STOP nan tout direksyon","Agir comme s'il y avait un arrêt dans toutes les directions","Actúe como si hubiera un PARE en todas las direcciones"),
   ("Slow to 20 mph and continue","Desann a 20 mph epi kontinye","Ralentir à 20 mph et continuer","Bajar a 20 mph y seguir"),
   ("Turn around","Fè demi-tou","Faire demi-tour","Dar la vuelta"),
   ("If signals are blacked out, be cautious and proceed as though there is a stop sign in all directions. If they flash, follow the rules for flashing lights.","Si limyè yo etenn nèt, fè atansyon epi aji kòmsi gen yon siy STOP nan tout direksyon. Si yo ap limen etèn, swiv règ pou limyè k ap limen etèn yo.","Si les feux sont éteints, soyez prudent et faites comme s'il y avait un arrêt dans toutes les directions. S'ils clignotent, suivez les règles des feux clignotants.","Si los semáforos están apagados, tenga cuidado y avance como si hubiera un PARE en todas las direcciones. Si destellan, siga las reglas de luces intermitentes.")),
  ("pm607",3,0,("oncoming traffic","machin k ap vini","circulation en sens inverse","tráfico de frente"),
   ("You are turning left on a steady green circle (no arrow). Who must you yield to?","W ap vire agoch sou yon limyè vèt won fiks (san flèch). Kiyès ou dwe bay dwa de pasaj?","Vous tournez à gauche au feu vert rond fixe (sans flèche). À qui devez-vous céder ?","Gira a la izquierda con luz verde redonda fija (sin flecha). ¿A quién debe ceder?"),
   ("No one, because green means go","Pèsonn, paske vèt vle di ale","Personne, car le vert veut dire passer","A nadie, porque verde significa avanzar"),
   ("Only to buses","Sèlman ak bis","Seulement aux autobus","Solo a los autobuses"),
   ("Only to vehicles behind you that want to pass","Sèlman machin dèyè w ki vle pase","Seulement aux véhicules derrière vous qui veulent passer","Solo a los vehículos detrás de usted que quieren pasar"),
   ("Oncoming traffic and pedestrians in your path","Machin k ap vini yo ak pyeton ki nan chemen w","À la circulation en face et aux piétons sur votre trajet","Al tráfico de frente y a los peatones en su camino"),
   ("On a green circle, a left turn is not protected: yield to oncoming traffic and pedestrians, and never block the intersection.","Sou yon limyè vèt won, vire agoch pa pwoteje: bay machin k ap vini ak pyeton yo dwa de pasaj, epi pa janm bloke kafou a.","Au feu vert rond, le virage à gauche n'est pas protégé : cédez à la circulation en face et aux piétons, et ne bloquez pas l'intersection.","Con verde redondo, el giro a la izquierda no está protegido: ceda al tráfico de frente y a los peatones, y no bloquee la intersección.")),
  ("pm608",0,1,("pedestrian beacon","limyè pou pyeton","feu pour piétons","baliza peatonal"),
   ("At a mid-block crosswalk, amber lights are flashing rapidly in an irregular pattern. What must you do?","Nan yon pasaj pyeton nan mitan yon blòk, limyè jòn zoranj ap limen etèn vit san ritm. Kisa ou dwe fè?","À un passage au milieu d'un pâté de maisons, des feux ambre clignotent rapidement et irrégulièrement. Que devez-vous faire ?","En un cruce a mitad de cuadra, luces ámbar destellan rápido y sin ritmo. ¿Qué debe hacer?"),
   ("Stop for pedestrians","Kanpe pou pyeton yo","S'arrêter pour les piétons","Parar para los peatones"),
   ("Speed up before someone steps out","Akselere anvan yon moun travèse","Accélérer avant qu'un piéton s'engage","Acelerar antes de que alguien cruce"),
   ("Honk and continue","Klaksonnen epi kontinye","Klaxonner et continuer","Tocar el claxon y seguir"),
   ("Ignore it unless there is also a red light","Pa okipe l sof si gen yon limyè wouj tou","L'ignorer sauf s'il y a aussi un feu rouge","Ignorarla salvo que también haya luz roja"),
   ("That is a rectangular rapid flashing beacon. A pedestrian has activated it: you must stop for pedestrians while it flashes.","Se yon limyè rektang ki kliyote vit. Yon pyeton limen l: ou dwe kanpe pou pyeton pandan l ap limen etèn.","C'est un feu rectangulaire à clignotement rapide. Un piéton l'a activé : arrêtez-vous pour les piétons tant qu'il clignote.","Es una baliza rectangular de destello rápido. Un peatón la activó: debe parar para los peatones mientras destella.")),
  ("pm609",2,1,("countdown timer","kontaj","compte à rebours","cuenta regresiva"),
   ("The pedestrian countdown reaches zero while a person is still in the crosswalk. Who has the right-of-way?","Kontaj pyeton an rive a zewo pandan yon moun toujou nan pasaj la. Kiyès ki gen dwa de pasaj?","Le compte à rebours piéton atteint zéro alors qu'une personne est encore sur le passage. Qui a la priorité ?","La cuenta regresiva peatonal llega a cero con una persona aún en el cruce. ¿Quién tiene el derecho de paso?"),
   ("You, because your light is green","Ou menm, paske limyè w vèt","Vous, car votre feu est vert","Usted, porque su luz está verde"),
   ("Whoever honks first","Moun ki klaksonnen anvan","Celui qui klaxonne en premier","Quien toque el claxon primero"),
   ("The pedestrian already in the crosswalk","Pyeton ki deja nan pasaj la","Le piéton déjà engagé","El peatón que ya está en el cruce"),
   ("Turning vehicles only","Machin k ap vire yo sèlman","Seulement les véhicules qui tournent","Solo los vehículos que giran"),
   ("Pedestrians who are already in the crosswalk when the countdown reaches zero have the right-of-way. Let them finish crossing.","Pyeton ki deja nan pasaj la lè kontaj la rive a zewo gen dwa de pasaj. Kite yo fin travèse.","Les piétons déjà engagés quand le compte à rebours atteint zéro ont la priorité. Laissez-les finir de traverser.","Los peatones que ya están en el cruce cuando la cuenta llega a cero tienen el derecho de paso. Déjelos terminar de cruzar.")),
  ("pm610",1,1,("crosswalk","pasaj pyeton","passage pour piétons","cruce peatonal"),
   ("The car in the lane next to you has stopped at a crosswalk. What should you do?","Machin ki nan vwa bò kote w lan kanpe nan yon pasaj pyeton. Kisa ou dwe fè?","La voiture dans la voie voisine s'est arrêtée à un passage pour piétons. Que faire ?","El auto del carril de al lado se detuvo en un cruce peatonal. ¿Qué debe hacer?"),
   ("Pass it carefully, watching the crosswalk","Pase l ak prekosyon, pandan w ap gade pasaj pyeton an","Le dépasser prudemment en surveillant le passage piéton","Rebasarlo con cuidado, mirando el cruce peatonal"),
   ("Slow down and stop: never pass a vehicle stopped for a pedestrian","Ralanti epi kanpe: pa janm depase yon machin ki kanpe pou yon pyeton","Ralentir et s'arrêter : ne jamais dépasser un véhicule arrêté pour un piéton","Bajar la velocidad y parar: nunca rebase un vehículo detenido por un peatón"),
   ("Honk to warn the pedestrian","Klaksonnen pou avèti pyeton an","Klaxonner pour avertir le piéton","Tocar el claxon para avisar al peatón"),
   ("Change to another lane and continue at the same speed","Chanje liy epi kontinye ak menm vitès la","Changer de voie et continuer à la même vitesse","Cambiar de carril y seguir a la misma velocidad"),
   ("A stopped car may be hiding a pedestrian. Never pass a vehicle that is stopped or slowing for a pedestrian.","Yon machin ki kanpe ka ap kache yon pyeton. Pa janm depase yon machin ki kanpe oswa k ap ralanti pou yon pyeton.","Une voiture arrêtée peut cacher un piéton. Ne dépassez jamais un véhicule arrêté ou qui ralentit pour un piéton.","Un auto detenido puede ocultar a un peatón. Nunca rebase un vehículo que se detiene o frena por un peatón.")),
  ("pm611",3,2,("orange sign","siy zoranj","panneau orange","señal naranja"),
   ("What do orange signs mean?","Kisa siy zoranj yo vle di?","Que signifient les panneaux orange ?","¿Qué significan las señales naranjas?"),
   ("Gas, food and other motorist services","Gaz, manje ak lòt sèvis pou chofè","Essence, restauration et autres services","Gasolina, comida y otros servicios"),
   ("Recreation areas","Zòn lwazi","Zones de loisirs","Áreas recreativas"),
   ("School zones and school crossings","Zòn lekòl ak travèse lekòl","Zones scolaires et passages d'écoliers","Zonas escolares y cruces escolares"),
   ("Construction or maintenance ahead","Konstriksyon oswa antretyen devan","Travaux ou entretien à venir","Construcción o mantenimiento adelante"),
   ("Orange signs warn of construction or maintenance work. Slow down and watch for workers.","Siy zoranj avèti gen travay konstriksyon oswa antretyen. Ralanti epi veye travayè yo.","Les panneaux orange signalent des travaux ou de l'entretien. Ralentissez et faites attention aux travailleurs.","Las señales naranjas avisan de construcción o mantenimiento. Baje la velocidad y cuide a los trabajadores."),"work"),
  ("pm612",0,2,("brown sign","siy mawon","panneau brun","señal café"),
   ("A brown sign usually points you to:","Yon siy mawon anjeneral montre w:","Un panneau brun indique généralement :","Una señal café normalmente lo dirige a:"),
   ("A park, recreation area or historic site","Yon pak, yon zòn lwazi oswa yon sit istorik","Un parc, une zone de loisirs ou un site historique","Un parque, área recreativa o sitio histórico"),
   ("A hospital or emergency room","Yon lopital oswa yon sal ijans","Un hôpital ou des urgences","Un hospital o una sala de emergencias"),
   ("A highway exit or an interstate route","Yon sòti gran wout oswa yon wout ant eta","Une sortie d'autoroute ou une route inter-États","Una salida de autopista o una ruta interestatal"),
   ("A detour around construction","Yon detou pou kontoune travay","Une déviation pour contourner des travaux","Un desvío para rodear una obra"),
   ("Brown signs lead to public recreation areas, state and national parks, points of interest and scenic sites. Blue signs show services; green signs give directions.","Siy mawon mennen nan zòn lwazi piblik, pak leta ak nasyonal, kote enteresan ak bèl peyizaj. Siy ble montre sèvis; siy vèt bay direksyon.","Les panneaux bruns mènent aux loisirs publics, parcs d'État et nationaux, points d'intérêt et sites panoramiques. Les bleus indiquent les services ; les verts, les directions.","Las señales café llevan a áreas recreativas, parques estatales y nacionales, puntos de interés y sitios escénicos. Las azules indican servicios; las verdes, direcciones.")),
  ("pm613",1,2,("prohibited","entèdi","interdit","prohibido"),
   ("What does this sign mean?","Kisa siy sa a vle di?","Que signifie ce panneau ?","¿Qué significa esta señal?"),
   ("U-turn allowed ahead","Ou ka fè demi-tou pi devan","Demi-tour permis plus loin","Vuelta en U permitida adelante"),
   ("No U-turn","Pa fè demi-tou","Demi-tour interdit","Prohibido dar vuelta en U"),
   ("Road curves sharply","Wout la fè yon koub sere","Virage serré","Curva cerrada"),
   ("Detour ahead","Detou devan","Déviation à venir","Desvío adelante"),
   ("A red circle with a diagonal slash means the action shown is prohibited. Here: no U-turns.","Yon sèk wouj ak yon ba an dyagonal vle di aksyon ki montre a entèdi. Isit la: pa fè demi-tou.","Un cercle rouge barré signifie que l'action montrée est interdite. Ici : demi-tour interdit.","Un círculo rojo con raya diagonal significa que la acción mostrada está prohibida. Aquí: no dar vuelta en U."),"nouturn"),
  ("pm614",3,3,("STOP sign","siy STOP","panneau STOP","señal de PARE"),
   ("You come to this sign. What must you do?","Ou rive devan siy sa a. Kisa ou dwe fè?","Vous arrivez à ce panneau. Que devez-vous faire ?","Llega a esta señal. ¿Qué debe hacer?"),
   ("Slow down, look both ways, and go if no one is coming","Ralanti, gade de bò, epi ale si pa gen pèsonn k ap vini","Ralentir, regarder des deux côtés et passer si personne ne vient","Reducir la velocidad, mirar a ambos lados y seguir si no viene nadie"),
   ("Stop only if a pedestrian is waiting to cross","Kanpe sèlman si gen yon pyeton k ap tann pou travèse","S'arrêter seulement si un piéton attend pour traverser","Detenerse solo si un peatón espera para cruzar"),
   ("Stop in the middle of the crosswalk, where you can see best","Kanpe nan mitan pasaj pyeton an, kote w ka wè pi byen","S'arrêter au milieu du passage piéton, là où l'on voit le mieux","Detenerse en medio del cruce peatonal, donde se ve mejor"),
   ("Stop completely before the line or crosswalk, yield, then go","Kanpe nèt anvan liy lan oswa pasaj pyeton an, bay priyorite, apre sa ale","S'arrêter complètement avant la ligne ou le passage, céder, puis repartir","Detenerse por completo antes de la línea o el cruce, ceder el paso y seguir"),
   ("The eight-sided red sign always means a complete stop, before any crosswalk or stop line. Just slowing down is not enough.","Siy wouj uit kote a toujou vle di kanpe nèt, anvan pasaj pyeton oswa liy stop la. Ralanti sèlman pa ase.","Le panneau rouge à huit côtés impose toujours un arrêt complet avant le passage ou la ligne d'arrêt. Ralentir ne suffit pas.","La señal roja de ocho lados siempre exige parar por completo antes del cruce o la línea de alto. Solo bajar la velocidad no basta."),"stop"),
  ("pm615",2,2,("school zone","zòn lekòl","zone scolaire","zona escolar"),
   ("What does this five-sided sign warn you about?","Ki sa siy senk kote sa a avèti w?","De quoi ce panneau à cinq côtés vous avertit-il ?","¿De qué le advierte esta señal de cinco lados?"),
   ("A railroad crossing ahead","Yon travèse tren devan","Un passage à niveau devant","Un cruce de tren adelante"),
   ("A hospital zone","Yon zòn lopital","Une zone d'hôpital","Una zona de hospital"),
   ("A school zone or school crossing","Yon zòn lekòl oswa yon pasaj lekòl","Une zone ou un passage scolaire","Una zona o cruce escolar"),
   ("A zone where passing is not allowed","Yon zòn kote w pa gen dwa depase","Une zone où il est interdit de dépasser","Una zona donde no se permite rebasar"),
   ("The pentagon shape marks a school zone or school crossing. The speed limit near schools is 20 mph; watch for children and crossing guards.","Fòm pantagòn nan make yon zòn oswa yon pasaj lekòl. Limit vitès toupre lekòl se 20 mph; veye timoun ak gad travèse yo.","Le pentagone signale une zone ou un passage scolaire. La limite près des écoles est de 20 mph ; attention aux enfants et brigadiers.","El pentágono marca una zona o cruce escolar. El límite cerca de escuelas es 20 mph; cuide a los niños y a los guardias de cruce."),"school"),
  ("pm616",0,4,("railroad crossing","wout tren","passage à niveau","cruce de tren"),
   ("You see this round yellow sign. What is ahead?","Ou wè siy jòn won sa a. Kisa ki devan?","Vous voyez ce panneau jaune rond. Qu'y a-t-il devant ?","Ve esta señal amarilla redonda. ¿Qué hay adelante?"),
   ("A railroad crossing: slow down and be ready to stop","Yon wout tren: ralanti epi pare pou kanpe","Un passage à niveau : ralentir et se préparer à s'arrêter","Un cruce de tren: baje la velocidad y esté listo para parar"),
   ("A traffic circle (rotary) ahead: yield to cars in it","Yon wonpwen devan: kite machin ki ladan l pase","Un rond-point devant : céder aux voitures qui y sont","Una rotonda adelante: ceder el paso a los autos que circulan"),
   ("A hospital","Yon lopital","Un hôpital","Un hospital"),
   ("A crossroad ahead with a stop sign","Yon kafou devan ak yon siy stop","Un carrefour devant avec un panneau stop","Un cruce adelante con señal de alto"),
   ("A round warning sign usually comes before a railroad crossing. Slow down, look and listen, and never try to beat a train.","Yon siy avètisman won konn vini anvan yon wout tren. Ralanti, gade epi koute, epi pa janm eseye pase devan yon tren.","Un panneau rond précède généralement un passage à niveau. Ralentissez, regardez, écoutez, et n'essayez jamais de devancer un train.","Una señal redonda suele anunciar un cruce de tren. Baje la velocidad, mire y escuche, y nunca intente ganarle al tren."),"rr"),
  ("pm617",1,2,("warning sign","siy avètisman","panneau d'avertissement","señal de advertencia"),
   ("What does this yellow diamond sign mean?","Kisa siy jòn an fòm dyaman sa a vle di?","Que signifie ce panneau jaune en losange ?","¿Qué significa esta señal amarilla en forma de rombo?"),
   ("Turn right now, at the next street","Vire adwat kounye a, nan pwochen lari a","Tourner à droite maintenant, à la prochaine rue","Girar a la derecha ahora, en la próxima calle"),
   ("The road curves to the right ahead: slow down","Wout la fè yon koub adwat pi devan: ralanti","La route tourne à droite plus loin : ralentir","El camino tiene una curva a la derecha adelante: baje la velocidad"),
   ("The right lane ends ahead: merge left","Liy dwat la fini devan: antre agoch","La voie de droite se termine : se rabattre à gauche","El carril derecho termina adelante: incorporarse a la izquierda"),
   ("No right turn","Pa vire adwat","Virage à droite interdit","Prohibido girar a la derecha"),
   ("Yellow diamond signs warn of hazards or changes ahead. This one warns that the road curves right. Slow down and obey the sign.","Siy jòn an fòm dyaman avèti gen danje oswa chanjman pi devan. Sa a avèti wout la fè yon koub adwat. Ralanti epi obeyi siy la.","Les losanges jaunes avertissent d'un danger ou d'un changement. Celui-ci annonce un virage à droite. Ralentissez et respectez-le.","Los rombos amarillos advierten de peligros o cambios adelante. Este avisa una curva a la derecha. Baje la velocidad y obedezca."),"curve"),
  ("pm618",2,3,("all-way stop","STOP nan tout direksyon","arrêt toutes directions","alto en todas las direcciones"),
   ("At a four-way stop, two cars arrive at different times. Who goes first?","Nan yon kafou STOP nan kat direksyon, de machin rive nan lè diferan. Kiyès ki pase anvan?","À un arrêt à quatre directions, deux voitures arrivent à des moments différents. Qui passe en premier ?","En un alto de cuatro direcciones llegan dos autos en momentos distintos. ¿Quién pasa primero?"),
   ("The larger vehicle, because it needs more time to stop","Machin ki pi gwo a, paske l bezwen plis tan pou l kanpe","Le plus gros véhicule, car il lui faut plus de temps pour s'arrêter","El vehículo más grande, porque necesita más tiempo para frenar"),
   ("The car going straight","Machin k ap ale tou dwat la","Celle qui va tout droit","El que sigue derecho"),
   ("The first car to reach the intersection","Premye machin ki rive nan kafou a","La première voiture arrivée à l'intersection","El primer auto en llegar a la intersección"),
   ("The car on the left","Machin ki sou bò goch la","La voiture de gauche","El auto de la izquierda"),
   ("At an all-way (4-WAY) stop, every vehicle must stop, and the first vehicle to reach the intersection has the right-of-way.","Nan yon kafou STOP nan tout direksyon (4-WAY), chak machin dwe kanpe, epi premye machin ki rive nan kafou a gen dwa de pasaj.","À un arrêt toutes directions (4-WAY), chaque véhicule s'arrête et le premier arrivé a la priorité.","En un alto en todas las direcciones (4-WAY), todos deben parar y el primero en llegar tiene el derecho de paso.")),
  ("pm619",3,3,("YIELD sign","siy YIELD","panneau YIELD (cédez)","señal de CEDA"),
   ("What does this sign require?","Kisa siy sa a mande?","Qu'exige ce panneau ?","¿Qué exige esta señal?"),
   ("A complete stop every time","Kanpe nèt chak fwa","Un arrêt complet chaque fois","Parar por completo siempre"),
   ("Speed up so you can merge before the other cars","Akselere pou w ka antre anvan lòt machin yo","Accélérer pour s'insérer avant les autres voitures","Acelerar para incorporarse antes que los demás autos"),
   ("Nothing, if you are turning right onto the other road","Anyen, si w ap vire adwat sou lòt wout la","Rien, si vous tournez à droite sur l'autre route","Nada, si va a girar a la derecha hacia el otro camino"),
   ("Slow down, let others go first, and stop if traffic requires it","Ralanti, kite lòt yo pase anvan, epi kanpe si sikilasyon an mande l","Ralentir, laisser passer les autres et s'arrêter si nécessaire","Bajar la velocidad, dejar pasar a otros y parar si hace falta"),
   ("At a YIELD sign, slow down and be ready to stop. Let vehicles, bicyclists and pedestrians go before you, and stop completely if traffic requires it.","Nan yon siy YIELD, ralanti epi pare pou kanpe. Kite machin, siklis ak pyeton pase anvan w, epi kanpe nèt si sikilasyon an mande l.","Au panneau YIELD, ralentissez et préparez-vous à vous arrêter. Laissez passer véhicules, cyclistes et piétons, et arrêtez-vous complètement si nécessaire.","En CEDA, baje la velocidad y esté listo para parar. Deje pasar vehículos, ciclistas y peatones, y pare por completo si hace falta."),"yield"),
  ("pm620",1,4,("railroad gate","baryè wout tren","barrière de passage à niveau","barrera del tren"),
   ("The lights are flashing at a railroad crossing. Where must you stop?","Limyè yo ap limen etèn nan yon wout tren. Ki kote ou dwe kanpe?","Les feux clignotent à un passage à niveau. Où devez-vous vous arrêter ?","Las luces destellan en un cruce de tren. ¿Dónde debe parar?"),
   ("Right on the tracks","Dirèkteman sou ray yo","Sur les rails","Sobre las vías"),
   ("At least 15 feet from the gate or light post","Omwen 15 pye de baryè a oswa poto limyè a","À au moins 15 pieds de la barrière ou du poteau","Al menos a 15 pies de la barrera o el poste"),
   ("You may drive around the gate if no train is visible","Ou ka fè wonn baryè a si w pa wè tren","On peut contourner la barrière si aucun train n'est visible","Puede rodear la barrera si no ve un tren"),
   ("Five feet from the tracks","Senk pye de ray yo","À cinq pieds des rails","A cinco pies de las vías"),
   ("Stop at least 15 feet before the light post or gate and stay stopped until the gate rises and the lights stop. Never drive around a lowered gate.","Kanpe omwen 15 pye anvan poto limyè a oswa baryè a epi rete kanpe jiskaske baryè a leve epi limyè yo sispann. Pa janm fè wonn yon baryè ki desann.","Arrêtez-vous à au moins 15 pieds avant le poteau ou la barrière et restez arrêté jusqu'à ce qu'elle se lève et que les feux s'éteignent. Ne contournez jamais une barrière baissée.","Pare al menos a 15 pies antes del poste o la barrera y quédese hasta que suba y se apaguen las luces. Nunca rodee una barrera baja.")),
  ("pm621",0,4,("work zone","zòn travay","zone de travaux","zona de obras"),
   ("You are approaching a work zone. What is the first thing you must do?","W ap pwoche yon zòn travay. Ki premye bagay ou dwe fè?","Vous approchez d'une zone de travaux. Quelle est la première chose à faire ?","Se acerca a una zona de obras. ¿Qué es lo primero que debe hacer?"),
   ("Slow down","Ralanti","Ralentir","Bajar la velocidad"),
   ("Change lanes immediately","Chanje vwa touswit","Changer de voie immédiatement","Cambiar de carril de inmediato"),
   ("Turn on your high beams","Limen gwo limyè ou","Allumer les feux de route","Encender las luces altas"),
   ("Look at the work being done","Gade travay y ap fè a","Regarder les travaux","Mirar el trabajo que hacen"),
   ("The first thing to do in a work zone is slow down, then look for guidance on how to get through safely. Do not be distracted by the work.","Premye bagay pou w fè nan yon zòn travay se ralanti, apre sa gade enstriksyon pou w pase san danje. Pa kite travay la distrè w.","Dans une zone de travaux, il faut d'abord ralentir, puis chercher les indications pour passer en sécurité. Ne vous laissez pas distraire.","En una zona de obras, lo primero es bajar la velocidad y luego buscar indicaciones para pasar seguro. No se distraiga con el trabajo.")),
  ("pm622",3,4,("flagger","moun ki gen drapo","signaleur","banderillero"),
   ("A police officer directing traffic waves you through a red light. What do you do?","Yon polisye k ap dirije sikilasyon an fè w siy pase nan yon limyè wouj. Kisa ou fè?","Un policier qui dirige la circulation vous fait signe de passer au feu rouge. Que faites-vous ?","Un policía que dirige el tránsito le indica pasar con luz roja. ¿Qué hace?"),
   ("Wait for the green light","Tann limyè vèt la","Attendre le feu vert","Esperar la luz verde"),
   ("Honk to ask if he is sure","Klaksonnen pou mande l si l sèten","Klaxonner pour lui demander s'il est sûr","Tocar el claxon para preguntar si está seguro"),
   ("Turn right instead","Vire adwat pito","Tourner à droite à la place","Girar a la derecha en su lugar"),
   ("Follow the officer's direction","Swiv enstriksyon polisye a","Suivre l'indication du policier","Seguir la indicación del policía"),
   ("You must always obey a traffic officer or flagger, even when their directions overrule signs, signals or pavement markings.","Ou dwe toujou obeyi yon polisye sikilasyon oswa moun ki gen drapo, menm lè sa yo di diferan de siy, limyè oswa liy sou wout la.","Il faut toujours obéir à l'agent de circulation ou au signaleur, même si ses ordres contredisent panneaux, feux ou marquages.","Siempre debe obedecer a un agente de tránsito o banderillero, aunque contradiga señales, semáforos o marcas.")),
  ("pm623",2,5,("broken white line","liy blan an tire","ligne blanche discontinue","línea blanca discontinua"),
   ("What does a broken white line between two lanes mean?","Kisa yon liy blan an tire ant de vwa vle di?","Que signifie une ligne blanche discontinue entre deux voies ?","¿Qué significa una línea blanca discontinua entre dos carriles?"),
   ("Traffic goes in opposite directions; pass only when clear","Machin yo ale nan direksyon opoze; depase sèlman lè wout la klè","La circulation va dans des sens opposés ; dépasser seulement si la voie est libre","El tráfico va en sentidos opuestos; rebasar solo si está despejado"),
   ("You may never cross it, even after signaling","Ou pa ka janm travèse l, menm apre w fin bay siyal","Vous ne pouvez jamais la franchir, même après avoir signalé","Nunca puede cruzarla, ni siquiera después de señalizar"),
   ("Same direction; you may cross to change lanes when safe, after signaling","Menm direksyon; ou ka travèse l pou chanje liy lè l san danje, apre w bay siyal","Même sens ; vous pouvez la franchir pour changer de voie quand c'est sûr, après avoir signalé","Mismo sentido; puede cruzarla para cambiar de carril cuando sea seguro, tras señalizar"),
   ("It marks a lane for buses and taxis only","Li make yon liy pou bis ak taksi sèlman","Elle indique une voie réservée aux bus et aux taxis","Marca un carril solo para autobuses y taxis"),
   ("Broken white lines separate lanes going the same direction. Once you have signaled and it is safe, you may cross to change lanes.","Liy blan an tire separe vwa ki ale menm direksyon. Lè w fin mete siyal epi l san danje, ou ka travèse pou chanje vwa.","Les lignes blanches discontinues séparent des voies de même sens. Après avoir signalé, et si c'est sûr, vous pouvez la franchir.","Las líneas blancas discontinuas separan carriles del mismo sentido. Tras señalar, y si es seguro, puede cruzarla para cambiar de carril.")),
  ("pm624",1,5,("double solid yellow","de liy jòn solid","double ligne jaune continue","doble línea amarilla continua"),
   ("When may you cross double solid yellow lines?","Kilè ou ka travèse de liy jòn solid?","Quand pouvez-vous franchir une double ligne jaune continue ?","¿Cuándo puede cruzar una doble línea amarilla continua?"),
   ("To pass a slow vehicle","Pou depase yon machin k ap mache dousman","Pour dépasser un véhicule lent","Para rebasar un vehículo lento"),
   ("Only to turn left, when it is safe","Sèlman pou vire agoch, lè l san danje","Seulement pour tourner à gauche, en sécurité","Solo para girar a la izquierda, cuando sea seguro"),
   ("Any time there is no oncoming traffic","Nenpòt lè pa gen machin k ap vini","Chaque fois qu'il n'y a pas de circulation en face","Siempre que no venga tráfico de frente"),
   ("Never","Pa janm","Jamais","Nunca"),
   ("Two solid yellow lines prohibit passing. You may cross them only to turn left when it is safe.","De liy jòn solid entèdi depase. Ou ka travèse yo sèlman pou vire agoch lè l san danje.","La double ligne jaune continue interdit le dépassement. On ne la franchit que pour tourner à gauche en sécurité.","La doble amarilla continua prohíbe rebasar. Solo se cruza para girar a la izquierda cuando es seguro.")),
  ("pm625",0,5,("solid yellow line","liy jòn solid","ligne jaune continue","línea amarilla continua"),
   ("There is a solid yellow line on your side and a broken yellow line on the other side. May you pass?","Gen yon liy jòn solid sou bò kote w ak yon liy jòn an tire sou lòt bò a. Èske w ka depase?","Il y a une ligne jaune continue de votre côté et une discontinue de l'autre. Pouvez-vous dépasser ?","Hay una línea amarilla continua de su lado y una discontinua del otro. ¿Puede rebasar?"),
   ("No; you may not cross when the solid line is on your side","Non; ou pa ka travèse lè liy solid la sou bò kote w","Non ; impossible quand la ligne continue est de votre côté","No; no puede cruzar cuando la continua está de su lado"),
   ("Yes, if the road ahead looks clear","Wi, si wout devan an sanble klè","Oui, si la route devant semble dégagée","Sí, si el camino adelante se ve despejado"),
   ("Yes, but only at night","Wi, men sèlman lannwit","Oui, mais seulement la nuit","Sí, pero solo de noche"),
   ("Yes, if the car ahead is going under the speed limit","Wi, si machin devan an ap woule pi ba pase limit vitès la","Oui, si la voiture devant roule sous la limite de vitesse","Sí, si el auto de adelante va por debajo del límite"),
   ("If the solid yellow line is closer to you, you cannot cross. If the broken line is closer to you, you may cross to pass when it is safe.","Si liy jòn solid la pi pre w, ou pa ka travèse. Si liy an tire a pi pre w, ou ka travèse pou depase lè l san danje.","Si la ligne continue est de votre côté, vous ne pouvez pas la franchir. Si c'est la discontinue, vous pouvez dépasser quand c'est sûr.","Si la amarilla continua está más cerca de usted, no puede cruzar. Si la discontinua está más cerca, puede rebasar cuando sea seguro.")),
  ("pm626",3,5,("bicycle lane","vwa bisiklèt","bande cyclable","carril para bicicletas"),
   ("When may a car drive in a marked bicycle lane?","Kilè yon machin ka kondui nan yon vwa bisiklèt ki make?","Quand une voiture peut-elle rouler dans une bande cyclable ?","¿Cuándo puede un auto ir por un carril para bicicletas marcado?"),
   ("To pass slow traffic on the right when the lane is empty","Pou depase machin ki dousman sou bò dwat lè liy lan vid","Pour dépasser la circulation lente par la droite quand la voie est vide","Para rebasar el tráfico lento por la derecha cuando el carril está vacío"),
   ("To park for a few minutes with your flashers on","Pou estasyone kèk minit ak limyè ijans ou limen","Pour stationner quelques minutes avec les feux de détresse","Para estacionarse unos minutos con las intermitentes puestas"),
   ("Any time no bicycles are there, if you go slowly","Nenpòt lè pa gen bisiklèt, si w ale dousman","Chaque fois qu'il n'y a pas de vélos, si vous roulez lentement","Siempre que no haya bicicletas, si va despacio"),
   ("Only when turning on or off the road, after checking for bicyclists","Sèlman lè w ap vire antre oswa soti nan wout la, apre w fin gade si gen siklis","Seulement pour tourner, après avoir vérifié les cyclistes","Solo al girar para entrar o salir del camino, después de buscar ciclistas"),
   ("Motor vehicles may use a bike lane only when turning on or off the road. Look carefully for bicyclists and cross with care.","Machin yo ka sèvi ak yon vwa bisiklèt sèlman lè y ap vire antre oswa soti nan wout la. Gade byen si gen siklis epi travèse avèk prekosyon.","Les véhicules n'utilisent la bande cyclable que pour tourner. Vérifiez soigneusement la présence de cyclistes et traversez prudemment.","Los vehículos solo usan el carril de bicicletas al girar para entrar o salir. Busque ciclistas con cuidado y cruce con precaución.")),
  ("pm627",2,5,("high occupancy vehicle (HOV)","veyikil ak plizyè pasaje (HOV)","véhicule multioccupant (VMO)","vehículo de alta ocupación (HOV)"),
   ("A white diamond is painted in a lane. What does it mean?","Gen yon dyaman blan pentire nan yon vwa. Kisa sa vle di?","Un losange blanc est peint dans une voie. Que signifie-t-il ?","Hay un rombo blanco pintado en un carril. ¿Qué significa?"),
   ("The lane ends soon; merge now","Liy lan pral fini; antre kounye a","La voie se termine bientôt ; se rabattre maintenant","El carril termina pronto; incorpórese ahora"),
   ("Railroad crossing ahead","Wout tren devan","Passage à niveau à venir","Cruce de tren adelante"),
   ("A special lane, such as HOV or bus only","Yon vwa espesyal, tankou HOV oswa bis sèlman","Une voie spéciale, comme VMO ou autobus seulement","Un carril especial, como HOV o solo autobuses"),
   ("A passing lane for faster cars","Yon liy pou depase pou machin ki pi vit","Une voie de dépassement pour les voitures plus rapides","Un carril de rebase para autos más rápidos"),
   ("A white diamond means a special lane restriction, like high-occupancy vehicles (carpools) only or buses only.","Yon dyaman blan vle di yon vwa ki gen restriksyon espesyal, tankou machin ak plizyè pasaje sèlman (kovwatiraj) oswa bis sèlman.","Un losange blanc indique une voie réservée, par exemple aux véhicules multioccupants (covoiturage) ou aux autobus.","Un rombo blanco indica un carril restringido, como solo vehículos de alta ocupación (viaje compartido) o solo autobuses.")),
  ("pm628",0,3,("yield line","liy yield","ligne « cédez le passage »","línea de ceda"),
   ("What does a yield line painted across the road look like?","Kijan yon liy yield pentire atravè wout la sanble?","À quoi ressemble une ligne « cédez le passage » peinte sur la chaussée ?","¿Cómo se ve una línea de ceda pintada en el camino?"),
   ("A row of triangles","Yon ranje triyang","Une rangée de triangles","Una fila de triángulos"),
   ("A single solid white line","Yon sèl liy blan solid","Une seule ligne blanche continue","Una sola línea blanca continua"),
   ("A double yellow line","Yon liy jòn doub","Une double ligne jaune","Una línea amarilla doble"),
   ("A white diamond","Yon dyaman blan","Un losange blanc","Un rombo blanco"),
   ("A yield line looks like a series of triangles painted side by side. A stop line is one solid white line. Stop behind them when a sign, signal or pedestrian requires it.","Yon liy yield sanble ak yon seri triyang pentire youn bò lòt. Yon liy stop se yon sèl liy blan solid. Kanpe dèyè yo lè yon siy, yon limyè oswa yon pyeton mande l.","Une ligne « cédez » ressemble à une série de triangles côte à côte. Une ligne d'arrêt est une seule ligne blanche continue. Arrêtez-vous derrière quand un panneau, un feu ou un piéton l'exige.","La línea de ceda parece una serie de triángulos uno junto a otro. La línea de alto es una sola línea blanca continua. Pare detrás cuando lo exija una señal, semáforo o peatón."))]))

# ---------------------------------------------------------------- P7
CH.append(dict(ch=7,
 title=("Speed, lanes, turns and right-of-way","Vitès, vwa, vire ak dwa de pasaj","Vitesse, voies, virages et priorité","Velocidad, carriles, giros y derecho de paso"),
 bp=("Manual chapter 4, pages 78–80 and 93–111. On the RMV test: rules of the road.","Chapit 4 nan mànyèl la, paj 78–80 ak 93–111. Nan egzamen RMV a: règ wout yo.","Chapitre 4 du manuel, pages 78–80 et 93–111. À l'examen du RMV : règles de la route.","Capítulo 4 del manual, páginas 78–80 y 93–111. En el examen del RMV: reglas del camino."),
 sections=[
  dict(h=("Speed limits","Limit vitès","Limites de vitesse","Límites de velocidad"), pg="78–80", b=[
   ("li",("The basic speed law: never drive faster than is safe for traffic, road, weather and visibility, even below the posted limit. Driving 40 mph in a heavy rainstorm on a 50 mph highway can get you a ticket.","Lwa debaz sou vitès: pa janm kondui pi vit pase sa ki san danje pou sikilasyon, wout, tan ak vizibilite, menm anba limit ki afiche a. Kondui 40 mph nan yon gwo lapli sou yon otowout 50 mph ka fè w jwenn yon kontravansyon.","La règle de base : ne roulez jamais plus vite que ce qui est sûr selon la circulation, la route, la météo et la visibilité, même sous la limite. Rouler à 40 mph sous une forte pluie sur une route à 50 peut valoir une contravention.","La ley básica de velocidad: nunca maneje más rápido de lo seguro para el tráfico, el camino, el clima y la visibilidad, aun bajo el límite. Manejar a 40 mph en un aguacero en una carretera de 50 puede costarle una multa.")),
   ("li",("Unless posted otherwise: 20 mph in a school zone, 30 mph in a thickly settled or business district (25 mph in some towns), 40 mph outside those districts, and 50 mph on a highway outside them. Interstates are posted 50 to 65 mph.","Sof si yon siy di yon lòt bagay: 20 mph nan yon zòn lekòl, 30 mph nan yon zòn ki gen anpil kay oswa zòn biznis (25 mph nan kèk vil), 40 mph andeyò zòn sa yo, ak 50 mph sou yon otowout andeyò yo. Otowout entèetatik yo gen limit 50 a 65 mph.","Sauf indication : 20 mph en zone scolaire, 30 mph en zone densément bâtie ou commerciale (25 dans certaines villes), 40 mph en dehors, et 50 mph sur une grande route en dehors. Les autoroutes inter-États affichent de 50 à 65 mph.","Salvo que se indique otra cosa: 20 mph en zona escolar, 30 mph en zona densamente poblada o comercial (25 en algunos pueblos), 40 mph fuera de ellas y 50 mph en carretera fuera de ellas. Las interestatales marcan de 50 a 65 mph.")),
   ("li",("A thickly settled district has buildings less than 200 feet apart for a quarter mile or more. Minimum speeds: 40 mph on the Massachusetts Turnpike and 20 mph in the Boston Harbor tunnels.","Yon zòn ki gen anpil kay se kote bilding yo mwens pase 200 pye youn de lòt sou yon ka mil oswa plis. Vitès minimòm: 40 mph sou Massachusetts Turnpike ak 20 mph nan tinèl Boston Harbor yo.","Une zone densément bâtie a des bâtiments à moins de 200 pieds les uns des autres sur un quart de mille ou plus. Vitesses minimales : 40 mph sur le Massachusetts Turnpike et 20 mph dans les tunnels du port de Boston.","Una zona densamente poblada tiene edificios a menos de 200 pies entre sí por un cuarto de milla o más. Velocidades mínimas: 40 mph en el Massachusetts Turnpike y 20 mph en los túneles del puerto de Boston.")),
   ("li",("Speed kills pedestrians: hit at 20 mph, 13% are seriously injured or killed; at 30 mph, 40%; at 40 mph, 73%.","Vitès touye pyeton: si yon machin frape yo a 20 mph, 13% blese grav oswa mouri; a 30 mph, 40%; a 40 mph, 73%.","La vitesse tue les piétons : percutés à 20 mph, 13 % sont gravement blessés ou tués ; à 30 mph, 40 % ; à 40 mph, 73 %.","La velocidad mata peatones: atropellados a 20 mph, el 13 % sufre heridas graves o muere; a 30 mph, el 40 %; a 40 mph, el 73 %."))]),
  dict(h=("Signals, lanes and highways","Siyal, vwa ak otowout","Signaux, voies et autoroutes","Señales, carriles y autopistas"), pg="93–96", b=[
   ("li",("Signal to change lanes, turn, pull away from or over to the curb, and enter or exit a highway. Before any move: check mirrors and blind spot, signal, then move. Turn the signal off afterward.","Mete siyal pou chanje vwa, vire, soti oswa rale bò twotwa a, ak antre oswa soti sou otowout. Anvan nenpòt mouvman: gade miwa yo ak kwen avèg la, mete siyal, apre sa fè mouvman an. Etenn siyal la apre.","Signalez pour changer de voie, tourner, quitter le trottoir ou vous y ranger, et entrer ou sortir d'une autoroute. Avant chaque manœuvre : rétroviseurs et angle mort, signal, puis manœuvre. Éteignez le signal ensuite.","Señale para cambiar de carril, girar, salir de la orilla o estacionarse, y entrar o salir de una autopista. Antes de moverse: revise espejos y punto ciego, señale y luego muévase. Apague la direccional al terminar.")),
   ("li",("If your signals do not work, use hand signals through the driver's window: arm straight out for a left turn, arm bent up for a right turn, arm bent down to slow or stop.","Si siyal yo pa mache, fè siyal ak men nan fenèt chofè a: bra lonje tou dwat pou vire agoch, bra pliye anlè pou vire adwat, bra pliye anba pou ralanti oswa kanpe.","Si vos clignotants ne marchent pas, faites les signaux de la main par la fenêtre du conducteur : bras tendu pour tourner à gauche, bras plié vers le haut pour la droite, bras plié vers le bas pour ralentir ou s'arrêter.","Si sus direccionales no funcionan, use señales con la mano por la ventana del conductor: brazo extendido para girar a la izquierda, doblado hacia arriba para la derecha, doblado hacia abajo para bajar la velocidad o parar.")),
   ("li",("On roads with two or more lanes your way, drive in the right lane unless you are passing, turning left, or the lane is blocked. Never change lanes in an intersection.","Sou wout ki gen de vwa oswa plis nan direksyon w, kondui nan vwa dwat la sof si w ap depase, w ap vire agoch, oswa vwa a bloke. Pa janm chanje vwa nan mitan yon kafou.","Sur les routes à deux voies ou plus dans votre sens, roulez à droite sauf pour dépasser, tourner à gauche ou si la voie est bloquée. Ne changez jamais de voie dans une intersection.","En caminos con dos o más carriles en su sentido, use el derecho salvo para rebasar, girar a la izquierda o si está bloqueado. Nunca cambie de carril dentro de una intersección.")),
   ("li",("Highways: yield to traffic already on the highway and match its speed when you enter. Signal at least 500 feet before an exit. If you miss your exit, never stop or back up: take the next one. With three or more lanes, the right lane is slower, the middle faster, the left for passing.","Otowout: bay machin ki deja sou otowout la dwa de pasaj epi mache menm vitès ak yo lè w ap antre. Mete siyal omwen 500 pye anvan yon sòti. Si w rate sòti w, pa janm kanpe ni fè bak: pran pwochen an. Ak twa vwa oswa plis, vwa dwat la pi lan, vwa mitan an pi vit, vwa goch la pou depase.","Autoroutes : cédez à la circulation déjà sur l'autoroute et adoptez sa vitesse en entrant. Signalez au moins 500 pieds avant une sortie. Si vous manquez la sortie, ne vous arrêtez jamais et ne reculez pas : prenez la suivante. Avec trois voies ou plus : droite plus lente, milieu plus rapide, gauche pour dépasser.","Autopistas: ceda al tráfico que ya está en la autopista e iguale su velocidad al entrar. Señale al menos 500 pies antes de una salida. Si pasa su salida, nunca pare ni retroceda: tome la siguiente. Con tres carriles o más: derecho más lento, del medio más rápido, izquierdo para rebasar.")),
   ("li",("On a long drive, stop and stretch every two hours or 100 miles. If you break down on a highway, move as far from traffic as you can and stay in your vehicle.","Nan yon long vwayaj, kanpe epi detire w chak dezè oswa chak 100 mil. Si machin nan tonbe an pàn sou otowout, rale toutotan ou kapab lwen machin yo epi rete andedan machin ou.","Sur un long trajet, arrêtez-vous et étirez-vous toutes les deux heures ou tous les 100 milles. En panne sur l'autoroute, éloignez-vous le plus possible de la circulation et restez dans votre véhicule.","En un viaje largo, pare y estírese cada dos horas o 100 millas. Si se descompone en la autopista, aléjese lo más posible del tráfico y quédese dentro del vehículo."))]),
  dict(h=("Turns","Vire","Virages","Giros"), pg="97–99", b=[
   ("li",("Signal at least 100 feet before a turn, or 500 feet on a highway. Slow down, check mirrors and your blind spot, yield when needed, and turn into the proper lane.","Mete siyal omwen 100 pye anvan yon vire, oswa 500 pye sou otowout. Ralanti, gade miwa ak kwen avèg ou, bay dwa de pasaj lè sa nesesè, epi vire antre nan bon vwa a.","Signalez au moins 100 pieds avant un virage, ou 500 pieds sur l'autoroute. Ralentissez, vérifiez rétroviseurs et angle mort, cédez si nécessaire, et tournez dans la bonne voie.","Señale al menos 100 pies antes de girar, o 500 en autopista. Baje la velocidad, revise espejos y punto ciego, ceda cuando haga falta y gire hacia el carril correcto.")),
   ("li",("Turn right from the far right lane and left from the lane closest to the center. Do not swing wide. Once you start a turn, finish it.","Vire adwat soti nan vwa ki pi adwat la, epi agoch soti nan vwa ki pi pre mitan an. Pa louvri twò laj. Lè w kòmanse yon vire, fini l.","Tournez à droite depuis la voie de droite et à gauche depuis la voie la plus proche du centre. Ne vous écartez pas. Un virage commencé doit être terminé.","Gire a la derecha desde el carril de la extrema derecha y a la izquierda desde el más cercano al centro. No se abra. Si empieza un giro, termínelo.")),
   ("li",("U-turns only from the lane closest to the center line, never where you or others cannot see 500 feet, and never where a NO U-TURN sign is posted. You may not drive along in a shared center left-turn lane.","Demi-tou sèlman soti nan vwa ki pi pre liy mitan an, pa janm kote ou menm oswa lòt moun pa ka wè 500 pye, e pa janm kote gen yon siy NO U-TURN. Ou pa ka kondui tou dwat nan yon vwa mitan ki pou vire agoch.","Demi-tour seulement depuis la voie la plus proche de la ligne centrale, jamais là où on ne voit pas à 500 pieds, ni sous un panneau NO U-TURN. On ne roule pas dans une voie centrale de virage à gauche.","Vuelta en U solo desde el carril más cercano a la línea central, nunca donde no se vea a 500 pies ni con un letrero NO U-TURN. No puede circular por un carril central compartido para giros a la izquierda."))]),
  dict(h=("Right-of-way","Dwa de pasaj","Priorité","Derecho de paso"), pg="99–101", b=[
   ("li",("Always yield to pedestrians in the roadway, including those already in the crosswalk when your light turns green. Stop for a blind pedestrian with a white cane or guide dog and stay stopped until they cross; do not honk or wave them on (the White Cane Law).","Toujou bay pyeton ki nan wout la dwa de pasaj, ansanm ak sa ki deja nan pasaj la lè limyè w vin vèt. Kanpe pou yon pyeton avèg ki gen yon baton blan oswa yon chen gid epi rete kanpe jiskaske l travèse; pa klaksonnen ni fè l siy pase (Lwa Baton Blan an).","Cédez toujours aux piétons sur la chaussée, y compris ceux déjà engagés quand votre feu passe au vert. Arrêtez-vous pour un piéton aveugle avec canne blanche ou chien-guide et restez arrêté jusqu'à ce qu'il ait traversé ; ne klaxonnez pas et ne lui faites pas signe (loi de la canne blanche).","Ceda siempre a los peatones en la vía, incluso a los que ya están en el cruce cuando su luz cambia a verde. Pare por un peatón ciego con bastón blanco o perro guía y quédese hasta que cruce; no toque el claxon ni le haga señas (Ley del Bastón Blanco).")),
   ("li",("At an intersection with no signs or signals, yield to vehicles coming from your right. At a four-way stop, go in the order you stopped; if two arrive together, yield to the vehicle on your right.","Nan yon kafou ki pa gen siy ni limyè, bay machin k ap vini sou bò dwat ou dwa de pasaj. Nan yon kafou STOP nan kat direksyon, pase nan lòd nou kanpe a; si de rive ansanm, bay machin sou bò dwat ou a dwa de pasaj.","À une intersection sans panneau ni feu, cédez aux véhicules venant de votre droite. À un arrêt à quatre directions, passez dans l'ordre d'arrêt ; si deux arrivent ensemble, cédez à celui de droite.","En una intersección sin señales ni semáforos, ceda a los vehículos que vienen por su derecha. En un alto de cuatro direcciones, pasen en el orden en que pararon; si llegan dos a la vez, ceda al de la derecha.")),
   ("li",("Turning left, yield to oncoming vehicles, vehicles already in the intersection, and pedestrians or bicyclists in your path. Coming out of a driveway, private road or unpaved road, stop and yield. A two-lane road meeting a divided highway or a road with three or more lanes must yield.","Lè w ap vire agoch, bay machin k ap vini, machin ki deja nan kafou a, ak pyeton oswa siklis ki nan chemen w dwa de pasaj. Lè w ap soti nan yon antre kay, yon wout prive oswa yon wout tè, kanpe epi bay dwa de pasaj. Yon wout de vwa ki rankontre yon otowout divize oswa yon wout twa vwa oswa plis dwe bay dwa de pasaj.","En tournant à gauche, cédez aux véhicules en face, à ceux déjà dans l'intersection, et aux piétons ou cyclistes sur votre trajet. En sortant d'une allée, d'un chemin privé ou non pavé, arrêtez-vous et cédez. Une route à deux voies qui croise une route divisée ou à trois voies ou plus doit céder.","Al girar a la izquierda, ceda a los vehículos de frente, a los que ya están en la intersección y a peatones o ciclistas en su camino. Al salir de una entrada, camino privado o de tierra, pare y ceda. Un camino de dos carriles que llega a una carretera dividida o de tres carriles o más debe ceder.")),
   ("li",("Courtesy crashes: if someone waves you through stopped traffic, oncoming traffic still has the right-of-way. Turn only when you can see it is clear.","Aksidan politès: si yon moun fè w siy pase nan mitan machin ki kanpe, machin k ap vini yo toujou gen dwa de pasaj. Vire sèlman lè w wè wout la klè.","Accidents de courtoisie : si quelqu'un vous fait signe de passer entre des véhicules arrêtés, la circulation en face garde la priorité. Tournez seulement si vous voyez que c'est libre.","Choques de cortesía: si alguien le hace señas para pasar entre autos detenidos, el tráfico de frente sigue teniendo el derecho de paso. Gire solo cuando vea que está libre."))]),
  dict(h=("Rotaries and roundabouts","Kafou won ak wonpwen piti","Carrefours giratoires","Rotondas y glorietas"), pg="101–102", b=[
   ("li",("Traffic in a rotary moves counterclockwise. Yield to vehicles already in the rotary and to pedestrians, and use your right signal to exit.","Sikilasyon nan yon kafou won fè wonn nan sans kontrè egui yon revèy. Bay machin ki deja nan kafou won an ak pyeton yo dwa de pasaj, epi sèvi ak siyal dwat ou pou w soti.","Dans un carrefour giratoire, on circule dans le sens inverse des aiguilles d'une montre. Cédez aux véhicules déjà dans l'anneau et aux piétons, et signalez à droite pour sortir.","En una rotonda se circula en sentido contrario a las agujas del reloj. Ceda a los vehículos que ya están dentro y a los peatones, y use la direccional derecha para salir.")),
   ("li",("Multi-lane rotary with no signs: to go a quarter turn or straight, enter from the right lane and stay right. For a three-quarter turn or U-turn, enter from the left lane, travel in the inner lane, and exit to the right lane.","Kafou won ak plizyè vwa san siy: pou fè yon ka vire oswa ale tou dwat, antre nan vwa dwat la epi rete adwat. Pou fè twa ka vire oswa demi-tou, antre nan vwa goch la, kondui nan vwa anndan an, epi soti nan vwa dwat la.","Giratoire à plusieurs voies sans panneau : pour un quart de tour ou tout droit, entrez par la voie de droite et restez à droite. Pour trois quarts de tour ou un demi-tour, entrez par la gauche, roulez dans la voie intérieure et sortez dans la voie de droite.","Rotonda de varios carriles sin señales: para un cuarto de vuelta o seguir derecho, entre por el carril derecho y quédese a la derecha. Para tres cuartos de vuelta o vuelta en U, entre por el izquierdo, circule por el interior y salga al carril derecho.")),
   ("li",("Missed your exit? Go around again. Never stop in a rotary. Roundabouts are smaller and need speeds of 25 mph or less.","Ou rate sòti w? Fè yon lòt wonn. Pa janm kanpe nan yon kafou won. Wonpwen piti yo (roundabouts) pi piti epi yo mande vitès 25 mph oswa mwens.","Sortie manquée ? Refaites un tour. Ne vous arrêtez jamais dans un giratoire. Les petits ronds-points exigent 25 mph ou moins.","¿Se pasó la salida? Dé otra vuelta. Nunca pare dentro de una rotonda. Las glorietas son más pequeñas y piden 25 mph o menos."))]),
  dict(h=("Passing","Depase","Dépassement","Rebasar"), pg="102–104", b=[
   ("li",("Pass on the left, only when necessary and safe, and never above the speed limit. Never pass on a shoulder, breakdown lane or sidewalk.","Depase sou bò goch, sèlman lè sa nesesè epi san danje, e pa janm pi vit pase limit vitès la. Pa janm depase sou bò wout la, nan vwa pàn nan oswa sou twotwa.","Dépassez par la gauche, seulement si nécessaire et sûr, et jamais au-delà de la limite. Ne dépassez jamais sur l'accotement, la voie de panne ou le trottoir.","Rebase por la izquierda, solo si es necesario y seguro, y nunca por encima del límite. Nunca rebase por el acotamiento, el carril de emergencia ni la acera.")),
   ("li",("Crossing a broken yellow line to pass, you must see at least 400 feet ahead. Move back when you can see the passed vehicle's headlights in your mirror, and before any oncoming vehicle comes within 200 feet.","Lè w travèse yon liy jòn an tire pou depase, ou dwe ka wè omwen 400 pye devan. Retounen nan vwa w lè w ka wè limyè devan machin ou depase a nan miwa w, e anvan nenpòt machin k ap vini rive a 200 pye de ou.","Pour franchir une ligne jaune discontinue et dépasser, vous devez voir au moins 400 pieds devant. Rabattez-vous quand vous voyez les phares du véhicule dépassé dans le rétroviseur, et avant qu'un véhicule en face soit à 200 pieds.","Para cruzar una amarilla discontinua y rebasar, debe ver al menos 400 pies adelante. Regrese cuando vea en el espejo las luces del vehículo rebasado, y antes de que uno de frente esté a 200 pies.")),
   ("li",("Passing on the right is allowed only when the vehicle ahead is turning left, on a one-way street, or on a road where all traffic goes one way. When someone passes you, slow down and keep right; do not speed up.","Ou ka depase sou bò dwat sèlman lè machin devan an ap vire agoch, sou yon wout yon sèl sans, oswa sou yon wout kote tout machin ale nan menm direksyon. Lè yon moun ap depase w, ralanti epi rete adwat; pa akselere.","Dépasser par la droite n'est permis que si le véhicule devant tourne à gauche, sur une rue à sens unique ou sur une route à sens unique. Quand on vous dépasse, ralentissez et restez à droite ; n'accélérez pas.","Rebasar por la derecha solo se permite si el de adelante gira a la izquierda, en calle de un sentido o en un camino donde todo el tráfico va en un sentido. Si lo rebasan, baje la velocidad y manténgase a la derecha; no acelere.")),
   ("li",("Move-over law: approaching a stopped emergency, highway or recovery vehicle with flashing lights, slow down and, on a road with two or more lanes your way, move over to leave an empty lane beside it. Do not pass vehicles that are stopped or turning.","Lwa «move-over»: lè w ap pwoche yon veyikil ijans, otowout oswa remòkaj ki kanpe ak limyè k ap limen etèn, ralanti epi, sou yon wout ki gen de vwa oswa plis nan direksyon w, deplase pou kite yon vwa vid bò kote l. Pa depase machin ki kanpe oswa k ap vire.","Loi « move-over » : en approchant d'un véhicule d'urgence, d'entretien ou de dépannage arrêté avec feux clignotants, ralentissez et, s'il y a deux voies ou plus dans votre sens, changez de voie pour laisser une voie libre à côté. Ne dépassez pas les véhicules arrêtés ou qui tournent.","Ley de moverse: al acercarse a un vehículo de emergencia, de carretera o de grúa detenido con luces intermitentes, baje la velocidad y, si hay dos o más carriles en su sentido, cámbiese para dejar un carril libre a su lado. No rebase vehículos detenidos o que giran."))]),
  dict(h=("Parking","Pakin","Stationnement","Estacionamiento"), pg="109–111", b=[
   ("li",("Before leaving your car: stop the motor, set the parking brake, lock the ignition, take the key and lock the door. Park within 12 inches of the curb and leave at least 12 feet of road clear.","Anvan w kite machin ou: etenn motè a, mete fren pakin nan, bloke kle kontak la, pran kle a epi fèmen pòt la a kle. Pake nan 12 pous de twotwa a epi kite omwen 12 pye wout klè.","Avant de quitter la voiture : coupez le moteur, serrez le frein de stationnement, verrouillez le contact, prenez la clé et fermez à clé. Garez-vous à 12 pouces du trottoir au plus et laissez au moins 12 pieds de chaussée libre.","Antes de dejar el auto: apague el motor, ponga el freno de estacionamiento, bloquee el encendido, saque la llave y cierre con llave. Estaciónese a no más de 12 pulgadas de la acera y deje al menos 12 pies de camino libre.")),
   ("li",("On a hill, set the parking brake and turn your wheels: downhill with a curb, toward the curb; uphill with a curb, away from the curb; with no curb, toward the edge of the road.","Sou yon mòn, mete fren pakin nan epi vire wou yo: desann ak twotwa, nan direksyon twotwa a; monte ak twotwa, nan direksyon opoze twotwa a; san twotwa, nan direksyon bò wout la.","En pente, serrez le frein et braquez les roues : en descente avec trottoir, vers le trottoir ; en montée avec trottoir, à l'opposé du trottoir ; sans trottoir, vers le bord de la route.","En una pendiente, ponga el freno y gire las ruedas: cuesta abajo con acera, hacia la acera; cuesta arriba con acera, hacia afuera; sin acera, hacia la orilla del camino.")),
   ("li",("Do not park within 20 feet of an intersection, within 10 feet of a fire hydrant, in a crosswalk, in front of a driveway, in a bike lane or bus stop ($100), or in a disability space without a placard ($300 first offense).","Pa pake nan 20 pye yon kafou, nan 10 pye yon bouch ponpye, nan yon pasaj pyeton, devan yon antre kay, nan yon vwa bisiklèt oswa yon arè bis ($100), ni nan yon plas pou moun ki gen andikap san plak ($300 premye fwa).","Ne stationnez pas à moins de 20 pieds d'une intersection, à moins de 10 pieds d'une borne d'incendie, sur un passage piéton, devant une entrée, dans une bande cyclable ou un arrêt d'autobus (100 $), ni sur une place handicapée sans vignette (300 $ la première fois).","No se estacione a menos de 20 pies de una intersección, a menos de 10 pies de un hidrante, en un cruce peatonal, frente a una entrada, en carril de bicicletas o parada de autobús ($100), ni en un espacio para discapacitados sin placa ($300 la primera vez)."))])],
 terms=[("thickly settled district","zòn ki gen anpil kay","zone densément bâtie","zona densamente poblada"),("blind spot","kwen avèg","angle mort","punto ciego"),("rotary","kafou won","carrefour giratoire","rotonda"),
        ("U-turn","demi-tou","demi-tour","vuelta en U"),("move-over law","lwa «move-over»","loi « move-over »","ley de moverse de carril"),("fire hydrant","bouch ponpye","borne d'incendie","hidrante")],
 qs=[
  ("pm701",2,0,("basic speed law","lwa debaz sou vitès","règle de base de la vitesse","ley básica de velocidad"),
   ("The posted limit is 50 mph, but there is a heavy rainstorm. Which is true?","Limit ki afiche a se 50 mph, men gen yon gwo lapli. Kisa ki vre?","La limite est de 50 mph, mais il y a une forte pluie. Qu'est-ce qui est vrai ?","El límite es 50 mph, pero hay un aguacero. ¿Qué es cierto?"),
   ("You may always drive 50 mph, since it is the posted limit","Ou ka toujou kondui 50 mph, paske se limit ki afiche a","Vous pouvez toujours rouler à 50 mph, puisque c'est la limite affichée","Siempre puede manejar a 50 mph, porque es el límite señalado"),
   ("You must turn on your flashers and drive 50","Ou dwe limen limyè ijans ou epi kondui 50","Vous devez allumer les feux de détresse et rouler à 50","Debe encender las intermitentes e ir a 50"),
   ("You must slow to a safe speed; even 40 mph could get you a ticket","Ou dwe ralanti pou yon vitès ki san danje; menm 40 mph ka fè w jwenn yon kontravansyon","Vous devez ralentir à une vitesse sûre ; même 40 mph peut valoir une contravention","Debe bajar a una velocidad segura; aun a 40 mph podrían multarlo"),
   ("Speed limits do not apply during bad weather","Limit vitès yo pa aplike lè move tan","Les limites de vitesse ne s'appliquent pas par mauvais temps","Los límites de velocidad no aplican con mal tiempo"),
   ("Speed limits assume ideal conditions. The basic law is never to drive faster than is safe. The manual's own example: 40 mph in a heavy rainstorm on a 50 mph highway can get a ticket.","Limit vitès yo baze sou bon kondisyon. Lwa debaz la se pa janm kondui pi vit pase sa ki san danje. Egzanp mànyèl la: 40 mph nan yon gwo lapli sou yon otowout 50 mph ka bay yon kontravansyon.","Les limites supposent des conditions idéales. La règle de base : jamais plus vite que ce qui est sûr. Exemple du manuel : 40 mph sous une forte pluie sur une route à 50 peut valoir une contravention.","Los límites suponen condiciones ideales. La ley básica es nunca ir más rápido de lo seguro. Ejemplo del manual: 40 mph en un aguacero en una carretera de 50 puede costar una multa.")),
  ("p4",0,0,("school zone","zòn lekòl","zone scolaire","zona escolar"),
   ("What is the speed limit in a school zone?","Ki limit vitès nan yon zòn lekòl?","Quelle est la limite de vitesse en zone scolaire ?","¿Cuál es el límite de velocidad en una zona escolar?"),
   ("20 mph","20 mph","20 mph","20 mph"),("25 mph","25 mph","25 mph","25 mph"),("30 mph","30 mph","30 mph","30 mph"),("35 mph","35 mph","35 mph","35 mph"),
   ("Unless posted otherwise, the limit near schools is 20 mph. It may be posted with flashing yellow lights or for certain hours. Watch for children and crossing guards.","Sof si yon siy di yon lòt bagay, limit lan toupre lekòl se 20 mph. Li ka afiche ak limyè jòn k ap limen etèn oswa pou kèk lè nan jounen an. Veye timoun ak gad travèse yo.","Sauf indication, la limite près des écoles est de 20 mph. Elle peut être signalée par des feux jaunes clignotants ou pour certaines heures. Attention aux enfants et brigadiers.","Salvo otra indicación, el límite cerca de escuelas es 20 mph. Puede indicarse con luces amarillas intermitentes o para ciertas horas. Cuide a los niños y a los guardias de cruce.")),
  ("p7",2,0,("thickly settled","zòn ki gen anpil kay","zone densément bâtie","zona densamente poblada"),
   ("With no speed limit sign, what is the limit in a thickly settled or business district?","Lè pa gen siy limit vitès, ki limit lan nan yon zòn ki gen anpil kay oswa zòn biznis?","Sans panneau, quelle est la limite en zone densément bâtie ou commerciale ?","Sin letrero de límite, ¿cuál es el límite en una zona densamente poblada o comercial?"),
   ("20 mph","20 mph","20 mph","20 mph"),("40 mph","40 mph","40 mph","40 mph"),("30 mph","30 mph","30 mph","30 mph"),("50 mph","50 mph","50 mph","50 mph"),
   ("The state default is 30 mph. Some cities and towns have set 25 mph and post signs at their entrances, so always obey posted signs.","Limit leta a se 30 mph. Kèk vil mete 25 mph epi yo poze siy nan antre vil la, kidonk toujou swiv siy ki afiche yo.","La limite par défaut de l'État est de 30 mph. Certaines villes ont fixé 25 mph et l'affichent à leurs entrées : respectez toujours les panneaux.","El límite estatal por defecto es 30 mph. Algunos pueblos fijaron 25 mph y lo anuncian en sus entradas, así que obedezca siempre los letreros.")),
  ("pm702",3,0,("limited-access highway","otowout ak aksè limite","autoroute à accès limité","autopista de acceso limitado"),
   ("What speed limits are posted on limited-access highways such as interstates?","Ki limit vitès yo afiche sou otowout ak aksè limite tankou wout entèetatik yo?","Quelles limites sont affichées sur les autoroutes à accès limité comme les inter-États ?","¿Qué límites se indican en autopistas de acceso limitado como las interestatales?"),
   ("25 to 35 mph","25 a 35 mph","25 à 35 mph","25 a 35 mph"),("70 to 80 mph","70 a 80 mph","70 à 80 mph","70 a 80 mph"),("There is no limit","Pa gen limit","Il n'y a pas de limite","No hay límite"),("50 to 65 mph","50 a 65 mph","50 à 65 mph","50 a 65 mph"),
   ("Limited-access highways, like interstate routes, are posted from 50 to 65 mph. Smaller highways are 55 mph or lower.","Otowout ak aksè limite, tankou wout entèetatik yo, afiche ant 50 ak 65 mph. Ti otowout yo gen 55 mph oswa mwens.","Les autoroutes à accès limité, comme les inter-États, affichent de 50 à 65 mph. Les routes plus petites, 55 mph ou moins.","Las autopistas de acceso limitado, como las interestatales, marcan de 50 a 65 mph. Las más pequeñas, 55 mph o menos.")),
  ("pm703",1,0,("minimum speed","vitès minimòm","vitesse minimale","velocidad mínima"),
   ("What is the minimum speed on the Massachusetts Turnpike?","Ki vitès minimòm sou Massachusetts Turnpike?","Quelle est la vitesse minimale sur le Massachusetts Turnpike ?","¿Cuál es la velocidad mínima en el Massachusetts Turnpike?"),
   ("There is none","Pa genyen","Il n'y en a pas","No hay"),("40 mph","40 mph","40 mph","40 mph"),("20 mph","20 mph","20 mph","20 mph"),("55 mph","55 mph","55 mph","55 mph"),
   ("The Massachusetts Turnpike has a 40 mph minimum; the Boston Harbor tunnels have a 20 mph minimum. Police can also pull over a driver who is slowing traffic.","Massachusetts Turnpike gen yon minimòm 40 mph; tinèl Boston Harbor yo gen yon minimòm 20 mph. Lapolis ka fè yon chofè k ap ralanti sikilasyon an rale sou kote tou.","Le Massachusetts Turnpike impose un minimum de 40 mph ; les tunnels du port de Boston, 20 mph. La police peut aussi arrêter un conducteur qui ralentit la circulation.","El Massachusetts Turnpike tiene un mínimo de 40 mph; los túneles del puerto de Boston, 20 mph. La policía también puede detener a quien frena el tráfico.")),
  ("pm704",0,0,("thickly settled district","zòn ki gen anpil kay","zone densément bâtie","zona densamente poblada"),
   ("What makes an area a thickly settled district?","Kisa ki fè yon zòn se yon zòn ki gen anpil kay?","Qu'est-ce qui définit une zone densément bâtie ?","¿Qué hace que un área sea zona densamente poblada?"),
   ("Buildings less than 200 feet apart for a quarter mile or more","Bilding yo mwens pase 200 pye youn de lòt sou yon ka mil oswa plis","Des bâtiments à moins de 200 pieds les uns des autres sur un quart de mille ou plus","Edificios a menos de 200 pies entre sí por un cuarto de milla o más"),
   ("Any road that has a sidewalk on one side","Nenpòt wout ki gen yon twotwa sou yon bò","Toute route qui a un trottoir d'un côté","Cualquier camino con banqueta de un lado"),
   ("More than 1,000 cars a day pass through the area","Plis pase 1,000 machin pa jou pase nan zòn nan","Plus de 1 000 voitures par jour traversent le secteur","Más de 1,000 autos al día pasan por la zona"),
   ("Any road inside a city or town limit","Nenpòt wout andedan limit yon vil","Toute route à l'intérieur des limites d'une ville","Cualquier camino dentro de los límites de una ciudad"),
   ("A thickly settled district has buildings fewer than 200 feet apart for a quarter mile or more. The default limit there is 30 mph.","Yon zòn ki gen anpil kay gen bilding mwens pase 200 pye youn de lòt sou yon ka mil oswa plis. Limit pa defo a se 30 mph.","Une zone densément bâtie a des bâtiments à moins de 200 pieds les uns des autres sur un quart de mille ou plus. La limite par défaut y est de 30 mph.","Una zona densamente poblada tiene edificios a menos de 200 pies entre sí por un cuarto de milla o más. El límite por defecto ahí es 30 mph.")),
  ("pm705",3,0,("pedestrian","pyeton","piéton","peatón"),
   ("A car hits a pedestrian at 40 mph. About what share of pedestrians are seriously injured or killed at that speed?","Yon machin frape yon pyeton a 40 mph. Anviwon ki pòsyon pyeton ki blese grav oswa mouri nan vitès sa a?","Une voiture heurte un piéton à 40 mph. Quelle part des piétons sont gravement blessés ou tués à cette vitesse ?","Un auto atropella a un peatón a 40 mph. ¿Qué parte de los peatones sufre heridas graves o muere a esa velocidad?"),
   ("13%","13%","13 %","13 %"),("25%","25%","25 %","25 %"),("40%","40%","40 %","40 %"),("73%","73%","73 %","73 %"),
   ("At 20 mph, 13% of pedestrians are seriously injured or killed; at 30 mph, 40%; at 40 mph, 73%. Vehicle speed is the leading threat to pedestrians.","A 20 mph, 13% pyeton blese grav oswa mouri; a 30 mph, 40%; a 40 mph, 73%. Vitès machin yo se pi gwo menas pou pyeton.","À 20 mph, 13 % des piétons sont gravement blessés ou tués ; à 30 mph, 40 % ; à 40 mph, 73 %. La vitesse est la première menace pour les piétons.","A 20 mph, el 13 % de los peatones sufre heridas graves o muere; a 30 mph, el 40 %; a 40 mph, el 73 %. La velocidad es la mayor amenaza para los peatones.")),
  ("pm706",1,1,("hand signal","siyal ak men","signal de la main","señal con la mano"),
   ("Your turn signals stop working. How do you signal a right turn by hand?","Siyal machin ou yo pa mache ankò. Kijan pou w fè siyal vire adwat ak men?","Vos clignotants ne fonctionnent plus. Comment signaler un virage à droite de la main ?","Sus direccionales dejaron de funcionar. ¿Cómo indica un giro a la derecha con la mano?"),
   ("Left arm straight out","Bra goch lonje tou dwat","Bras gauche tendu","Brazo izquierdo extendido"),
   ("Left arm bent up at the elbow","Bra goch pliye monte anlè nan koud la","Bras gauche plié vers le haut","Brazo izquierdo doblado hacia arriba"),
   ("Left arm bent down","Bra goch pliye desann anba","Bras gauche plié vers le bas","Brazo izquierdo doblado hacia abajo"),
   ("Wave your arm in a circle","Fè bra w fè wonn","Faire tourner le bras","Mover el brazo en círculo"),
   ("Hand signals are made through the driver's window: arm straight out for left, arm bent up for right, arm bent down to slow or stop. You must know them to pass the road test.","Siyal ak men fèt nan fenèt chofè a: bra lonje tou dwat pou agoch, bra pliye anlè pou adwat, bra pliye anba pou ralanti oswa kanpe. Ou dwe konnen yo pou w pase Egzamen Pratik la.","Les signaux se font par la fenêtre du conducteur : bras tendu pour la gauche, plié vers le haut pour la droite, plié vers le bas pour ralentir ou s'arrêter. Il faut les connaître pour l'examen routier.","Las señales se hacen por la ventana del conductor: brazo extendido para la izquierda, doblado hacia arriba para la derecha, doblado hacia abajo para frenar o parar. Debe saberlas para el examen práctico.")),
  ("pm707",0,1,("right lane","vwa dwat","voie de droite","carril derecho"),
   ("On a road with two lanes going your way, which lane should you normally use?","Sou yon wout ki gen de vwa nan direksyon w, ki vwa ou dwe sèvi anjeneral?","Sur une route à deux voies dans votre sens, quelle voie utiliser normalement ?","En un camino con dos carriles en su sentido, ¿qué carril debe usar normalmente?"),
   ("The right lane, unless passing, turning left, or it is blocked","Vwa dwat la, sof si w ap depase, vire agoch, oswa l bloke","La voie de droite, sauf pour dépasser, tourner à gauche ou si elle est bloquée","El derecho, salvo para rebasar, girar a la izquierda o si está bloqueado"),
   ("The left lane, because it is the faster lane","Liy goch la, paske se liy ki pi vit la","La voie de gauche, parce que c'est la plus rapide","El carril izquierdo, porque es el más rápido"),
   ("Either lane, whichever has less traffic at the moment","Nenpòt liy, sa ki gen mwens machin nan moman an","L'une ou l'autre, celle qui a le moins de circulation sur le moment","Cualquiera, el que tenga menos tráfico en ese momento"),
   ("Straddle both lanes so no one can pass you","Woule ant de liy yo pou pèsonn pa ka depase w","Rouler à cheval sur les deux voies pour que personne ne vous dépasse","Ir entre los dos carriles para que nadie lo rebase"),
   ("Use the right lane unless you are passing, making a left turn, or the right lane is blocked.","Sèvi ak vwa dwat la sof si w ap depase, w ap vire agoch, oswa vwa dwat la bloke.","Utilisez la voie de droite sauf pour dépasser, tourner à gauche ou si elle est bloquée.","Use el carril derecho salvo para rebasar, girar a la izquierda o si está bloqueado.")),
  ("pm708",2,1,("exit","sòti","sortie","salida"),
   ("You miss your exit on the highway. What should you do?","Ou rate sòti w sou otowout la. Kisa ou dwe fè?","Vous manquez votre sortie sur l'autoroute. Que faire ?","Se pasó su salida en la autopista. ¿Qué debe hacer?"),
   ("Stop on the shoulder and back up","Kanpe sou bò wout la epi fè bak","S'arrêter sur l'accotement et reculer","Parar en el acotamiento y retroceder"),
   ("Make a U-turn across the median","Fè demi-tou atravè mitan an","Faire demi-tour par le terre-plein","Dar vuelta en U por el camellón"),
   ("Continue to the next exit","Kontinye jiska pwochen sòti a","Continuer jusqu'à la sortie suivante","Seguir hasta la siguiente salida"),
   ("Stop in the lane and wait","Kanpe nan vwa a epi tann","S'arrêter dans la voie et attendre","Parar en el carril y esperar"),
   ("If you miss your exit, do not stop and never back up on a highway. Get off at the next exit and follow signs back.","Si w rate sòti w, pa kanpe e pa janm fè bak sou otowout. Soti nan pwochen sòti a epi swiv siy yo pou w retounen.","Si vous manquez la sortie, ne vous arrêtez pas et ne reculez jamais sur l'autoroute. Prenez la sortie suivante et suivez les panneaux.","Si se pasa la salida, no pare ni retroceda nunca en la autopista. Salga en la siguiente y siga las señales para volver.")),
  ("pm709",1,2,("turn signal","siyal vire","clignotant","direccional"),
   ("How far before a turn on a regular road must you signal?","A ki distans anvan yon vire sou yon wout nòmal ou dwe mete siyal?","À quelle distance avant un virage sur une route ordinaire faut-il signaler ?","¿A qué distancia antes de girar en un camino normal debe señalar?"),
   ("25 feet","25 pye","25 pieds","25 pies"),("At least 100 feet","Omwen 100 pye","Au moins 100 pieds","Al menos 100 pies"),("At least 500 feet","Omwen 500 pye","Au moins 500 pieds","Al menos 500 pies"),("Only as you turn","Sèlman lè w ap vire","Seulement en tournant","Solo al girar"),
   ("Signal at least 100 feet before a turn, and at least 500 feet on a highway. Signal before you brake so others know what you plan.","Mete siyal omwen 100 pye anvan yon vire, ak omwen 500 pye sou otowout. Mete siyal anvan w fren pou lòt moun konnen sa w pral fè.","Signalez au moins 100 pieds avant un virage, et 500 sur l'autoroute. Signalez avant de freiner pour que les autres sachent ce que vous allez faire.","Señale al menos 100 pies antes de girar y 500 en autopista. Señale antes de frenar para que otros sepan lo que hará.")),
  ("pm710",3,1,("highway exit","sòti otowout","sortie d'autoroute","salida de autopista"),
   ("How far before a highway exit should you signal?","A ki distans anvan yon sòti otowout ou dwe mete siyal?","À quelle distance avant une sortie d'autoroute faut-il signaler ?","¿A qué distancia antes de una salida de autopista debe señalar?"),
   ("50 feet","50 pye","50 pieds (15 m)","50 pies"),("100 feet, just before the ramp","100 pye, jis anvan bretèl la","100 pieds (30 m), juste avant la bretelle","100 pies, justo antes de la rampa"),("1 mile","1 mil","1 mille","1 milla"),("At least 500 feet","Omwen 500 pye","Au moins 500 pieds","Al menos 500 pies"),
   ("Signal your exit at least 500 feet before the ramp, then slow to the posted ramp speed once you are on it.","Mete siyal sòti w omwen 500 pye anvan ranp lan, apre sa ralanti pou vitès ki afiche sou ranp lan lè w rive sou li.","Signalez votre sortie au moins 500 pieds avant la bretelle, puis ralentissez à la vitesse affichée sur la bretelle.","Señale su salida al menos 500 pies antes de la rampa y luego baje a la velocidad indicada en ella.")),
  ("pm711",2,1,("passing lane","vwa pou depase","voie de dépassement","carril para rebasar"),
   ("On an expressway with three lanes your way, what is the far left lane for?","Sou yon otowout ki gen twa vwa nan direksyon w, pou kisa vwa ki pi agoch la ye?","Sur une voie rapide à trois voies dans votre sens, à quoi sert la voie de gauche ?","En una autopista con tres carriles en su sentido, ¿para qué es el carril de la izquierda?"),
   ("Trucks","Kamyon","Les camions","Los camiones"),("Slow driving","Kondui dousman","La conduite lente","Manejar despacio"),("Passing","Depase","Dépassement","Rebasar"),("Breakdowns","Machin an pàn","Les pannes","Las averías"),
   ("With three or more lanes: the far right lane for slower driving, the middle lane for faster driving, the far left lane for passing.","Ak twa vwa oswa plis: vwa ki pi adwat la pou kondui pi dousman, vwa mitan an pou kondui pi vit, vwa ki pi agoch la pou depase.","Avec trois voies ou plus : la droite pour rouler plus lentement, le milieu pour plus vite, la gauche pour dépasser.","Con tres carriles o más: el de la derecha para ir más lento, el del medio más rápido y el de la izquierda para rebasar.")),
  ("pm712",0,2,("U-turn","demi-tou","demi-tour","vuelta en U"),
   ("Where may you NOT make a U-turn, even with no sign?","Ki kote ou PA ka fè demi-tou, menm si pa gen siy?","Où ne pouvez-vous PAS faire demi-tour, même sans panneau ?","¿Dónde NO puede dar vuelta en U, aunque no haya letrero?"),
   ("Near a curve or hilltop where drivers cannot see 500 feet","Toupre yon koub oswa tèt mòn kote chofè pa ka wè 500 pye","Près d'un virage ou d'un sommet où l'on ne voit pas à 500 pieds","Cerca de una curva o cima donde no se ve a 500 pies"),
   ("On a straight, clear street with good visibility","Sou yon lari dwat e klè kote w wè byen","Dans une rue droite et dégagée, avec une bonne visibilité","En una calle recta y despejada con buena visibilidad"),
   ("From the lane nearest the center line","Soti nan vwa ki pi pre liy mitan an","Depuis la voie la plus proche du centre","Desde el carril más cercano al centro"),
   ("On a quiet road with light traffic","Sou yon wout trankil ki pa gen anpil machin","Sur une route calme avec peu de circulation","En un camino tranquilo con poco tráfico"),
   ("Do not make a U-turn at the top of a hill, near a curve, or anywhere you or others cannot see 500 feet away. Make it only from the lane closest to the center line.","Pa fè demi-tou sou tèt yon mòn, toupre yon koub, oswa nenpòt kote ou menm oswa lòt moun pa ka wè 500 pye. Fè l sèlman soti nan vwa ki pi pre liy mitan an.","Pas de demi-tour au sommet d'une côte, près d'un virage, ni là où l'on ne voit pas à 500 pieds. Seulement depuis la voie la plus proche du centre.","No dé vuelta en U en una cima, cerca de una curva ni donde no se vea a 500 pies. Solo desde el carril más cercano a la línea central.")),
  ("pm713",3,2,("center turn lane","vwa mitan pou vire","voie centrale de virage","carril central de giro"),
   ("A two-way road has a shared center left-turn lane. Which is true?","Yon wout de sans gen yon vwa mitan pou vire agoch nan de direksyon. Kisa ki vre?","Une route à double sens a une voie centrale de virage à gauche partagée. Qu'est-ce qui est vrai ?","Un camino de doble sentido tiene un carril central compartido para girar a la izquierda. ¿Qué es cierto?"),
   ("You may use it to pass","Ou ka sèvi avè l pou depase","On peut l'utiliser pour dépasser","Puede usarlo para rebasar"),
   ("It is for one direction only","Li pou yon sèl direksyon","Elle sert à un seul sens","Es para un solo sentido"),
   ("You may drive in it for long distances","Ou ka kondui ladan l sou yon long distans","On peut y rouler longtemps","Puede circular por él largas distancias"),
   ("It is only for left turns; you may not travel in it","Li sèlman pou vire agoch; ou pa ka kondui ladan l","Elle ne sert qu'à tourner à gauche ; on n'y circule pas","Es solo para girar a la izquierda; no puede circular por él"),
   ("A center lane marked for left turns is shared by both directions for turning only. You may not travel in it.","Yon vwa mitan ki make pou vire agoch se pou de direksyon yo pataje sèlman pou vire. Ou pa ka kondui ladan l.","Une voie centrale marquée pour les virages à gauche est partagée par les deux sens, seulement pour tourner. On n'y circule pas.","Un carril central marcado para giros a la izquierda lo comparten ambos sentidos solo para girar. No se circula por él.")),
  ("pm714",1,2,("turning lane","vwa pou vire","voie de virage","carril de giro"),
   ("From which lane should you make a left turn on a multi-lane road?","Ki vwa ou dwe sèvi pou vire agoch sou yon wout ki gen plizyè vwa?","Depuis quelle voie tourner à gauche sur une route à plusieurs voies ?","¿Desde qué carril debe girar a la izquierda en un camino de varios carriles?"),
   ("The far right lane","Vwa ki pi adwat la","La voie de droite","El carril de la derecha"),
   ("The lane closest to the center","Vwa ki pi pre mitan an","La voie la plus proche du centre","El carril más cercano al centro"),
   ("Any lane, if you signal","Nenpòt vwa, si w mete siyal","N'importe laquelle, en signalant","Cualquiera, si señala"),
   ("The breakdown lane","Vwa pàn nan","La voie de panne","El carril de emergencia"),
   ("Turn from the lane closest to the lane you want to enter: left turns from the lane nearest the center, right turns from the far right lane. Change lanes after the turn if you need to.","Vire soti nan vwa ki pi pre vwa w vle antre a: vire agoch soti nan vwa ki pi pre mitan an, vire adwat soti nan vwa ki pi adwat la. Chanje vwa apre vire a si w bezwen.","Tournez depuis la voie la plus proche de celle où vous allez : à gauche depuis la plus proche du centre, à droite depuis celle de droite. Changez de voie après le virage si besoin.","Gire desde el carril más cercano al que quiere entrar: a la izquierda desde el más cercano al centro, a la derecha desde el de la derecha. Cambie de carril después si hace falta.")),
  ("pm715",0,3,("uncontrolled intersection","kafou san siy","intersection sans signalisation","intersección sin control"),
   ("At an intersection with no signs or signals, another car arrives from your right at the same time. Who goes first?","Nan yon kafou ki pa gen siy ni limyè, yon lòt machin rive sou bò dwat ou an menm tan. Kiyès ki pase anvan?","À une intersection sans panneau ni feu, une voiture arrive de votre droite en même temps. Qui passe d'abord ?","En una intersección sin señales ni semáforos, otro auto llega por su derecha al mismo tiempo. ¿Quién pasa primero?"),
   ("The car on your right","Machin ki sou bò dwat ou a","La voiture de droite","El auto de su derecha"),
   ("You do, if you are going straight","Ou menm, si w ap kontinye dwat","Vous, si vous allez tout droit","Usted, si sigue derecho"),
   ("The faster car","Machin ki pi vit la","La voiture la plus rapide","El auto más rápido"),
   ("Whoever honks","Moun ki klaksonnen an","Celui qui klaxonne","Quien toque el claxon"),
   ("At an uncontrolled intersection, yield to any vehicle that has entered from your right or is coming from your right. Still watch traffic from the left.","Nan yon kafou san siy, bay nenpòt machin ki antre oswa k ap vini sou bò dwat ou dwa de pasaj. Kontinye veye machin ki sou bò goch yo tou.","À une intersection sans signalisation, cédez à tout véhicule entré ou arrivant de votre droite. Surveillez aussi la gauche.","En una intersección sin control, ceda a cualquier vehículo que entró o viene por su derecha. Vigile también la izquierda.")),
  ("pm716",2,3,("four-way stop","STOP nan kat direksyon","arrêt à quatre directions","alto de cuatro direcciones"),
   ("At a four-way stop, you and the car on your right stop at the same time. What do you do?","Nan yon kafou STOP nan kat direksyon, ou menm ak machin ki sou bò dwat ou kanpe an menm tan. Kisa ou fè?","À un arrêt à quatre directions, vous et la voiture de droite vous arrêtez en même temps. Que faites-vous ?","En un alto de cuatro direcciones, usted y el auto de su derecha paran a la vez. ¿Qué hace?"),
   ("Go first, since you are on the left","Pase anvan, paske w sou bò goch","Passer d'abord, car vous êtes à gauche","Pasar primero, porque está a la izquierda"),
   ("Both go at once","Nou toulède pase an menm tan","Passer tous les deux","Pasan los dos a la vez"),
   ("Yield to the car on your right","Bay machin ki sou bò dwat ou a dwa de pasaj","Céder à la voiture de droite","Ceder al auto de su derecha"),
   ("Honk and go","Klaksonnen epi pase","Klaxonner et passer","Tocar el claxon y pasar"),
   ("Vehicles go in the order they stopped. If two stop at the same time, yield to the one on your right. Eye contact helps avoid confusion.","Machin yo pase nan lòd yo te kanpe a. Si de kanpe an menm tan, bay sa ki sou bò dwat ou a dwa de pasaj. Gade chofè yo nan je ede evite konfizyon.","Les véhicules passent dans l'ordre d'arrêt. Si deux s'arrêtent ensemble, cédez à celui de droite. Le contact visuel évite la confusion.","Los vehículos pasan en el orden en que pararon. Si dos paran a la vez, ceda al de la derecha. El contacto visual evita confusiones.")),
  ("pm717",3,3,("White Cane Law","Lwa Baton Blan","loi de la canne blanche","Ley del Bastón Blanco"),
   ("A person with a white cane is crossing the street in front of you. What does the law require?","Yon moun ki gen yon baton blan ap travèse ri a devan w. Kisa lalwa mande?","Une personne avec une canne blanche traverse devant vous. Qu'exige la loi ?","Una persona con bastón blanco cruza la calle frente a usted. ¿Qué exige la ley?"),
   ("Honk once so they know you are there","Klakonnen yon fwa pou l konnen w la","Klaxonner une fois pour qu'elle sache que vous êtes là","Tocar el claxon una vez para que sepa que usted está ahí"),
   ("Wave them across","Fè l siy pou l travèse","Lui faire signe de traverser","Hacerle señas para que cruce"),
   ("Drive slowly around them, leaving plenty of room","Kondui dousman otou l, epi kite anpil espas","Le contourner lentement en laissant beaucoup d'espace","Rodearlo despacio, dejando mucho espacio"),
   ("Stop completely and stay stopped until they have crossed","Kanpe nèt epi rete kanpe jiskaske l fin travèse","S'arrêter complètement et rester arrêté jusqu'à ce qu'elle ait traversé","Parar por completo y quedarse hasta que termine de cruzar"),
   ("The White Cane Law requires a complete stop for a blind pedestrian crossing. Stay stopped until they are across; do not honk or wave, and never pass another stopped vehicle.","Lwa Baton Blan an mande pou w kanpe nèt pou yon pyeton avèg k ap travèse. Rete kanpe jiskaske l fin travèse; pa klaksonnen ni fè siy, epi pa janm depase yon lòt machin ki kanpe.","La loi de la canne blanche impose un arrêt complet pour un piéton aveugle qui traverse. Restez arrêté jusqu'à ce qu'il ait traversé ; ne klaxonnez pas, ne faites pas signe et ne dépassez jamais un autre véhicule arrêté.","La Ley del Bastón Blanco exige parar por completo ante un peatón ciego que cruza. Quédese hasta que termine; no toque el claxon ni haga señas, y nunca rebase a otro vehículo detenido.")),
  ("pm718",1,3,("driveway","antre kay","allée","entrada de casa"),
   ("You are pulling out of a driveway onto a paved street. What must you do?","W ap soti nan yon antre kay pou antre sou yon ri asfalte. Kisa ou dwe fè?","Vous sortez d'une allée pour vous engager sur une rue pavée. Que devez-vous faire ?","Sale de una entrada de casa a una calle pavimentada. ¿Qué debe hacer?"),
   ("Honk to warn others, then pull out","Klakonnen pou avèti lòt moun, apre sa sòti","Klaxonner pour prévenir, puis s'engager","Tocar el claxon para avisar y luego salir"),
   ("Stop and yield to pedestrians, bicyclists and vehicles on the street","Kanpe epi bay pyeton, siklis ak machin ki sou ri a dwa de pasaj","S'arrêter et céder aux piétons, cyclistes et véhicules dans la rue","Parar y ceder a peatones, ciclistas y vehículos en la calle"),
   ("Pull out quickly before more traffic arrives","Sòti vit anvan plis machin rive","S'engager vite avant que d'autres voitures arrivent","Salir rápido antes de que llegue más tráfico"),
   ("Pull out slowly, since traffic on the street must stop for you","Sòti dousman, paske machin nan lari a dwe kanpe pou ou","Vous engager lentement, puisque la circulation doit s'arrêter pour vous","Salir despacio, ya que el tráfico de la calle debe detenerse por usted"),
   ("Entering a paved road from a private road, driveway or unpaved road, you must stop and give the right-of-way to pedestrians, bicyclists and vehicles on that road.","Lè w ap antre sou yon wout asfalte soti nan yon wout prive, yon antre kay oswa yon wout tè, ou dwe kanpe epi bay pyeton, siklis ak machin ki sou wout sa a dwa de pasaj.","En entrant sur une route pavée depuis un chemin privé, une allée ou un chemin non pavé, vous devez vous arrêter et céder aux piétons, cyclistes et véhicules.","Al entrar a un camino pavimentado desde un camino privado, una entrada o un camino de tierra, debe parar y ceder a peatones, ciclistas y vehículos.")),
  ("pm719",0,3,("divided highway","otowout divize","route divisée","carretera dividida"),
   ("You are on a two-lane road and reach an intersection with a divided highway. Who has the right-of-way?","Ou sou yon wout de vwa epi w rive nan yon kafou ak yon otowout divize. Kiyès ki gen dwa de pasaj?","Vous êtes sur une route à deux voies et arrivez à une route divisée. Qui a la priorité ?","Va por un camino de dos carriles y llega a una carretera dividida. ¿Quién tiene el derecho de paso?"),
   ("Traffic on the divided highway","Machin ki sou otowout divize a","La circulation sur la route divisée","El tráfico de la carretera dividida"),
   ("You, if you arrive first","Ou menm, si w rive anvan","Vous, si vous arrivez en premier","Usted, si llega primero"),
   ("Whoever is going faster","Moun ki pi vit la","Le plus rapide","Quien vaya más rápido"),
   ("You, because you are on the right","Ou menm, paske w sou bò dwat","Vous, car vous êtes à droite","Usted, porque está a la derecha"),
   ("If you are on a single or two-lane road and come to a divided highway or a road with three or more lanes, you must yield the right-of-way.","Si w sou yon wout yon oswa de vwa epi w rive nan yon otowout divize oswa yon wout twa vwa oswa plis, ou dwe bay dwa de pasaj.","Sur une route à une ou deux voies, à l'arrivée sur une route divisée ou à trois voies ou plus, vous devez céder.","Si va por un camino de uno o dos carriles y llega a una carretera dividida o de tres carriles o más, debe ceder.")),
  ("p3",1,4,("rotary","kafou won","carrefour giratoire","rotonda"),
   ("You are entering a rotary. Who has the right-of-way?","W ap antre nan yon kafou won. Kiyès ki gen dwa de pasaj?","Vous entrez dans un carrefour giratoire. Qui a la priorité ?","Está entrando a una rotonda. ¿Quién tiene el derecho de paso?"),
   ("You, because you are on the right","Ou menm, paske w sou bò dwat","Vous, car vous êtes à droite","Usted, porque está a la derecha"),
   ("Vehicles already in the rotary","Machin ki deja nan kafou won an","Les véhicules déjà dans l'anneau","Los vehículos que ya están en la rotonda"),
   ("The larger vehicle","Machin ki pi gwo a","Le plus gros véhicule","El vehículo más grande"),
   ("Whoever honks first","Moun ki klaksonnen an premye","Celui qui klaxonne en premier","Quien toque el claxon primero"),
   ("Traffic in a Massachusetts rotary moves counterclockwise. Yield to vehicles already in the rotary and to pedestrians, unless signs or police say otherwise.","Sikilasyon nan yon kafou won nan Massachusetts fè wonn nan sans kontrè egui yon revèy. Bay machin ki deja nan kafou won an ak pyeton yo dwa de pasaj, sof si siy oswa lapolis di yon lòt bagay.","Dans un giratoire du Massachusetts, on tourne dans le sens inverse des aiguilles d'une montre. Cédez aux véhicules déjà dans l'anneau et aux piétons, sauf indication contraire.","En una rotonda de Massachusetts se circula en sentido contrario al reloj. Ceda a los vehículos que ya están dentro y a los peatones, salvo que señales o policías indiquen otra cosa.")),
  ("pm720",3,4,("counterclockwise","kontrè egui yon revèy","sens inverse des aiguilles d'une montre","sentido contrario al reloj"),
   ("Which way does traffic travel in a Massachusetts rotary?","Nan ki direksyon machin yo fè wonn nan yon kafou won Massachusetts?","Dans quel sens circule-t-on dans un giratoire du Massachusetts ?","¿En qué sentido se circula en una rotonda de Massachusetts?"),
   ("Clockwise","Nan sans egui yon revèy","Dans le sens des aiguilles d'une montre","En el sentido del reloj"),("Either way","Nenpòt sans","Dans les deux sens","En cualquier sentido"),("Whichever way is shorter","Sans ki pi kout la","Par le chemin le plus court","Por donde sea más corto"),("Counterclockwise","Nan sans kontrè egui yon revèy","Dans le sens inverse des aiguilles d'une montre","En sentido contrario al reloj"),
   ("Traffic in a rotary always travels counterclockwise, around the central island.","Sikilasyon nan yon kafou won toujou fè wonn nan sans kontrè egui yon revèy, toutotou zile mitan an.","Dans un giratoire, on tourne toujours dans le sens inverse des aiguilles d'une montre, autour de l'îlot central.","En una rotonda siempre se circula en sentido contrario al reloj, alrededor de la isla central.")),
  ("pm721",0,4,("multi-lane rotary","kafou won ak plizyè vwa","giratoire à plusieurs voies","rotonda de varios carriles"),
   ("In a multi-lane rotary with no signs, you want to make a U-turn. Which lane should you enter from?","Nan yon kafou won ak plizyè vwa san siy, ou vle fè demi-tou. Nan ki vwa ou dwe antre?","Dans un giratoire à plusieurs voies sans panneau, vous voulez faire demi-tour. Par quelle voie entrer ?","En una rotonda de varios carriles sin señales, quiere dar vuelta en U. ¿Por qué carril debe entrar?"),
   ("The left lane, then exit to the right lane","Vwa goch la, apre sa soti nan vwa dwat la","La voie de gauche, puis sortir dans la voie de droite","El carril izquierdo, luego salir al derecho"),
   ("The right lane, and stay right the whole way","Vwa dwat la, epi rete adwat tout chemen an","La voie de droite, en restant à droite","El derecho, y quedarse a la derecha todo el tiempo"),
   ("Any lane, then cut across","Nenpòt vwa, apre sa koupe travèse","N'importe quelle voie, puis couper","Cualquiera, y luego cruzar"),
   ("The breakdown lane","Vwa pàn nan","La voie de panne","El carril de emergencia"),
   ("For a three-quarter turn or U-turn with no signs, enter from the left lane, travel in the inner lane, and exit onto the right lane. For a quarter turn or straight ahead, use the right lane.","Pou twa ka vire oswa demi-tou san siy, antre nan vwa goch la, kondui nan vwa anndan an, epi soti nan vwa dwat la. Pou yon ka vire oswa tou dwat, sèvi ak vwa dwat la.","Pour trois quarts de tour ou un demi-tour sans panneau, entrez par la gauche, roulez à l'intérieur et sortez à droite. Pour un quart de tour ou tout droit, voie de droite.","Para tres cuartos de vuelta o vuelta en U sin señales, entre por la izquierda, circule por dentro y salga al carril derecho. Para un cuarto de vuelta o seguir derecho, use el derecho.")),
  ("pm722",2,4,("roundabout","wonpwen piti","rond-point","glorieta"),
   ("Compared with a rotary, a roundabout requires what speed?","Konpare ak yon kafou won, ki vitès yon wonpwen piti mande?","Par rapport à un giratoire, quelle vitesse un rond-point exige-t-il ?","Comparada con una rotonda, ¿qué velocidad requiere una glorieta?"),
   ("Up to 40 mph","Jiska 40 mph","Jusqu'à 40 mph","Hasta 40 mph"),("Highway speed","Vitès otowout","Vitesse d'autoroute","Velocidad de autopista"),("25 mph or less","25 mph oswa mwens","25 mph ou moins","25 mph o menos"),("At least 30 mph","Omwen 30 mph","Au moins 30 mph","Al menos 30 mph"),
   ("Roundabouts are smaller than rotaries, with yield lines and crosswalks, and their size requires speeds of 25 mph or less. Big rotaries handle traffic up to 40 mph.","Wonpwen piti yo pi piti pase kafou won yo, ak liy yield ak pasaj pyeton, epi gwosè yo mande vitès 25 mph oswa mwens. Gwo kafou won yo ka resevwa machin jiska 40 mph.","Les ronds-points sont plus petits que les giratoires, avec lignes « cédez » et passages, et leur taille impose 25 mph ou moins. Les grands giratoires acceptent jusqu'à 40 mph.","Las glorietas son más pequeñas que las rotondas, con líneas de ceda y cruces, y su tamaño pide 25 mph o menos. Las rotondas grandes manejan hasta 40 mph.")),
  ("pm723",1,3,("courtesy crash","aksidan politès","accident de courtoisie","choque de cortesía"),
   ("You are waiting to turn left. A driver in stopped traffic waves you through. What is true?","W ap tann pou vire agoch. Yon chofè nan machin ki kanpe yo fè w siy pase. Kisa ki vre?","Vous attendez pour tourner à gauche. Un conducteur dans la file arrêtée vous fait signe de passer. Qu'est-ce qui est vrai ?","Espera para girar a la izquierda. Un conductor en el tráfico detenido le hace señas para pasar. ¿Qué es cierto?"),
   ("The wave gives you the right-of-way over all other traffic","Siy la ba w priyorite sou tout lòt machin","Le signe vous donne la priorité sur toute autre circulation","La seña le da el derecho de paso sobre todo el demás tráfico"),
   ("Oncoming traffic still has the right-of-way; turn only when you can see it is clear","Machin k ap vini yo toujou gen dwa de pasaj; vire sèlman lè w wè wout la klè","La circulation en face garde la priorité ; tournez seulement si vous voyez que c'est libre","El tráfico de frente sigue teniendo el derecho de paso; gire solo si ve que está libre"),
   ("You must turn right away so you do not hold up traffic","Ou dwe vire touswit pou w pa bloke sikilasyon an","Vous devez tourner tout de suite pour ne pas bloquer","Debe girar de inmediato para no detener el tráfico"),
   ("The driver who waved is responsible for any crash that follows","Chofè ki fè siy la responsab nenpòt aksidan ki rive apre","Le conducteur qui a fait signe est responsable de tout accident qui suit","El conductor que hizo la seña es responsable de cualquier choque"),
   ("Waving people through stopped traffic causes courtesy crashes. Oncoming traffic has the right-of-way whether or not someone waves at you.","Fè moun siy pase nan mitan machin ki kanpe lakoz aksidan politès. Machin k ap vini yo gen dwa de pasaj kit yon moun fè w siy kit li pa fè w siy.","Faire signe de passer entre des véhicules arrêtés cause des accidents de courtoisie. La circulation en face a la priorité, qu'on vous fasse signe ou non.","Hacer señas para pasar entre autos detenidos causa choques de cortesía. El tráfico de frente tiene el derecho de paso, le hagan señas o no.")),
  ("pm724",3,5,("passing","depase","dépassement","rebasar"),
   ("You want to cross a broken yellow line to pass. How far ahead must you be able to see clearly?","Ou vle travèse yon liy jòn an tire pou depase. Ki distans devan ou dwe ka wè klè?","Vous voulez franchir une ligne jaune discontinue pour dépasser. Jusqu'où devez-vous voir clairement ?","Quiere cruzar una amarilla discontinua para rebasar. ¿Hasta dónde debe ver con claridad?"),
   ("100 feet","100 pye","100 pieds (30 m)","100 pies"),("At least 200 feet","Omwen 200 pye","Au moins 200 pieds (60 m)","Al menos 200 pies"),("1,000 feet","1,000 pye","1 000 pieds","1,000 pies"),("At least 400 feet","Omwen 400 pye","Au moins 400 pieds","Al menos 400 pies"),
   ("To cross a broken yellow line to pass, you must see at least 400 feet ahead, and you must be back in your lane before any oncoming vehicle comes within 200 feet.","Pou travèse yon liy jòn an tire pou depase, ou dwe ka wè omwen 400 pye devan, epi ou dwe retounen nan vwa w anvan nenpòt machin k ap vini rive a 200 pye.","Pour franchir une jaune discontinue et dépasser, vous devez voir au moins 400 pieds devant, et être revenu dans votre voie avant qu'un véhicule en face soit à 200 pieds.","Para cruzar una amarilla discontinua y rebasar, debe ver al menos 400 pies adelante y volver a su carril antes de que uno de frente esté a 200 pies.")),
  ("pm725",2,5,("returning to lane","retounen nan vwa","se rabattre","volver al carril"),
   ("After passing, when is it safe to move back into the right lane?","Apre w fin depase, kilè li san danje pou w retounen nan vwa dwat la?","Après un dépassement, quand peut-on se rabattre à droite ?","Después de rebasar, ¿cuándo es seguro volver al carril derecho?"),
   ("As soon as your front bumper is past the other car","Depi pare-chòk devan w fin pase lòt machin nan","Dès que votre pare-chocs avant a dépassé l'autre voiture","Apenas su defensa delantera pase el otro auto"),
   ("After you honk","Apre w fin klaksonnen","Après avoir klaxonné","Después de tocar el claxon"),
   ("When you can see the passed vehicle's headlights in your mirror","Lè w ka wè limyè devan machin ou depase a nan miwa w","Quand vous voyez les phares du véhicule dépassé dans le rétroviseur","Cuando vea en el espejo las luces del vehículo rebasado"),
   ("Only at the next intersection","Sèlman nan pwochen kafou a","Seulement à la prochaine intersection","Solo en la siguiente intersección"),
   ("Wait at least until you can see the passed vehicle's headlights in your mirror, signal right, and return before oncoming traffic is within 200 feet.","Tann omwen jiskaske w wè limyè devan machin ou depase a nan miwa w, mete siyal adwat, epi retounen anvan machin k ap vini yo rive a 200 pye.","Attendez au moins de voir les phares du véhicule dépassé dans le rétroviseur, signalez à droite, et rabattez-vous avant qu'un véhicule en face soit à 200 pieds.","Espere al menos a ver en el espejo las luces del vehículo rebasado, señale a la derecha y vuelva antes de que el tráfico de frente esté a 200 pies.")),
  ("pm726",0,5,("passing on the right","depase sou bò dwat","dépasser par la droite","rebasar por la derecha"),
   ("When may you pass another vehicle on the right?","Kilè ou ka depase yon lòt machin sou bò dwat?","Quand pouvez-vous dépasser un véhicule par la droite ?","¿Cuándo puede rebasar a otro vehículo por la derecha?"),
   ("When it is turning left and there is room","Lè l ap vire agoch epi gen espas","Quand il tourne à gauche et qu'il y a de la place","Cuando gira a la izquierda y hay espacio"),
   ("Any time it is going too slowly","Nenpòt lè l ap mache twò dousman","Chaque fois qu'il roule trop lentement","Siempre que vaya demasiado lento"),
   ("Using the shoulder","Sou bò wout la","Par l'accotement","Usando el acotamiento"),
   ("Never","Pa janm","Jamais","Nunca"),
   ("Passing on the right is allowed only when the vehicle is turning left, on a one-way street, or on a road where traffic moves one way, and the road is wide and clear. Never use the shoulder.","Ou ka depase sou bò dwat sèlman lè machin nan ap vire agoch, sou yon wout yon sèl sans, oswa sou yon wout kote machin yo ale nan yon sèl direksyon, epi wout la laj e klè. Pa janm sèvi ak bò wout la.","On peut dépasser par la droite seulement si le véhicule tourne à gauche, en sens unique ou sur une route à sens unique, si la chaussée est large et libre. Jamais par l'accotement.","Se puede rebasar por la derecha solo si el vehículo gira a la izquierda, en calle de un sentido o en camino de un sentido, con espacio y libre. Nunca por el acotamiento.")),
  ("pm727",1,5,("being passed","yon moun ap depase w","se faire dépasser","ser rebasado"),
   ("Another car is passing you. What should you do?","Yon lòt machin ap depase w. Kisa ou dwe fè?","Une autre voiture vous dépasse. Que faire ?","Otro auto lo está rebasando. ¿Qué debe hacer?"),
   ("Speed up so it can't get in front","Akselere pou l pa ka pase devan w","Accélérer pour l'empêcher de passer","Acelerar para que no se le meta"),
   ("Slow down and keep to the right","Ralanti epi rete adwat","Ralentir et rester à droite","Bajar la velocidad y mantenerse a la derecha"),
   ("Move to the left to block it","Deplase agoch pou bloke l","Se déporter à gauche pour le bloquer","Moverse a la izquierda para bloquearlo"),
   ("Brake hard","Fren fò","Freiner fort","Frenar fuerte"),
   ("When you are being passed, slow down, stay to the right, and let the other driver pass safely. Do not speed up.","Lè yon moun ap depase w, ralanti, rete adwat, epi kite lòt chofè a pase san danje. Pa akselere.","Quand on vous dépasse, ralentissez, restez à droite et laissez passer en sécurité. N'accélérez pas.","Cuando lo rebasan, baje la velocidad, manténgase a la derecha y deje pasar con seguridad. No acelere.")),
  ("pm728",3,5,("move-over law","lwa «move-over»","loi « move-over »","ley de moverse de carril"),
   ("On a four-lane highway, a police car is stopped on the shoulder with its lights flashing. What does the move-over law require?","Sou yon otowout kat vwa, yon machin lapolis kanpe sou bò wout la ak limyè l k ap limen etèn. Kisa lwa «move-over» a mande?","Sur une autoroute à quatre voies, une voiture de police est arrêtée sur l'accotement, feux clignotants. Qu'exige la loi « move-over » ?","En una autopista de cuatro carriles, una patrulla está detenida en el acotamiento con luces intermitentes. ¿Qué exige la ley de moverse?"),
   ("Nothing, as long as you stay in your lane and keep your speed","Anyen, toutotan w rete nan liy ou epi kenbe vitès ou","Rien, tant que vous restez dans votre voie à la même vitesse","Nada, siempre que siga en su carril y a la misma velocidad"),
   ("Stop behind the police car until it leaves","Kanpe dèyè machin polis la jiskaske l ale","S'arrêter derrière la voiture de police jusqu'à son départ","Detenerse detrás de la patrulla hasta que se vaya"),
   ("Speed up so you pass it as quickly as possible","Akselere pou w pase l pi vit posib","Accélérer pour le dépasser le plus vite possible","Acelerar para pasarlo lo más rápido posible"),
   ("Slow down and, if safe, move over to leave an empty lane beside it","Ralanti epi, si l san danje, deplase pou kite yon vwa vid bò kote l","Ralentir et, si possible, changer de voie pour laisser une voie libre à côté","Bajar la velocidad y, si es seguro, cambiarse para dejar un carril libre a su lado"),
   ("Approaching a stopped emergency, highway or recovery vehicle with flashing lights, slow to a safe speed and move to a lane not next to it. If you cannot move over, you must still slow down.","Lè w ap pwoche yon veyikil ijans, otowout oswa remòkaj ki kanpe ak limyè k ap limen etèn, ralanti a yon vitès san danje epi pran yon vwa ki pa kole ak li. Si w pa ka deplase, ou toujou dwe ralanti.","En approchant d'un véhicule d'urgence, d'entretien ou de dépannage arrêté avec feux clignotants, ralentissez et prenez une voie qui n'est pas à côté. Si c'est impossible, ralentissez quand même.","Al acercarse a un vehículo de emergencia, de carretera o de grúa detenido con luces, baje a una velocidad segura y use un carril que no esté junto a él. Si no puede cambiarse, igual debe bajar la velocidad.")),
  ("pm729",2,6,("parking on a hill","pake sou mòn","stationner en pente","estacionar en pendiente"),
   ("You park facing downhill next to a curb. Which way should you turn your front wheels?","Ou pake fas desann bò yon twotwa. Ki bò ou dwe vire wou devan yo?","Vous stationnez en descente le long d'un trottoir. De quel côté tourner les roues avant ?","Se estaciona cuesta abajo junto a la acera. ¿Hacia dónde gira las ruedas delanteras?"),
   ("Straight ahead","Tou dwat","Tout droit","Derechas"),
   ("Away from the curb","Nan direksyon opoze twotwa a","À l'opposé du trottoir","Hacia afuera de la acera"),
   ("Toward the curb","Nan direksyon twotwa a","Vers le trottoir","Hacia la acera"),
   ("It does not matter with the parking brake on","Sa pa enpòtan si fren pakin nan mete","Peu importe avec le frein serré","No importa con el freno puesto"),
   ("Downhill against a curb: wheels toward the curb. Uphill against a curb: wheels away from the curb, toward the travel lane. No curb: wheels toward the edge of the road. Always set the parking brake.","Desann bò yon twotwa: wou yo vire nan direksyon twotwa a. Monte bò yon twotwa: wou yo vire nan direksyon opoze twotwa a, sou bò vwa a. San twotwa: wou yo vire sou bò wout la. Toujou mete fren pakin nan.","En descente avec trottoir : roues vers le trottoir. En montée avec trottoir : roues à l'opposé, vers la voie. Sans trottoir : roues vers le bord de la route. Serrez toujours le frein.","Cuesta abajo con acera: ruedas hacia la acera. Cuesta arriba con acera: ruedas hacia afuera, hacia el carril. Sin acera: hacia la orilla del camino. Ponga siempre el freno.")),
  ("pm730",0,6,("fire hydrant","bouch ponpye","borne d'incendie","hidrante"),
   ("How close to a fire hydrant may you park?","Ki distans ou ka pake bò yon bouch ponpye?","À quelle distance d'une borne d'incendie peut-on stationner ?","¿A qué distancia de un hidrante puede estacionarse?"),
   ("No closer than 10 feet","Pa pi pre pase 10 pye","Pas à moins de 10 pieds","No a menos de 10 pies"),("No closer than 3 feet","Pa pi pre pase 3 pye","Pas à moins de 3 pieds","No a menos de 3 pies"),("Right next to it, if you stay in the car","Kole ak li, si w rete nan machin nan","Juste à côté, si on reste dans la voiture","Junto a él, si se queda en el auto"),("No closer than 50 feet","Pa pi pre pase 50 pye","Pas à moins de 50 pieds","No a menos de 50 pies"),
   ("You may not park within 10 feet of a fire hydrant or fire lane, or within 20 feet of an intersection.","Ou pa ka pake nan 10 pye yon bouch ponpye oswa yon vwa ponpye, ni nan 20 pye yon kafou.","Interdit de stationner à moins de 10 pieds d'une borne ou d'une voie pompiers, ou à moins de 20 pieds d'une intersection.","No puede estacionarse a menos de 10 pies de un hidrante o carril de bomberos, ni a menos de 20 pies de una intersección.")),
  ("pm731",3,6,("intersection","kafou","intersection","intersección"),
   ("How close to an intersection may you park?","Ki distans ou ka pake bò yon kafou?","À quelle distance d'une intersection peut-on stationner ?","¿A qué distancia de una intersección puede estacionarse?"),
   ("5 feet","5 pye","5 pieds","5 pies"),("10 feet","10 pye","10 pieds","10 pies"),("Anywhere outside the crosswalk","Nenpòt kote andeyò pasaj pyeton an","N'importe où hors du passage","En cualquier lugar fuera del cruce"),("No closer than 20 feet","Pa pi pre pase 20 pye","Pas à moins de 20 pieds","No a menos de 20 pies"),
   ("Do not park within 20 feet of an intersection, in a crosswalk, or in front of a driveway.","Pa pake nan 20 pye yon kafou, nan yon pasaj pyeton, ni devan yon antre kay.","Pas de stationnement à moins de 20 pieds d'une intersection, sur un passage, ni devant une entrée.","No se estacione a menos de 20 pies de una intersección, en un cruce ni frente a una entrada.")),
  ("pm732",1,6,("parking brake","fren pakin","frein de stationnement","freno de estacionamiento"),
   ("You leave your car parked on the street. What does state law require?","Ou kite machin ou pake nan ri a. Kisa lwa leta a mande?","Vous laissez votre voiture garée dans la rue. Qu'exige la loi ?","Deja su auto estacionado en la calle. ¿Qué exige la ley?"),
   ("Only lock the doors and take your key","Fèmen pòt yo a kle epi pran kle w sèlman","Seulement verrouiller les portes et prendre votre clé","Solo cerrar las puertas con llave y llevarse la llave"),
   ("Stop the motor, set the parking brake, lock the ignition, remove the key and lock the door","Etenn motè a, mete fren pakin nan, bloke kontak la, retire kle a epi fèmen pòt la a kle","Couper le moteur, serrer le frein, verrouiller le contact, retirer la clé et verrouiller la porte","Apagar el motor, poner el freno, bloquear el encendido, sacar la llave y cerrar la puerta"),
   ("You may leave the engine running if you will be back in a few minutes","Ou ka kite motè a ap mache si w ap tounen nan kèk minit","Vous pouvez laisser le moteur tourner si vous revenez dans quelques minutes","Puede dejar el motor encendido si regresa en unos minutos"),
   ("Turn on the emergency flashers","Limen limyè ijans yo","Allumer les feux de détresse","Encender las luces de emergencia"),
   ("When you leave your vehicle, state law requires you to stop the motor, set the parking brake, lock the ignition, remove the key and lock the door.","Lè w kite machin ou, lwa leta a mande pou w etenn motè a, mete fren pakin nan, bloke kontak la, retire kle a epi fèmen pòt la a kle.","En quittant le véhicule, la loi exige de couper le moteur, serrer le frein, verrouiller le contact, retirer la clé et verrouiller la porte.","Al dejar el vehículo, la ley exige apagar el motor, poner el freno de estacionamiento, bloquear el encendido, sacar la llave y cerrar la puerta."))]))

# ---------------------------------------------------------------- P3
CH.append(dict(ch=3,
 title=("Sharing the road","Pataje wout la","Partager la route","Compartir el camino"),
 bp=("Manual chapter 2, pages 49–54, and chapter 4, pages 104–117. On the RMV test: rules of the road.","Chapit 2 nan mànyèl la, paj 49–54, ak chapit 4, paj 104–117. Nan egzamen RMV a: règ wout yo.","Chapitre 2 du manuel, pages 49–54, et chapitre 4, pages 104–117. À l'examen du RMV : règles de la route.","Capítulo 2 del manual, páginas 49–54, y capítulo 4, páginas 104–117. En el examen del RMV: reglas del camino."),
 sections=[
  dict(h=("Vulnerable road users","Moun ki pi frajil sou wout la","Usagers vulnérables","Usuarios vulnerables"), pg="49", b=[
   ("li",("Vulnerable road users include pedestrians, roadside workers, bicyclists, horse riders, and people using wheelchairs, mopeds, scooters, skateboards or roller skates.","Moun ki pi frajil sou wout la gen ladan pyeton, travayè bò wout, siklis, moun ki monte cheval, ak moun ki sèvi ak chèz woulant, moped, eskoutè, skateboard oswa paten.","Les usagers vulnérables comprennent piétons, travailleurs en bord de route, cyclistes, cavaliers, et personnes en fauteuil roulant, cyclomoteur, trottinette, planche à roulettes ou patins.","Los usuarios vulnerables incluyen peatones, trabajadores en la vía, ciclistas, jinetes y personas en silla de ruedas, ciclomotor, patineta motorizada o no, skateboard o patines.")),
   ("li",("When you pass one, leave at least four feet. If it is safe, you may use part of the next lane or cross the center line, and you must still obey the speed limit.","Lè w ap depase youn, kite omwen kat pye. Si l san danje, ou ka sèvi ak yon pati nan vwa bò kote a oswa travèse liy mitan an, epi ou toujou dwe respekte limit vitès la.","En dépassant l'un d'eux, laissez au moins quatre pieds. Si c'est sûr, vous pouvez empiéter sur la voie voisine ou franchir la ligne centrale, toujours sans dépasser la limite.","Al rebasar a uno, deje al menos cuatro pies. Si es seguro, puede usar parte del carril de al lado o cruzar la línea central, sin pasar el límite de velocidad."))]),
  dict(h=("Pedestrians","Pyeton","Piétons","Peatones"), pg="49–50, 112", b=[
   ("li",("Watch for children near schools, parks, bus stops and playgrounds, and for older people near senior centers. Look for people hidden by curves, hills or parked cars.","Veye timoun toupre lekòl, pak, arè bis ak teren jwèt, ak granmoun toupre sant pou granmoun. Gade si gen moun ki kache dèyè koub, mòn oswa machin ki pake.","Surveillez les enfants près des écoles, parcs, arrêts d'autobus et terrains de jeu, et les aînés près des centres pour personnes âgées. Cherchez les personnes cachées par un virage, une côte ou des voitures garées.","Cuide a los niños cerca de escuelas, parques, paradas y áreas de juego, y a los mayores cerca de centros para ancianos. Busque personas ocultas por curvas, cuestas o autos estacionados.")),
   ("li",("Before backing up, check behind the car and turn your head to look. Do not rely only on mirrors or sensors.","Anvan w fè bak, gade dèyè machin nan epi vire tèt ou pou w gade. Pa konte sèlman sou miwa oswa detektè yo.","Avant de reculer, vérifiez derrière la voiture et tournez la tête pour regarder. Ne vous fiez pas qu'aux rétroviseurs ou capteurs.","Antes de retroceder, revise detrás del auto y gire la cabeza para mirar. No confíe solo en los espejos o sensores.")),
   ("li",("You cannot tell by looking whether someone is Deaf or hard of hearing. Do not assume people can hear your car: it is always safer to yield.","Ou pa ka konnen lè w gade yon moun si l soud oswa si l gen difikilte pou tande. Pa sipoze moun yo ka tande machin ou: li toujou pi san danje pou w bay dwa de pasaj.","On ne peut pas voir si une personne est sourde ou malentendante. Ne supposez pas qu'on entend votre voiture : céder est toujours plus sûr.","No se puede saber a simple vista si alguien es sordo o tiene problemas de audición. No suponga que lo oyen: siempre es más seguro ceder."))]),
  dict(h=("Bicycles","Bisiklèt","Vélos","Bicicletas"), pg="50–51, 112–117", b=[
   ("li",("Bicyclists have the same right to the road as drivers and may use the full lane, even where there is a bike lane. They may legally ride to the right of traffic.","Siklis yo gen menm dwa sou wout la ak chofè yo epi yo ka sèvi ak tout vwa a, menm kote gen yon vwa bisiklèt. Lalwa pèmèt yo woule sou bò dwat machin yo.","Les cyclistes ont le même droit à la route que les conducteurs et peuvent occuper toute la voie, même s'il y a une bande cyclable. Ils peuvent légalement rouler à droite de la circulation.","Los ciclistas tienen el mismo derecho al camino que los conductores y pueden usar todo el carril, aunque haya un carril para bicicletas. Pueden ir legalmente a la derecha del tráfico.")),
   ("li",("Pass a bicyclist slowly with at least four feet of space, wait if the lane is too narrow, and do not cut back in or turn right sharply in front of them after passing.","Depase yon siklis dousman ak omwen kat pye espas, tann si vwa a twò etwat, epi pa koupe devan l ni vire adwat sanzatann devan l apre w fin depase l.","Dépassez un cycliste lentement avec au moins quatre pieds d'espace, attendez si la voie est trop étroite, et ne vous rabattez pas ni ne tournez brusquement à droite devant lui après le dépassement.","Rebase a un ciclista despacio y con al menos cuatro pies de espacio, espere si el carril es angosto, y no se le cierre ni gire bruscamente a la derecha frente a él después de rebasar.")),
   ("li",("Turning left, yield to oncoming bicyclists. Before opening a car door, check mirrors and use the hand farther from the door (the Dutch Reach). Opening a door into a bicyclist can bring a fine of up to $100.","Lè w ap vire agoch, bay siklis k ap vini yo dwa de pasaj. Anvan w louvri pòt machin nan, gade miwa yo epi sèvi ak men ki pi lwen pòt la (Dutch Reach). Louvri yon pòt sou yon siklis ka koute w jiska $100 amann.","En tournant à gauche, cédez aux cyclistes en face. Avant d'ouvrir une portière, regardez les rétroviseurs et utilisez la main la plus éloignée de la portière (Dutch Reach). Ouvrir une portière sur un cycliste peut coûter jusqu'à 100 $.","Al girar a la izquierda, ceda a los ciclistas de frente. Antes de abrir la puerta, revise los espejos y use la mano más lejana a la puerta (Dutch Reach). Abrir la puerta contra un ciclista puede costar hasta $100.")),
   ("li",("Stop behind a green bicycle box at a red light, even when it is empty. Riders and passengers under 16 must wear a bicycle helmet.","Kanpe dèyè yon bwat bisiklèt vèt nan limyè wouj, menm lè l vid. Siklis ak pasaje ki poko gen 16 an dwe mete yon kas bisiklèt.","Arrêtez-vous derrière un sas vélo vert au feu rouge, même vide. Les cyclistes et passagers de moins de 16 ans doivent porter un casque.","Pare detrás de una caja verde para bicicletas con luz roja, aunque esté vacía. Los ciclistas y pasajeros menores de 16 deben usar casco."))]),
  dict(h=("Motorcycles and mopeds","Moto ak moped","Motos et cyclomoteurs","Motos y ciclomotores"), pg="51–53", b=[
   ("li",("Drivers often overlook motorcycles. Check twice before changing lanes or turning left, and let an oncoming motorcycle pass through the intersection first.","Chofè yo konn pa wè moto. Gade de fwa anvan w chanje vwa oswa vire agoch, epi kite yon moto k ap vini pase nan kafou a anvan.","Les conducteurs remarquent mal les motos. Regardez deux fois avant de changer de voie ou de tourner à gauche, et laissez passer d'abord une moto qui arrive en face.","Los conductores suelen no ver las motos. Mire dos veces antes de cambiar de carril o girar a la izquierda, y deje que una moto de frente pase primero la intersección.")),
   ("li",("A motorcycle has the right to the full width of a lane. Never share a lane with one. Keep a four-second following distance.","Yon moto gen dwa sèvi ak tout lajè yon vwa. Pa janm pataje yon vwa ak yon moto. Kenbe kat segonn distans dèyè l.","Une moto a droit à toute la largeur de la voie. Ne partagez jamais une voie avec elle. Gardez quatre secondes de distance.","Una moto tiene derecho a todo el ancho del carril. Nunca comparta un carril con ella. Deje cuatro segundos de distancia.")),
   ("li",("A moped (motorized bicycle) may not go faster than 25 mph and needs a driver's license or learner's permit. A motorized scooter is limited to 20 mph. Riders of both must wear a DOT helmet.","Yon moped (bisiklèt ak motè) pa ka depase 25 mph epi li mande yon lisans oswa yon pèmi apranti. Yon eskoutè ak motè limite a 20 mph. Moun ki monte tou de dwe mete yon kas DOT.","Un cyclomoteur (vélo motorisé) ne peut pas dépasser 25 mph et exige un permis ou un permis d'apprenti. Une trottinette motorisée est limitée à 20 mph. Le casque DOT est obligatoire pour les deux.","Un ciclomotor (bicicleta motorizada) no puede pasar de 25 mph y requiere licencia o permiso de aprendiz. Una patineta motorizada está limitada a 20 mph. Ambos requieren casco DOT."))]),
  dict(h=("School buses, trolleys and transit","Bis lekòl, trole ak transpò piblik","Autobus scolaires, tramways et transports","Autobuses escolares, tranvías y transporte"), pg="105, 107", b=[
   ("li",("When a school bus has its red lights flashing and stop sign out, you must stop, whichever side of the road you are on, and stay stopped until the lights stop and the sign folds back.","Lè yon bis lekòl gen limyè wouj li k ap limen etèn epi siy stop li louvri, ou dwe kanpe, kèlkeswa bò wout ou ye a, epi rete kanpe jiskaske limyè yo sispann epi siy la fèmen.","Quand un autobus scolaire a ses feux rouges clignotants et son panneau d'arrêt sorti, vous devez vous arrêter, quel que soit votre côté de la route, jusqu'à ce que les feux s'éteignent et que le panneau se replie.","Cuando un autobús escolar tiene las luces rojas intermitentes y el letrero de alto extendido, debe parar, sin importar de qué lado del camino esté, hasta que se apaguen las luces y se doble el letrero.")),
   ("li",("The only exception is a bus on the other side of a divided highway with a barrier. A first violation can bring a license suspension and a $250 fine.","Sèl eksepsyon an se yon bis ki sou lòt bò yon otowout divize ki gen yon baryè. Premye vyolasyon ka bay yon sispansyon lisans ak yon amann $250.","La seule exception : un autobus de l'autre côté d'une route divisée par une barrière. Une première infraction peut entraîner une suspension et 250 $ d'amende.","La única excepción es un autobús del otro lado de una carretera dividida con barrera. La primera infracción puede traer suspensión y $250 de multa.")),
   ("li",("Stay at least eight feet from a trolley's passenger step while people get on or off. Let buses pull out from their stops.","Rete omwen uit pye de mach pasaje yon trole pandan moun ap monte oswa desann. Kite bis yo soti nan arè yo.","Restez à au moins huit pieds de la marche d'un tramway pendant la montée ou la descente des passagers. Laissez les autobus quitter leur arrêt.","Quédese al menos a ocho pies del escalón de un tranvía mientras suben o bajan pasajeros. Deje que los autobuses salgan de sus paradas."))]),
  dict(h=("Trucks, slow vehicles, animals and other drivers","Kamyon, machin ki lan, bèt ak lòt chofè","Camions, véhicules lents, animaux et autres conducteurs","Camiones, vehículos lentos, animales y otros conductores"), pg="104–109", b=[
   ("li",("Large trucks have big blind spots on all four sides. If you cannot see a truck's mirrors, the driver cannot see you. Trucks may need twice the stopping distance, so never cut in front of one.","Gwo kamyon gen gwo kwen avèg sou kat bò yo. Si w pa ka wè miwa yon kamyon, chofè a pa ka wè w. Kamyon ka bezwen de fwa distans pou kanpe, kidonk pa janm koupe devan youn.","Les gros camions ont de grands angles morts des quatre côtés. Si vous ne voyez pas les rétroviseurs du camion, le chauffeur ne vous voit pas. Un camion peut avoir besoin du double de distance pour s'arrêter : ne vous rabattez jamais devant.","Los camiones grandes tienen puntos ciegos amplios en los cuatro lados. Si no ve los espejos del camión, el chofer no lo ve a usted. Pueden necesitar el doble para frenar, así que nunca se les meta adelante.")),
   ("li",("Trucks and buses make wide right turns and may swing left first. Do not pass them on the right; stay behind until you know what the driver is doing.","Kamyon ak bis vire adwat byen laj epi yo ka ale agoch anvan. Pa depase yo sou bò dwat; rete dèyè jiskaske w konnen sa chofè a pral fè.","Camions et autobus tournent large à droite et peuvent d'abord se déporter à gauche. Ne les dépassez pas par la droite ; restez derrière jusqu'à savoir ce que fait le chauffeur.","Camiones y autobuses giran abierto a la derecha y pueden moverse antes a la izquierda. No los rebase por la derecha; quédese atrás hasta saber qué hará el chofer.")),
   ("li",("An orange triangle on the back marks a slow-moving vehicle: slow down. Funeral processions have the right-of-way at intersections; do not join one or drive between its vehicles.","Yon triyang zoranj dèyè yon veyikil make se yon veyikil ki mache dousman: ralanti. Kòtèj fineray gen dwa de pasaj nan kafou yo; pa antre nan youn ni pase ant machin li yo.","Un triangle orange à l'arrière signale un véhicule lent : ralentissez. Les cortèges funèbres ont la priorité aux intersections ; ne vous y joignez pas et ne passez pas entre leurs véhicules.","Un triángulo naranja atrás marca un vehículo lento: baje la velocidad. Los cortejos fúnebres tienen el derecho de paso en las intersecciones; no se una a uno ni pase entre sus vehículos.")),
   ("li",("Give the right-of-way to animals being led, ridden or driven. Slow down, do not honk, and pull over and stop if an animal looks scared.","Bay bèt yon moun ap mennen, monte oswa kondui dwa de pasaj. Ralanti, pa klaksonnen, epi rale sou kote epi kanpe si bèt la sanble l pè.","Cédez le passage aux animaux menés, montés ou attelés. Ralentissez, ne klaxonnez pas, et rangez-vous pour vous arrêter si l'animal semble effrayé.","Ceda el paso a los animales guiados, montados o de tiro. Baje la velocidad, no toque el claxon y deténgase a un lado si el animal parece asustado.")),
   ("li",("If an aggressive driver confronts you, get out of their way, do not challenge them, avoid eye contact and ignore gestures. Call 911 to report an emergency.","Si yon chofè agresif fè w fas, retire kò w nan chemen l, pa defye l, evite gade l nan je epi pa okipe jès li yo. Rele 911 pou rapòte yon ijans.","Face à un conducteur agressif, écartez-vous, ne le provoquez pas, évitez son regard et ignorez ses gestes. Appelez le 911 pour signaler une urgence.","Si un conductor agresivo lo confronta, apártese, no lo desafíe, evite mirarlo a los ojos e ignore sus gestos. Llame al 911 para reportar una emergencia."))], sign="smv")],
 terms=[("vulnerable road user","moun ki pi frajil sou wout la","usager vulnérable","usuario vulnerable"),("bicyclist","siklis","cycliste","ciclista"),("moped","moped","cyclomoteur","ciclomotor"),
        ("school bus","bis lekòl","autobus scolaire","autobús escolar"),("blind spot","kwen avèg","angle mort","punto ciego"),("slow-moving vehicle","veyikil ki mache dousman","véhicule lent","vehículo lento")],
 qs=[
  ("pm301",2,0,("vulnerable road user","moun ki pi frajil sou wout la","usager vulnérable","usuario vulnerable"),
   ("How much space must you leave when passing a bicyclist, pedestrian or roadside worker?","Konbyen espas ou dwe kite lè w ap depase yon siklis, yon pyeton oswa yon travayè bò wout?","Quel espace devez-vous laisser en dépassant un cycliste, un piéton ou un travailleur en bord de route ?","¿Cuánto espacio debe dejar al rebasar a un ciclista, peatón o trabajador en la vía?"),
   ("At least one foot","Omwen yon pye","Au moins un pied (30 cm)","Al menos un pie"),("At least two feet","Omwen de pye","Au moins deux pieds (60 cm)","Al menos dos pies"),("At least four feet","Omwen kat pye","Au moins quatre pieds","Al menos cuatro pies"),("Ten feet","Dis pye","Dix pieds","Diez pies"),
   ("Massachusetts law requires at least four feet when passing a vulnerable road user. If safe, you may use part of the next lane or cross the center line, without speeding.","Lwa Massachusetts mande omwen kat pye lè w ap depase yon moun ki frajil sou wout la. Si l san danje, ou ka sèvi ak yon pati nan vwa bò kote a oswa travèse liy mitan an, san w pa depase limit vitès la.","La loi exige au moins quatre pieds pour dépasser un usager vulnérable. Si c'est sûr, on peut empiéter sur la voie voisine ou franchir la ligne centrale, sans excès de vitesse.","La ley exige al menos cuatro pies al rebasar a un usuario vulnerable. Si es seguro, puede usar parte del carril de al lado o cruzar la línea central, sin exceder el límite.")),
  ("pm302",0,0,("roadside worker","travayè bò wout","travailleur en bord de route","trabajador en la vía"),
   ("Which of these is a vulnerable road user under Massachusetts law?","Kiyès nan moun sa yo ki se yon moun ki frajil sou wout la dapre lwa Massachusetts?","Lequel de ces usagers est vulnérable selon la loi du Massachusetts ?","¿Cuál de estos es un usuario vulnerable según la ley de Massachusetts?"),
   ("A person riding a horse","Yon moun ki monte cheval","Une personne à cheval","Una persona a caballo"),
   ("A truck driver","Yon chofè kamyon","Un chauffeur de camion","Un chofer de camión"),
   ("A bus passenger","Yon pasaje bis","Un passager d'autobus","Un pasajero de autobús"),
   ("A driver in a parked car","Yon chofè nan yon machin ki pake","Un conducteur dans une voiture garée","Un conductor en un auto estacionado"),
   ("Vulnerable road users include pedestrians, roadside workers, bicyclists, people riding horses, and people using wheelchairs, mopeds, scooters, skateboards or roller skates.","Moun ki frajil sou wout la gen ladan pyeton, travayè bò wout, siklis, moun ki monte cheval, ak moun ki sèvi ak chèz woulant, moped, eskoutè, skateboard oswa paten.","Les usagers vulnérables incluent piétons, travailleurs en bord de route, cyclistes, cavaliers et personnes en fauteuil, cyclomoteur, trottinette, planche ou patins.","Los usuarios vulnerables incluyen peatones, trabajadores en la vía, ciclistas, jinetes y personas en silla de ruedas, ciclomotor, patineta, skateboard o patines.")),
  ("pm303",3,1,("backing up","fè bak","marche arrière","retroceder"),
   ("Your car has a backup camera. What should you still do before backing out of a driveway?","Machin ou gen yon kamera pou fè bak. Kisa ou toujou dwe fè anvan w fè bak soti nan yon antre kay?","Votre voiture a une caméra de recul. Que devez-vous quand même faire avant de reculer d'une allée ?","Su auto tiene cámara de reversa. ¿Qué debe hacer igual antes de salir en reversa de una entrada?"),
   ("Nothing; the camera is enough","Anyen; kamera a ase","Rien ; la caméra suffit","Nada; la cámara basta"),
   ("Honk three times","Klaksonnen twa fwa","Klaxonner trois fois","Tocar el claxon tres veces"),
   ("Back up quickly to limit the time in the road","Fè bak vit pou w pa pase twòp tan nan wout la","Reculer vite pour limiter le temps sur la chaussée","Retroceder rápido para estar poco tiempo en la calle"),
   ("Check behind the car and turn your head to look","Gade dèyè machin nan epi vire tèt ou pou w gade","Vérifier derrière la voiture et tourner la tête pour regarder","Revisar detrás del auto y girar la cabeza para mirar"),
   ("Blind spots can hide children or animals. Check behind the vehicle before getting in, and turn your head and look out the window as you back up. Do not rely only on mirrors or sensors.","Kwen avèg yo ka kache timoun oswa bèt. Gade dèyè machin nan anvan w monte, epi vire tèt ou gade nan fenèt la pandan w ap fè bak. Pa konte sèlman sou miwa oswa detektè.","Les angles morts peuvent cacher enfants ou animaux. Vérifiez derrière avant de monter, puis tournez la tête et regardez par la fenêtre en reculant. Ne vous fiez pas qu'aux rétroviseurs ou capteurs.","Los puntos ciegos pueden ocultar niños o animales. Revise detrás antes de subir y gire la cabeza mirando por la ventana al retroceder. No confíe solo en espejos o sensores.")),
  ("pm304",1,1,("Deaf or hard of hearing","soud oswa difikilte pou tande","sourd ou malentendant","sordo o con problemas de audición"),
   ("A pedestrian steps into the street without looking toward your car. What is the safest assumption?","Yon pyeton antre nan ri a san l pa gade machin ou. Ki sa ki pi san danje pou w panse?","Un piéton s'engage sans regarder votre voiture. Quelle est l'hypothèse la plus sûre ?","Un peatón baja a la calle sin mirar su auto. ¿Qué es lo más seguro suponer?"),
   ("They heard you and will stop","Li tande w epi l ap kanpe","Il vous a entendu et va s'arrêter","Lo oyó y se detendrá"),
   ("They may not hear your car, so yield","Li ka pa tande machin ou, kidonk bay dwa de pasaj","Il n'entend peut-être pas votre voiture : cédez","Puede que no oiga su auto, así que ceda"),
   ("They are breaking the law, so you may continue","L ap vyole lalwa, kidonk ou ka kontinye","Il enfreint la loi, vous pouvez continuer","Está violando la ley, así que puede seguir"),
   ("Honking will always solve it","Klaksonnen ap toujou rezoud sa","Klaxonner règle toujours le problème","Tocar el claxon siempre lo resuelve"),
   ("You cannot tell by looking whether someone is Deaf or hard of hearing. It is always safer to yield, even if you have the right-of-way.","Ou pa ka konnen lè w gade yon moun si l soud oswa si l gen difikilte pou tande. Li toujou pi san danje pou w bay dwa de pasaj, menm si se ou ki gen dwa a.","On ne peut pas voir si quelqu'un est sourd ou malentendant. Il est toujours plus sûr de céder, même si vous avez la priorité.","No se puede saber a simple vista si alguien es sordo. Siempre es más seguro ceder, aunque usted tenga el derecho de paso.")),
  ("pm305",2,2,("full lane","tout vwa a","toute la voie","todo el carril"),
   ("A bicyclist is riding in the middle of the lane on a street that has a bike lane. Which is true?","Yon siklis ap woule nan mitan vwa a sou yon ri ki gen yon vwa bisiklèt. Kisa ki vre?","Un cycliste roule au milieu de la voie dans une rue qui a une bande cyclable. Qu'est-ce qui est vrai ?","Un ciclista va por el centro del carril en una calle con carril para bicicletas. ¿Qué es cierto?"),
   ("They must use the bike lane","Li oblije sèvi ak vwa bisiklèt la","Il doit utiliser la bande cyclable","Debe usar el carril para bicicletas"),
   ("You may honk until they move","Ou ka klaksonnen jiskaske l deplase","Vous pouvez klaxonner jusqu'à ce qu'il se range","Puede tocar el claxon hasta que se quite"),
   ("Bicyclists may use the full lane, even where there is a bike lane","Siklis yo ka sèvi ak tout vwa a, menm kote gen yon vwa bisiklèt","Les cyclistes peuvent occuper toute la voie, même avec une bande cyclable","Los ciclistas pueden usar todo el carril, aunque haya carril para bicicletas"),
   ("Bicycles are not allowed on streets with bike lanes","Bisiklèt pa gen dwa sou ri ki gen vwa bisiklèt","Les vélos sont interdits dans les rues avec bande cyclable","Las bicicletas no pueden ir por calles con carril para bicicletas"),
   ("Bicyclists can use the full lane anywhere, anytime, on any street except posted limited-access highways, even where there is a bike lane. Pass only when you can leave at least four feet.","Siklis yo ka sèvi ak tout vwa a nenpòt kote, nenpòt lè, sou nenpòt ri sof otowout ak aksè limite ki make, menm kote gen yon vwa bisiklèt. Depase sèlman lè w ka kite omwen kat pye.","Les cyclistes peuvent occuper toute la voie partout, en tout temps, sauf sur les autoroutes à accès limité signalées, même avec une bande cyclable. Dépassez seulement avec au moins quatre pieds.","Los ciclistas pueden usar todo el carril en cualquier calle y momento, salvo autopistas de acceso limitado señalizadas, aunque haya carril para bicicletas. Rebase solo si puede dejar cuatro pies.")),
  ("pm306",3,2,("Dutch Reach","Dutch Reach (louvri ak lòt men an)","Dutch Reach (main opposée)","Dutch Reach (mano contraria)"),
   ("You parked on a busy street. What is the best way to open your door?","Ou pake sou yon ri ki gen anpil moun. Ki pi bon fason pou w louvri pòt ou?","Vous êtes garé dans une rue animée. Quelle est la meilleure façon d'ouvrir la portière ?","Se estacionó en una calle concurrida. ¿Cuál es la mejor forma de abrir la puerta?"),
   ("Push it open quickly so you are in the way for less time","Pouse l louvri vit pou w pa bloke wout la twò lontan","La pousser vite pour gêner moins longtemps","Abrirla rápido para estorbar menos tiempo"),
   ("Open it a little and wait","Louvri l yon ti kras epi tann","L'entrouvrir et attendre","Abrirla un poco y esperar"),
   ("Turn on your left signal, then open it","Limen siyal goch ou, apre sa louvri l","Mettre le clignotant gauche, puis l'ouvrir","Poner la direccional izquierda y luego abrirla"),
   ("Check your mirrors, then open it with the hand farther from the door","Gade miwa yo, apre sa louvri l ak men ki pi lwen pòt la","Regarder les rétroviseurs, puis l'ouvrir avec la main la plus éloignée","Revisar los espejos y abrirla con la mano más lejana a la puerta"),
   ("Check your rear-view and side mirrors, then use the far hand (the Dutch Reach). Your body turns so you see bicyclists coming. Opening a door into a bicyclist can cost up to $100.","Gade miwa dèyè a ak miwa sou kote a, apre sa sèvi ak men ki pi lwen an (Dutch Reach). Kò w vire konsa ou wè siklis k ap vini yo. Louvri yon pòt sou yon siklis ka koute jiska $100.","Regardez le rétroviseur intérieur et extérieur, puis utilisez la main éloignée (Dutch Reach). Votre corps pivote et vous voyez les cyclistes. Ouvrir sur un cycliste peut coûter jusqu'à 100 $.","Revise el retrovisor y el espejo lateral y use la mano lejana (Dutch Reach). Su cuerpo gira y ve a los ciclistas. Abrir la puerta contra un ciclista puede costar hasta $100.")),
  ("pm307",1,2,("right hook","vire adwat devan siklis","crochet à droite","gancho derecho"),
   ("You just passed a bicyclist and want to turn right at the next driveway. What should you do?","Ou fèk depase yon siklis epi ou vle vire adwat nan pwochen antre a. Kisa ou dwe fè?","Vous venez de dépasser un cycliste et voulez tourner à droite à la prochaine entrée. Que faire ?","Acaba de rebasar a un ciclista y quiere girar a la derecha en la siguiente entrada. ¿Qué debe hacer?"),
   ("Turn right away, in front of them, before they reach the driveway","Vire touswit, devan l, anvan l rive nan antre a","Tourner tout de suite, devant lui, avant qu'il arrive à l'entrée","Girar enseguida, delante de él, antes de que llegue a la entrada"),
   ("Turn only when you are a safe distance ahead, or let them pass first","Vire sèlman lè w byen lwen devan l, oswa kite l pase anvan","Tourner seulement à bonne distance devant, ou le laisser passer d'abord","Girar solo cuando esté a distancia segura, o dejarlo pasar primero"),
   ("Honk so they stop","Klaksonnen pou l kanpe","Klaxonner pour qu'il s'arrête","Tocar el claxon para que pare"),
   ("Speed up to get well ahead, then brake hard to turn","Akselere pou w byen devan, apre sa frennen fò pou vire","Accélérer pour bien le dépasser, puis freiner fort pour tourner","Acelerar para adelantarse bien y luego frenar fuerte para girar"),
   ("Do not make an abrupt right turn after passing a bicyclist. Turn only at a safe distance and a reasonable speed. Bicycles may legally ride on your right.","Pa vire adwat sanzatann apre w fin depase yon siklis. Vire sèlman lè w byen lwen epi a yon vitès rezonab. Lalwa pèmèt bisiklèt woule sou bò dwat ou.","Ne tournez pas brusquement à droite après avoir dépassé un cycliste. Tournez seulement à distance sûre et à vitesse raisonnable. Les vélos peuvent légalement rouler à votre droite.","No gire bruscamente a la derecha tras rebasar a un ciclista. Gire solo a distancia segura y velocidad razonable. Las bicicletas pueden ir legalmente a su derecha.")),
  ("pm308",0,2,("bicycle box","bwat bisiklèt","sas vélo","caja para bicicletas"),
   ("At a red light, a green box with a bicycle symbol is painted ahead of the crosswalk. Where do you stop?","Nan yon limyè wouj, gen yon bwat vèt ak yon desen bisiklèt pentire devan pasaj pyeton an. Ki kote ou kanpe?","Au feu rouge, un carré vert avec un vélo est peint avant le passage piéton. Où vous arrêtez-vous ?","Con luz roja, hay una caja verde con un símbolo de bicicleta antes del cruce. ¿Dónde se detiene?"),
   ("Behind the bicycle box, even if it is empty","Dèyè bwat bisiklèt la, menm si l vid","Derrière le sas vélo, même vide","Detrás de la caja para bicicletas, aunque esté vacía"),
   ("Inside the box if no bicycles are there","Anndan bwat la si pa gen bisiklèt","Dans le sas s'il n'y a pas de vélo","Dentro de la caja si no hay bicicletas"),
   ("On the crosswalk","Sou pasaj pyeton an","Sur le passage piéton","Sobre el cruce peatonal"),
   ("Anywhere, as long as you stop","Nenpòt kote, depi w kanpe","N'importe où, pourvu qu'on s'arrête","Donde sea, mientras pare"),
   ("Drivers must stop behind a bicycle box, even when it is empty, and wait for the green light.","Chofè yo dwe kanpe dèyè yon bwat bisiklèt, menm lè l vid, epi tann limyè vèt la.","Les conducteurs doivent s'arrêter derrière le sas vélo, même vide, et attendre le vert.","Los conductores deben parar detrás de la caja para bicicletas, aunque esté vacía, y esperar el verde.")),
  ("pm309",2,2,("bicycle helmet","kas bisiklèt","casque de vélo","casco de bicicleta"),
   ("Who must wear a bicycle helmet in Massachusetts?","Kiyès ki dwe mete yon kas bisiklèt nan Massachusetts?","Qui doit porter un casque de vélo au Massachusetts ?","¿Quién debe usar casco de bicicleta en Massachusetts?"),
   ("Everyone","Tout moun","Tout le monde","Todos"),("Only riders over 18","Sèlman moun ki gen plis pase 18 an","Seulement les plus de 18 ans","Solo los mayores de 18"),("Riders and passengers under 16","Siklis ak pasaje ki poko gen 16 an","Les cyclistes et passagers de moins de 16 ans","Ciclistas y pasajeros menores de 16"),("No one; it is optional","Pèsonn; se opsyonèl","Personne ; c'est facultatif","Nadie; es opcional"),
   ("A bicycle operator or passenger under 16 must wear an approved helmet on public ways and bike paths. Helmets greatly reduce deaths and serious injuries for everyone.","Yon siklis oswa pasaje ki poko gen 16 an dwe mete yon kas apwouve sou wout piblik ak chemen bisiklèt. Kas yo diminye anpil lanmò ak blesi grav pou tout moun.","Un cycliste ou passager de moins de 16 ans doit porter un casque homologué sur la voie publique et les pistes. Le casque réduit beaucoup les décès et blessures graves pour tous.","Un ciclista o pasajero menor de 16 debe usar casco aprobado en vías públicas y ciclovías. El casco reduce mucho las muertes y lesiones graves para todos.")),
  ("pm310",3,3,("motorcycle","moto","moto","motocicleta"),
   ("A motorcycle is riding on the left side of a wide lane. May you pull up beside it in the same lane?","Yon moto ap woule sou bò goch yon vwa ki laj. Èske w ka vin kanpe bò kote l nan menm vwa a?","Une moto roule à gauche d'une voie large. Pouvez-vous vous placer à côté d'elle dans la même voie ?","Una moto va por el lado izquierdo de un carril ancho. ¿Puede ponerse a su lado en el mismo carril?"),
   ("Yes, if the lane is wide enough","Wi, si vwa a laj ase","Oui, si la voie est assez large","Sí, si el carril es suficientemente ancho"),
   ("Yes, but only in slow traffic","Wi, men sèlman lè sikilasyon an lan","Oui, mais seulement en circulation lente","Sí, pero solo en tráfico lento"),
   ("Yes, if you signal first","Wi, si w mete siyal anvan","Oui, si vous signalez d'abord","Sí, si señala primero"),
   ("No; never share a lane with a motorcycle","Non; pa janm pataje yon vwa ak yon moto","Non ; ne partagez jamais une voie avec une moto","No; nunca comparta un carril con una moto"),
   ("A motorcycle has the right to the full width of a lane. Crowding into its lane is illegal and very dangerous, even if the lane is wide.","Yon moto gen dwa sèvi ak tout lajè yon vwa. Antre nan vwa li a ilegal epi danjere anpil, menm si vwa a laj.","Une moto a droit à toute la largeur de la voie. S'y serrer est illégal et très dangereux, même si la voie est large.","Una moto tiene derecho a todo el ancho del carril. Meterse en su carril es ilegal y muy peligroso, aunque el carril sea ancho.")),
  ("pm311",0,3,("left turn","vire agoch","virage à gauche","giro a la izquierda"),
   ("You are waiting to turn left. An oncoming motorcycle is approaching the intersection. What should you do?","W ap tann pou vire agoch. Yon moto k ap vini ap pwoche kafou a. Kisa ou dwe fè?","Vous attendez pour tourner à gauche. Une moto approche en face. Que faire ?","Espera para girar a la izquierda. Una moto de frente se acerca a la intersección. ¿Qué debe hacer?"),
   ("Let the motorcycle pass through first","Kite moto a pase anvan","Laisser la moto passer d'abord","Dejar que la moto pase primero"),
   ("Turn quickly in front of it","Vire vit devan l","Tourner vite devant elle","Girar rápido frente a ella"),
   ("Flash your lights and turn","Fè limyè w kliyote epi vire","Faire un appel de phares et tourner","Hacer cambio de luces y girar"),
   ("Turn; motorcycles can stop quickly","Vire; moto ka kanpe vit","Tourner ; les motos s'arrêtent vite","Girar; las motos frenan rápido"),
   ("Cars turning left in front of oncoming motorcycles cause many crashes. Their speed is hard to judge, and the rider may not have time to slow down. Let the motorcycle pass first.","Machin ki vire agoch devan moto k ap vini lakoz anpil aksidan. Li difisil pou w konnen vitès yo, epi moun ki sou moto a ka pa gen tan ralanti. Kite moto a pase anvan.","Les voitures qui tournent à gauche devant une moto causent beaucoup d'accidents. Sa vitesse est difficile à juger et le motard peut ne pas avoir le temps de ralentir. Laissez-la passer.","Los autos que giran a la izquierda frente a motos causan muchos choques. Es difícil calcular su velocidad y el motociclista puede no alcanzar a frenar. Déjela pasar primero.")),
  ("pm312",1,3,("moped","moped","cyclomoteur","ciclomotor"),
   ("Which rule applies to driving a moped (motorized bicycle) in Massachusetts?","Ki règ ki aplike pou kondui yon moped (bisiklèt ak motè) nan Massachusetts?","Quelle règle s'applique à la conduite d'un cyclomoteur au Massachusetts ?","¿Qué regla aplica para manejar un ciclomotor en Massachusetts?"),
   ("No license or permit is needed if it goes under 30 mph","Ou pa bezwen lisans ni pèmi si l pa depase 30 mph","Aucun permis n'est nécessaire s'il roule à moins de 30 mph","No se necesita licencia ni permiso si va a menos de 30 mph"),
   ("You need a license or learner's permit, and may not exceed 25 mph","Ou bezwen yon lisans oswa yon pèmi apranti, epi ou pa ka depase 25 mph","Il faut un permis ou un permis d'apprenti, et ne pas dépasser 25 mph","Necesita licencia o permiso de aprendiz, y no puede pasar de 25 mph"),
   ("You may ride on highways if you stay in the right lane","Ou ka monte sou gran wout si w rete nan liy dwat la","Vous pouvez rouler sur l'autoroute si vous restez dans la voie de droite","Puede andar en autopistas si se queda en el carril derecho"),
   ("Helmets are optional","Kas se opsyonèl","Le casque est facultatif","El casco es opcional"),
   ("A moped needs a valid driver's license (any class) or learner's permit. Do not drive faster than 25 mph, wear a DOT helmet, and stay off limited-access highways. With a permit, carry no passengers.","Yon moped mande yon lisans (nenpòt klas) oswa yon pèmi apranti. Pa kondui pi vit pase 25 mph, mete yon kas DOT, epi pa monte sou otowout ak aksè limite. Ak yon pèmi, pa pote pasaje.","Un cyclomoteur exige un permis (toute classe) ou un permis d'apprenti. Pas plus de 25 mph, casque DOT, et pas d'autoroute à accès limité. Avec un permis d'apprenti, aucun passager.","Un ciclomotor requiere licencia (cualquier clase) o permiso de aprendiz. No pase de 25 mph, use casco DOT y no vaya por autopistas de acceso limitado. Con permiso, sin pasajeros.")),
  ("pm313",2,4,("school bus","bis lekòl","autobus scolaire","autobús escolar"),
   ("On a two-lane road, a school bus coming toward you stops with red lights flashing and its stop sign out. What must you do?","Sou yon wout de vwa, yon bis lekòl k ap vin sou ou kanpe ak limyè wouj k ap limen etèn epi siy stop li louvri. Kisa ou dwe fè?","Sur une route à deux voies, un autobus scolaire venant en face s'arrête, feux rouges clignotants et panneau sorti. Que devez-vous faire ?","En un camino de dos carriles, un autobús escolar de frente se detiene con luces rojas intermitentes y el letrero de alto afuera. ¿Qué debe hacer?"),
   ("Slow down and pass carefully, since it is on the other side of the road","Ralanti epi pase ak prekosyon, paske l lòt bò wout la","Ralentir et passer prudemment, puisqu'il est de l'autre côté de la route","Reducir la velocidad y pasar con cuidado, ya que está del otro lado"),
   ("Nothing; it is on the other side","Anyen; li sou lòt bò a","Rien ; il est de l'autre côté","Nada; está del otro lado"),
   ("Stop and stay stopped until the lights stop and the sign folds back","Kanpe epi rete kanpe jiskaske limyè yo sispann epi siy la fèmen","S'arrêter et rester arrêté jusqu'à ce que les feux s'éteignent et que le panneau se replie","Parar y quedarse hasta que se apaguen las luces y se doble el letrero"),
   ("Honk to warn the children, then go","Klakonnen pou avèti timoun yo, apre sa ale","Klaxonner pour avertir les enfants, puis passer","Tocar el claxon para avisar a los niños y luego seguir"),
   ("You must stop for a school bus with flashing red lights and its stop sign out, whichever side of the road you are on. Even after it moves, go slowly and watch for children.","Ou dwe kanpe pou yon bis lekòl ki gen limyè wouj k ap limen etèn ak siy stop li louvri, kèlkeswa bò wout ou ye a. Menm apre l fin ale, kondui dousman epi veye timoun yo.","Vous devez vous arrêter pour un autobus scolaire aux feux rouges clignotants et panneau sorti, quel que soit votre côté. Même après, roulez lentement et surveillez les enfants.","Debe parar ante un autobús escolar con luces rojas intermitentes y letrero afuera, sin importar el lado del camino. Aun después, avance despacio y cuide a los niños.")),
  ("pm314",3,4,("divided highway","otowout divize","route divisée","carretera dividida"),
   ("When are you NOT required to stop for a school bus with flashing red lights?","Kilè ou PA oblije kanpe pou yon bis lekòl ki gen limyè wouj k ap limen etèn?","Quand n'êtes-vous PAS obligé de vous arrêter pour un autobus scolaire aux feux rouges clignotants ?","¿Cuándo NO está obligado a parar ante un autobús escolar con luces rojas intermitentes?"),
   ("When you are in a hurry","Lè w prese","Quand vous êtes pressé","Cuando tiene prisa"),
   ("When no children are visible near the bus or the road","Lè w pa wè okenn timoun bò bis la oswa bò wout la","Quand aucun enfant n'est visible près du bus ou de la route","Cuando no se ve ningún niño cerca del autobús o del camino"),
   ("On any road with four lanes, even without a barrier","Sou nenpòt wout ki gen kat liy, menm san baryè","Sur toute route à quatre voies, même sans séparation","En cualquier camino de cuatro carriles, aunque no haya barrera"),
   ("When the bus is on the other side of a divided highway with a barrier","Lè bis la sou lòt bò yon otowout divize ki gen yon baryè","Quand l'autobus est de l'autre côté d'une route divisée par une barrière","Cuando el autobús está del otro lado de una carretera dividida con barrera"),
   ("The only exception is a school bus stopped on the other side of a divided highway with a barrier between the directions.","Sèl eksepsyon an se yon bis lekòl ki kanpe sou lòt bò yon otowout divize ki gen yon baryè ant de direksyon yo.","La seule exception : un autobus scolaire arrêté de l'autre côté d'une route divisée par une barrière.","La única excepción es un autobús escolar detenido del otro lado de una carretera dividida con barrera entre sentidos.")),
  ("pm315",0,4,("school bus violation","vyolasyon bis lekòl","infraction autobus scolaire","infracción de autobús escolar"),
   ("What can a first violation of the school bus stopping law bring?","Kisa premye vyolasyon lwa sou kanpe pou bis lekòl ka bay?","Que peut entraîner une première infraction à la loi sur l'arrêt pour autobus scolaire ?","¿Qué puede traer la primera infracción de la ley de parar ante el autobús escolar?"),
   ("A license suspension and a $250 fine","Yon sispansyon lisans ak yon amann $250","Une suspension de permis et 250 $ d'amende","Una suspensión de licencia y $250 de multa"),
   ("A written warning only, with no fine","Yon avètisman ekri sèlman, san amann","Un avertissement écrit seulement, sans amende","Solo una advertencia por escrito, sin multa"),
   ("A $25 fine and no other penalty","Yon amann $25 e okenn lòt penalite","Une amende de 25 $ sans autre sanction","Una multa de $25 y ninguna otra sanción"),
   ("A required road test","Yon Egzamen Pratik obligatwa","Un examen routier obligatoire","Un examen práctico obligatorio"),
   ("A first violation of the school bus law can cause a license suspension and a $250 fine.","Premye vyolasyon lwa bis lekòl la ka lakoz yon sispansyon lisans ak yon amann $250.","Une première infraction peut entraîner une suspension et 250 $ d'amende.","La primera infracción puede causar una suspensión y una multa de $250.")),
  ("pm316",1,4,("trolley","trole","tramway","tranvía"),
   ("A trolley is stopped and passengers are getting off. How close may you drive to its passenger step?","Yon trole kanpe epi pasaje ap desann. A ki distans ou ka kondui bò mach pasaje li a?","Un tramway est arrêté et des passagers descendent. À quelle distance de sa marche pouvez-vous passer ?","Un tranvía está detenido y bajan pasajeros. ¿A qué distancia de su escalón puede pasar?"),
   ("Two feet","De pye","Deux pieds","Dos pies"),("No closer than eight feet","Pa pi pre pase uit pye","Pas à moins de huit pieds","No a menos de ocho pies"),("Any distance, if you go slowly","Nenpòt distans, si w kondui dousman","N'importe quelle distance, lentement","Cualquier distancia, si va despacio"),("Fifty feet","Senkant pye","Cinquante pieds","Cincuenta pies"),
   ("You must not drive closer than eight feet to a trolley's passenger step while it is loading or unloading. A trolley cannot swerve to avoid you.","Ou pa dwe kondui pi pre pase uit pye de mach pasaje yon trole pandan moun ap monte oswa desann. Yon trole pa ka devye pou evite w.","Ne passez pas à moins de huit pieds de la marche d'un tramway pendant la montée ou la descente. Un tramway ne peut pas vous éviter.","No pase a menos de ocho pies del escalón de un tranvía mientras suben o bajan pasajeros. Un tranvía no puede esquivarlo.")),
  ("pm317",3,5,("blind spot","kwen avèg","angle mort","punto ciego"),
   ("You are following a tractor-trailer and cannot see its side mirrors. What does that mean?","W ap swiv yon gwo kamyon epi ou pa ka wè miwa sou kote l yo. Kisa sa vle di?","Vous suivez un semi-remorque et ne voyez pas ses rétroviseurs. Qu'est-ce que cela signifie ?","Va detrás de un tráiler y no ve sus espejos laterales. ¿Qué significa?"),
   ("You are at a safe distance behind the truck","Ou nan yon bon distans dèyè kamyon an","Vous êtes à une distance sûre derrière le camion","Está a una distancia segura detrás del camión"),
   ("The truck is about to turn or change lanes","Kamyon an pral vire oswa chanje liy","Le camion est sur le point de tourner ou de changer de voie","El camión está a punto de girar o cambiar de carril"),
   ("The mirrors are broken","Miwa yo kase","Les rétroviseurs sont cassés","Los espejos están rotos"),
   ("You are too close: the driver cannot see you","Ou twò pre: chofè a pa ka wè w","Vous êtes trop près : le chauffeur ne vous voit pas","Está demasiado cerca: el chofer no lo ve"),
   ("If you cannot see a truck's rearview mirrors, you are tailgating and in its blind spot. Trucks have blind spots on the right, left, front and behind.","Si w pa ka wè miwa yon kamyon, ou kole twò pre epi w nan kwen avèg li. Kamyon gen kwen avèg sou bò dwat, bò goch, devan ak dèyè.","Si vous ne voyez pas les rétroviseurs du camion, vous le suivez de trop près et êtes dans son angle mort. Les camions ont des angles morts à droite, à gauche, devant et derrière.","Si no ve los espejos del camión, va pegado y en su punto ciego. Los camiones tienen puntos ciegos a la derecha, izquierda, adelante y atrás.")),
  ("pm318",2,5,("wide turn","vire laj","virage large","giro abierto"),
   ("A truck ahead of you moves slightly left with its right signal on. What should you do?","Yon kamyon devan w deplase yon ti kras agoch ak siyal dwat li limen. Kisa ou dwe fè?","Un camion devant vous se déporte un peu à gauche, clignotant droit allumé. Que faire ?","Un camión adelante se mueve un poco a la izquierda con la direccional derecha encendida. ¿Qué debe hacer?"),
   ("Pass it on the right while it moves left","Pase l sou bò dwat pandan l ap deplase agoch","Le dépasser par la droite pendant qu'il se décale à gauche","Rebasarlo por la derecha mientras se mueve a la izquierda"),
   ("Honk to warn the driver that the wrong signal is on","Klakonnen pou avèti chofè a se move siyal la ki limen","Klaxonner pour prévenir le conducteur que le mauvais clignotant est allumé","Tocar el claxon para avisar al conductor que tiene la direccional equivocada"),
   ("Stay behind; it is swinging out to make a wide right turn","Rete dèyè; l ap louvri pou fè yon vire adwat ki laj","Rester derrière ; il s'écarte pour tourner large à droite","Quedarse atrás; se abre para girar ampliamente a la derecha"),
   ("Pull up beside it on the left and wait","Vin kanpe bò kote l sou bò goch epi tann","Vous placer à sa gauche et attendre","Ponerse a su lado izquierdo y esperar"),
   ("Large vehicles make wide turns and may move left before turning right. Do not pass on the right; stay safely behind until you know what the driver is doing.","Gwo veyikil vire laj epi yo ka ale agoch anvan yo vire adwat. Pa depase sou bò dwat; rete dèyè san danje jiskaske w konnen sa chofè a pral fè.","Les gros véhicules tournent large et peuvent se déporter à gauche avant de tourner à droite. Ne dépassez pas par la droite ; restez derrière jusqu'à comprendre.","Los vehículos grandes giran abierto y pueden moverse a la izquierda antes de girar a la derecha. No rebase por la derecha; quédese atrás hasta saber qué hará.")),
  ("pm319",0,5,("slow-moving vehicle","veyikil ki mache dousman","véhicule lent","vehículo lento"),
   ("You come up behind a farm tractor with this orange triangle on the back. What should you do?","Ou rive dèyè yon traktè fèm ki gen triyang zoranj sa a dèyè l. Kisa ou dwe fè?","Vous arrivez derrière un tracteur agricole portant ce triangle orange. Que faire ?","Llega detrás de un tractor agrícola con este triángulo naranja atrás. ¿Qué debe hacer?"),
   ("Slow down, use caution and leave plenty of space if you pass","Ralanti, fè atansyon, epi kite anpil espas si w depase","Ralentir, être prudent et laisser beaucoup d'espace pour dépasser","Bajar la velocidad, tener cuidado y dejar mucho espacio si rebasa"),
   ("Pass it right away on the shoulder to save time","Pase l touswit sou bòdi a pou w pa pèdi tan","Le dépasser tout de suite par l'accotement pour gagner du temps","Rebasarlo enseguida por el acotamiento para ganar tiempo"),
   ("Honk until it pulls over","Klaksonnen jiskaske l rale sou kote","Klaxonner jusqu'à ce qu'il se range","Tocar el claxon hasta que se haga a un lado"),
   ("Follow it closely so other drivers cannot cut in","Swiv li kole pou lòt chofè pa ka antre devan w","Le suivre de près pour que les autres ne se glissent pas devant vous","Seguirlo de cerca para que otros no se metan delante"),
   ("An orange triangle marks a slow-moving vehicle such as farm equipment or a construction rig. Slow down, treat it like a bicyclist, and leave plenty of room if you pass.","Yon triyang zoranj make yon veyikil ki mache dousman tankou yon machin fèm oswa konstriksyon. Ralanti, trete l tankou yon siklis, epi kite anpil espas si w depase.","Un triangle orange signale un véhicule lent, comme un engin agricole ou de chantier. Ralentissez, traitez-le comme un cycliste et laissez beaucoup d'espace pour dépasser.","Un triángulo naranja marca un vehículo lento, como maquinaria agrícola o de obra. Baje la velocidad, trátelo como a un ciclista y deje mucho espacio si rebasa."),"smv"),
  ("pm320",1,5,("funeral procession","kòtèj fineray","cortège funèbre","cortejo fúnebre"),
   ("A funeral procession is going through a red light at an intersection while your light is green. What should you do?","Yon kòtèj fineray ap pase nan yon limyè wouj nan yon kafou pandan limyè pa w la vèt. Kisa ou dwe fè?","Un cortège funèbre traverse au feu rouge alors que votre feu est vert. Que faire ?","Un cortejo fúnebre cruza con luz roja mientras su luz está en verde. ¿Qué debe hacer?"),
   ("Go, since your light is green and you have the right-of-way","Ale, paske limyè w vèt e se ou ki gen priyorite","Passer, puisque votre feu est vert et que vous avez la priorité","Avanzar, ya que su luz está en verde y usted tiene el derecho de paso"),
   ("Wait; do not cross its path or drive between its vehicles","Tann; pa travèse chemen l ni pase ant machin li yo","Attendre ; ne pas couper le cortège ni passer entre ses véhicules","Esperar; no cruce su camino ni pase entre sus vehículos"),
   ("Join the end of the procession to get through the light","Antre nan ke konvwa a pou w pase limyè a","Se mettre au bout du cortège pour passer le feu","Unirse al final del cortejo para pasar el semáforo"),
   ("Honk to warn them","Klaksonnen pou avèti yo","Klaxonner pour les avertir","Tocar el claxon para avisarles"),
   ("Funeral processions have the right-of-way at intersections. You may not cross their path even on a green light, drive between their vehicles, or join the procession.","Kòtèj fineray gen dwa de pasaj nan kafou yo. Ou pa ka travèse chemen yo menm ak limyè vèt, pase ant machin yo, ni antre nan kòtèj la.","Les cortèges funèbres ont la priorité aux intersections. Vous ne pouvez pas couper leur trajet même au vert, passer entre leurs véhicules ni vous y joindre.","Los cortejos fúnebres tienen el derecho de paso en las intersecciones. No puede cruzar su camino aun con verde, pasar entre sus vehículos ni unirse al cortejo.")),
  ("pm321",2,5,("horse","cheval","cheval","caballo"),
   ("You are about to pass a person riding a horse, and the horse looks scared. What must you do?","Ou pral depase yon moun ki monte cheval, epi cheval la sanble l pè. Kisa ou dwe fè?","Vous allez dépasser un cavalier et le cheval semble effrayé. Que devez-vous faire ?","Va a rebasar a una persona a caballo y el caballo parece asustado. ¿Qué debe hacer?"),
   ("Honk so the rider knows you are there","Klaksonnen pou moun nan konnen ou la","Klaxonner pour signaler votre présence","Tocar el claxon para que el jinete sepa que está ahí"),
   ("Pass quickly to get it over with","Depase vit pou sa fini","Dépasser vite pour en finir","Rebasar rápido para terminar pronto"),
   ("Pull to the side and stop","Rale sou kote epi kanpe","Se ranger et s'arrêter","Hacerse a un lado y parar"),
   ("Flash your headlights","Fè limyè w kliyote","Faire un appel de phares","Hacer cambio de luces"),
   ("Give the right-of-way to animals being ridden or led. Slow down and do not honk. If the animal looks scared, you must pull to the side and stop, and you must stop if the rider signals you to.","Bay bèt yon moun ap monte oswa mennen dwa de pasaj. Ralanti epi pa klaksonnen. Si bèt la sanble l pè, ou dwe rale sou kote epi kanpe, epi ou dwe kanpe si moun ki sou li a fè w siy.","Cédez aux animaux montés ou menés. Ralentissez et ne klaxonnez pas. Si l'animal semble effrayé, rangez-vous et arrêtez-vous, et arrêtez-vous si le cavalier vous le demande.","Ceda el paso a los animales montados o guiados. Baje la velocidad y no toque el claxon. Si el animal parece asustado, hágase a un lado y pare, y pare si el jinete se lo indica.")),
  ("pm322",0,5,("aggressive driver","chofè agresif","conducteur agressif","conductor agresivo"),
   ("An aggressive driver is tailgating you and making rude gestures. What should you do?","Yon chofè agresif ap kole dèyè w epi l ap fè jès malelve. Kisa ou dwe fè?","Un conducteur agressif vous colle et fait des gestes grossiers. Que faire ?","Un conductor agresivo se le pega y hace gestos groseros. ¿Qué debe hacer?"),
   ("Get out of the way, avoid eye contact and ignore the gestures","Retire kò w nan chemen l, evite gade l nan je, epi pa okipe jès li yo","S'écarter, éviter son regard et ignorer les gestes","Apartarse, evitar mirarlo y no hacer caso a los gestos"),
   ("Brake suddenly to teach them a lesson","Frennen sou kou pou ba l yon leson","Freiner brusquement pour lui donner une leçon","Frenar de golpe para darle una lección"),
   ("Speed up so they cannot keep up with you","Akselere pou l pa ka swiv ou","Accélérer pour qu'il ne puisse pas vous suivre","Acelerar para que no pueda seguirlo"),
   ("Make a gesture back so they know you saw them","Fè yon jès tou pou l konnen w wè l","Lui répondre par un geste pour qu'il sache que vous l'avez vu","Responder con un gesto para que sepa que lo vio"),
   ("Try to get out of an aggressive driver's way. Do not challenge them, avoid eye contact, ignore rude gestures and keep your seat belt on. Call 911 to report an emergency.","Eseye retire kò w nan chemen yon chofè agresif. Pa defye l, evite gade l nan je, pa okipe jès malelve yo, epi kenbe senti w mare. Rele 911 pou rapòte yon ijans.","Écartez-vous d'un conducteur agressif. Ne le provoquez pas, évitez son regard, ignorez les gestes et gardez votre ceinture. Appelez le 911 en cas d'urgence.","Apártese de un conductor agresivo. No lo desafíe, evite mirarlo, ignore los gestos y mantenga el cinturón. Llame al 911 para reportar una emergencia."))]))

# ---------------------------------------------------------------- P8
CH.append(dict(ch=8,
 title=("Emergencies, police stops and crashes","Ijans, lè lapolis kanpe w, ak aksidan","Urgences, contrôles de police et accidents","Emergencias, paradas de la policía y choques"),
 bp=("Manual chapter 5, pages 119–131. On the RMV test: rules of the road.","Chapit 5 nan mànyèl la, paj 119–131. Nan egzamen RMV a: règ wout yo.","Chapitre 5 du manuel, pages 119–131. À l'examen du RMV : règles de la route.","Capítulo 5 del manual, páginas 119–131. En el examen del RMV: reglas del camino."),
 sections=[
  dict(h=("Emergency vehicles","Veyikil ijans","Véhicules d'urgence","Vehículos de emergencia"), pg="120–121", b=[
   ("li",("When an emergency vehicle uses its siren or lights, from any direction, pull as close as you can to the right side of the road and stop until it passes. Slowly rolling is not enough. Never stop in an intersection: drive through, then pull over.","Lè yon veyikil ijans sèvi ak siren oswa limyè l, kèlkeswa direksyon l ap vini, rale toutotan ou kapab sou bò dwat wout la epi kanpe jiskaske l pase. Woule dousman pa ase. Pa janm kanpe nan mitan yon kafou: travèse l, apre sa rale sou kote.","Quand un véhicule d'urgence utilise sa sirène ou ses feux, quelle que soit sa direction, rangez-vous le plus possible à droite et arrêtez-vous jusqu'à son passage. Rouler lentement ne suffit pas. Ne vous arrêtez jamais dans une intersection : traversez-la, puis rangez-vous.","Cuando un vehículo de emergencia usa sirena o luces, venga de donde venga, hágase lo más posible a la derecha y pare hasta que pase. Avanzar despacio no basta. Nunca pare dentro de una intersección: crúcela y luego hágase a un lado.")),
   ("li",("After it passes, signal left and merge back when the lane is clear. Do not follow closer than 300 feet behind an emergency vehicle answering an alarm, and do not drive or park within 800 feet of a fire.","Apre l fin pase, mete siyal agoch epi retounen nan sikilasyon an lè vwa a klè. Pa swiv pi pre pase 300 pye dèyè yon veyikil ijans k ap reponn yon alam, epi pa kondui ni pake nan 800 pye yon dife.","Après son passage, signalez à gauche et reprenez la circulation quand la voie est libre. Ne suivez pas à moins de 300 pieds un véhicule d'urgence qui répond à une alerte, et ne circulez ni ne stationnez à moins de 800 pieds d'un incendie.","Cuando pase, señale a la izquierda y regrese cuando el carril esté libre. No siga a menos de 300 pies a un vehículo de emergencia que atiende una alarma, y no maneje ni se estacione a menos de 800 pies de un incendio."))]),
  dict(h=("If police stop you","Si lapolis kanpe w","Si la police vous arrête","Si la policía lo detiene"), pg="121–123", b=[
   ("li",("Signal, check mirrors and pull completely to the right, not into an intersection or in front of a driveway. Put the car in park, turn off the engine and radio, and at night turn on the interior light.","Mete siyal, gade miwa yo epi rale nèt sou bò dwat, pa nan yon kafou ni devan yon antre kay. Mete machin nan nan pak, etenn motè ak radyo a, epi lannwit limen limyè anndan an.","Signalez, regardez les rétroviseurs et rangez-vous complètement à droite, pas dans une intersection ni devant une entrée. Mettez en position stationnement, coupez moteur et radio, et la nuit allumez le plafonnier.","Señale, revise espejos y hágase completamente a la derecha, no en una intersección ni frente a una entrada. Ponga el auto en park, apague motor y radio y, de noche, encienda la luz interior.")),
   ("li",("Stay in the car with your hands in plain sight. Reach for your license and registration only when asked. Failing to produce them is a $35 fine for a first offense.","Rete nan machin nan ak men w kote yo ka wè yo. Chèche lisans ak anrejistreman w sèlman lè yo mande w. Si w pa ka montre yo, se $35 amann premye fwa.","Restez dans la voiture, les mains bien visibles. Ne cherchez permis et immatriculation que lorsqu'on vous les demande. Ne pas les présenter coûte 35 $ la première fois.","Quédese en el auto con las manos a la vista. Busque licencia y registro solo cuando se los pidan. No presentarlos es una multa de $35 la primera vez.")),
   ("li",("If you get a ticket, do not argue: you can challenge it in court. Massachusetts does not require you to sign a citation.","Si yo ba w yon kontravansyon, pa diskite: ou ka konteste l nan tribinal. Massachusetts pa mande w siyen yon kontravansyon.","Si vous recevez une contravention, ne discutez pas : vous pouvez la contester devant le tribunal. Le Massachusetts n'exige pas de signer la contravention.","Si recibe una multa, no discuta: puede impugnarla en el tribunal. Massachusetts no exige firmar la multa."))]),
  dict(h=("Driving emergencies","Ijans pandan w ap kondui","Urgences de conduite","Emergencias al manejar"), pg="123–125", b=[
   ("li",("Skid: ease off the gas, do not brake, and steer in the direction the rear of the car is sliding. Running off the pavement: hold the wheel firmly, ease off the gas, brake gently, then steer gently back.","Derapaj: lage gaz la dousman, pa fren, epi vire volan an nan direksyon dèyè machin nan ap glise. Si w soti sou asfalt la: kenbe volan an fèm, lage gaz la, fren dousman, apre sa dirije tou dousman retounen sou wout la.","Dérapage : levez le pied, ne freinez pas et braquez dans le sens où glisse l'arrière. Sortie de chaussée : tenez fermement le volant, levez le pied, freinez doucement, puis revenez doucement sur la route.","Derrape: suelte el acelerador, no frene y gire hacia donde se desliza la parte trasera. Si se sale del pavimento: sujete firme el volante, suelte el acelerador, frene suave y regrese con suavidad.")),
   ("li",("Blowout: grip the wheel, ease off the gas and brake gently once you have control. Brake failure without antilock brakes: pump the pedal quickly; with antilock brakes, downshift and apply the parking brake gently. Stuck gas pedal: shift to neutral and brake.","Kawoutchou pete: kenbe volan an fèm, lage gaz la epi fren dousman lè w fin kontwole machin nan. Fren ki pa mache san ABS: ponpe pedal la vit; ak ABS, desann vitès epi mete fren pakin nan dousman. Pedal gaz ki kole: mete machin nan nan net epi fren.","Éclatement : tenez le volant, levez le pied et freinez doucement une fois le contrôle repris. Freins défaillants sans ABS : pompez vite la pédale ; avec ABS, rétrogradez et serrez doucement le frein de stationnement. Accélérateur coincé : point mort et freinage.","Llanta reventada: sujete el volante, suelte el acelerador y frene suave cuando tenga control. Falla de frenos sin ABS: bombee el pedal rápido; con ABS, baje de cambio y ponga suave el freno de estacionamiento. Acelerador atorado: neutral y frene.")),
   ("li",("A car coming head-on in your lane: slow down, pull right and sound your horn. Headlights fail: turn on parking lights or flashers and pull off the road.","Yon machin k ap vin fas a fas nan vwa w: ralanti, rale adwat epi klaksonnen. Limyè devan yo etenn: limen ti limyè yo oswa limyè ijans epi soti sou wout la.","Un véhicule arrive de face dans votre voie : ralentissez, serrez à droite et klaxonnez. Phares en panne : allumez veilleuses ou feux de détresse et quittez la route.","Un auto de frente en su carril: baje la velocidad, hágase a la derecha y toque el claxon. Si fallan las luces: encienda las de estacionamiento o intermitentes y salga del camino.")),
   ("li",("Stalled on railroad tracks with a train coming: get everyone out immediately and run away from the tracks at a 45-degree angle toward the direction the train is coming from, then call 911.","Machin nan kanpe sou ray tren epi gen yon tren k ap vini: fè tout moun desann touswit epi kouri lwen ray yo nan yon ang 45 degre nan direksyon tren an ap soti a, apre sa rele 911.","Calé sur une voie ferrée avec un train qui arrive : faites sortir tout le monde immédiatement et courez en vous éloignant des rails à 45 degrés vers la direction d'où vient le train, puis appelez le 911.","Detenido en las vías con un tren acercándose: saque a todos de inmediato y corran alejándose de las vías en un ángulo de 45 grados hacia el lado de donde viene el tren; luego llame al 911."))]),
  dict(h=("Breakdowns, fire and water","Pàn, dife ak dlo","Pannes, incendie et eau","Averías, incendio y agua"), pg="125–128", b=[
   ("li",("On a highway, stop as far from traffic as you can and stay in the vehicle with hazard lights on. Warning triangles: on a divided highway, 10 and 100 feet behind; on a two-way road, also 100 feet in front.","Sou otowout, kanpe toutotan ou kapab lwen machin yo epi rete nan veyikil la ak limyè ijans limen. Triyang avètisman: sou yon otowout divize, 10 ak 100 pye dèyè; sou yon wout de sans, 100 pye devan tou.","Sur l'autoroute, arrêtez-vous le plus loin possible de la circulation et restez dans le véhicule, feux de détresse allumés. Triangles : sur une route divisée, à 10 et 100 pieds derrière ; sur une route à double sens, aussi à 100 pieds devant.","En autopista, pare lo más lejos posible del tráfico y quédese en el vehículo con las intermitentes. Triángulos: en carretera dividida, a 10 y 100 pies detrás; en camino de doble sentido, también a 100 pies adelante.")),
   ("li",("Smoke from under the hood: pull off, turn off the ignition, move away and call the fire department.","Lafimen ki soti anba kapo a: rale sou kote, etenn kontak la, deplase lwen machin nan epi rele ponpye.","Fumée sous le capot : rangez-vous, coupez le contact, éloignez-vous et appelez les pompiers.","Humo bajo el cofre: hágase a un lado, apague el encendido, aléjese y llame a los bomberos.")),
   ("li",("If your car goes into water, unfasten your belt and escape through a window. Do not open a door. If it sinks first, move to the back seat where air may be trapped, then escape through a window.","Si machin ou tonbe nan dlo, demare senti w epi soti pa yon fenèt. Pa louvri yon pòt. Si l desann anba dlo anvan, ale nan chèz dèyè a kote ka gen lè, apre sa soti pa yon fenèt.","Si la voiture tombe à l'eau, détachez la ceinture et sortez par une fenêtre. N'ouvrez pas de portière. Si elle coule d'abord, allez à l'arrière où de l'air peut rester, puis sortez par une fenêtre.","Si el auto cae al agua, quítese el cinturón y salga por una ventana. No abra una puerta. Si se hunde antes, vaya al asiento trasero donde puede quedar aire y luego salga por una ventana."))]),
  dict(h=("Crashes","Aksidan","Accidents","Choques"), pg="128–131", b=[
   ("li",("After any crash you must stop. Leaving the scene without identifying yourself is a crime (hit and run).","Apre nenpòt aksidan ou dwe kanpe. Kite sèn nan san w pa idantifye tèt ou se yon krim (frape epi kouri).","Après tout accident, vous devez vous arrêter. Partir sans vous identifier est un délit (délit de fuite).","Después de cualquier choque debe parar. Irse sin identificarse es un delito (huir del lugar).")),
   ("li",("If no one is hurt, move the vehicles out of travel lanes (the Driver Removal Law). Exchange names, addresses, license numbers, registration and insurance.","Si pa gen moun ki blese, retire machin yo nan vwa sikilasyon yo (Lwa sou Retire Machin). Bay youn lòt non, adrès, nimewo lisans, anrejistreman ak asirans.","S'il n'y a pas de blessé, déplacez les véhicules hors des voies (loi sur le dégagement des véhicules). Échangez noms, adresses, numéros de permis, immatriculation et assurance.","Si no hay heridos, saque los vehículos de los carriles (Ley de Retiro de Vehículos). Intercambien nombres, direcciones, números de licencia, registro y seguro.")),
   ("li",("Within five days, file a crash report with the RMV and the local police if anyone was hurt or killed, or damage is $1,000 or more. Telling your insurer is not enough.","Nan senk jou, ranpli yon rapò aksidan pou RMV ak lapolis lokal si yon moun blese oswa mouri, oswa si domaj yo $1,000 oswa plis. Di konpayi asirans ou sèlman pa ase.","Dans les cinq jours, déposez un rapport d'accident auprès du RMV et de la police locale s'il y a eu blessé ou décès, ou 1 000 $ de dégâts ou plus. Prévenir l'assureur ne suffit pas.","En cinco días, presente un informe de choque al RMV y a la policía local si hubo heridos o muertos, o daños de $1,000 o más. Avisar al seguro no basta.")),
   ("li",("Do not move an injured person unless necessary; press directly on bleeding. If wires fall on a car, the people inside should stay inside until help arrives. As a witness, do not slow down to look.","Pa deplase yon moun ki blese sof si sa nesesè; peze dirèkteman sou kote k ap senyen an. Si fil kouran tonbe sou yon machin, moun ki andedan yo dwe rete andedan jiskaske èd rive. Si w se temwen, pa ralanti pou w gade.","Ne déplacez pas un blessé sauf nécessité ; appuyez directement sur un saignement. Si des fils tombent sur une voiture, les occupants restent dedans jusqu'à l'arrivée des secours. Témoin, ne ralentissez pas pour regarder.","No mueva a un herido salvo que sea necesario; presione directo sobre el sangrado. Si caen cables sobre un auto, quienes están dentro deben quedarse hasta que llegue ayuda. Como testigo, no frene para mirar."))])],
 terms=[("emergency vehicle","veyikil ijans","véhicule d'urgence","vehículo de emergencia"),("skid","derapaj","dérapage","derrape"),("blowout","kawoutchou pete","éclatement","reventón"),
        ("hit and run","frape epi kouri","délit de fuite","choque y fuga"),("crash report","rapò aksidan","rapport d'accident","informe de choque"),("warning triangle","triyang avètisman","triangle de signalisation","triángulo de advertencia")],
 qs=[
  ("p13",0,0,("emergency vehicle","veyikil ijans","véhicule d'urgence","vehículo de emergencia"),
   ("An ambulance with flashing lights and a siren comes up behind you. What do you do?","Yon anbilans ak limyè k ap limen etèn ak siren ap vini dèyè w. Kisa ou fè?","Une ambulance avec feux et sirène arrive derrière vous. Que faites-vous ?","Una ambulancia con luces y sirena viene detrás de usted. ¿Qué hace?"),
   ("Pull to the right and stop","Rale sou bò dwat epi kanpe","Se ranger à droite et s'arrêter","Hacerse a la derecha y parar"),
   ("Speed up to get out of its way","Akselere pou soti devan l","Accélérer pour lui laisser la place","Acelerar para quitarse"),
   ("Stop where you are in your lane","Kanpe kote w ye a nan vwa w","S'arrêter sur place dans sa voie","Parar donde está en su carril"),
   ("Keep driving at the same speed","Kontinye kondui menm vitès la","Continuer à la même vitesse","Seguir a la misma velocidad"),
   ("Pull as close as you can to the right side and stop until it passes. Slowly rolling is not acceptable. Never stop in an intersection: drive through, then pull over.","Rale toutotan ou kapab sou bò dwat epi kanpe jiskaske l pase. Woule dousman pa aksepte. Pa janm kanpe nan mitan yon kafou: travèse l, apre sa rale sou kote.","Rangez-vous le plus à droite possible et arrêtez-vous jusqu'à son passage. Rouler lentement n'est pas acceptable. Jamais d'arrêt dans une intersection : traversez, puis rangez-vous.","Hágase lo más a la derecha posible y pare hasta que pase. Avanzar despacio no se acepta. Nunca pare en una intersección: crúcela y luego hágase a un lado.")),
  ("pm801",2,0,("following distance","distans dèyè","distance de sécurité","distancia de seguimiento"),
   ("How close may you follow a fire truck answering an alarm?","A ki distans ou ka swiv yon kamyon ponpye k ap reponn yon alam?","À quelle distance pouvez-vous suivre un camion de pompiers qui répond à une alerte ?","¿A qué distancia puede seguir a un camión de bomberos que atiende una alarma?"),
   ("100 feet","100 pye","100 pieds","100 pies"),("Any distance, if your lights are on","Nenpòt distans, si limyè w limen","N'importe quelle distance, phares allumés","Cualquier distancia, con las luces encendidas"),("No closer than 300 feet","Pa pi pre pase 300 pye","Pas à moins de 300 pieds","No a menos de 300 pies"),("50 feet","50 pye","50 pieds","50 pies"),
   ("It is illegal to follow closer than 300 feet behind an emergency vehicle responding to an alarm. Also stay at least 800 feet from a fire.","Li ilegal pou w swiv pi pre pase 300 pye dèyè yon veyikil ijans k ap reponn yon alam. Rete omwen 800 pye lwen yon dife tou.","Il est illégal de suivre à moins de 300 pieds un véhicule d'urgence qui répond à une alerte. Restez aussi à au moins 800 pieds d'un incendie.","Es ilegal seguir a menos de 300 pies a un vehículo de emergencia que atiende una alarma. Manténgase también a 800 pies de un incendio.")),
  ("pm802",1,0,("intersection","kafou","intersection","intersección"),
   ("You are in the middle of an intersection when you hear a siren behind you. What should you do?","Ou nan mitan yon kafou lè w tande yon siren dèyè w. Kisa ou dwe fè?","Vous êtes au milieu d'une intersection quand vous entendez une sirène derrière vous. Que faire ?","Está en medio de una intersección cuando oye una sirena detrás. ¿Qué debe hacer?"),
   ("Stop right where you are","Kanpe kote w ye a","S'arrêter là où vous êtes","Detenerse donde está"),
   ("Drive through the intersection, then pull to the right and stop","Travèse kafou a, apre sa rale sou bò dwat epi kanpe","Traverser l'intersection, puis se ranger à droite et s'arrêter","Cruzar la intersección y luego hacerse a la derecha y parar"),
   ("Back up out of the intersection to clear the way","Fè bak pou sòti nan kafou a pou libere wout la","Reculer pour sortir du carrefour et libérer le passage","Retroceder para salir del cruce y dejar el paso libre"),
   ("Pull to the left","Rale sou bò goch","Se ranger à gauche","Hacerse a la izquierda"),
   ("Never stop in the middle of an intersection. Drive through it, then pull over to the right as soon as it is safe. Do not pull left or slam on the brakes.","Pa janm kanpe nan mitan yon kafou. Travèse l, apre sa rale sou bò dwat depi l san danje. Pa rale agoch ni fren sanzatann.","Ne vous arrêtez jamais au milieu d'une intersection. Traversez-la, puis rangez-vous à droite dès que c'est sûr. Pas à gauche, et pas de freinage brusque.","Nunca pare en medio de una intersección. Crúcela y hágase a la derecha en cuanto sea seguro. No se mueva a la izquierda ni frene de golpe.")),
  ("pm803",3,1,("traffic stop","lè lapolis kanpe w","contrôle routier","parada de tránsito"),
   ("A police officer has pulled you over and is walking to your car. What should you do?","Yon polisye fè w rale sou kote epi l ap mache vin bò machin ou. Kisa ou dwe fè?","Un policier vous a fait arrêter et s'approche de votre voiture. Que faire ?","Un policía lo detuvo y camina hacia su auto. ¿Qué debe hacer?"),
   ("Get out and walk to the police car","Desann epi mache al jwenn machin lapolis la","Sortir et aller vers la voiture de police","Bajarse y caminar hacia la patrulla"),
   ("Reach under the seat for your papers","Chèche papye w yo anba chèz la","Chercher vos papiers sous le siège","Buscar sus papeles bajo el asiento"),
   ("Call someone on your phone","Rele yon moun nan telefòn ou","Appeler quelqu'un avec votre téléphone","Llamar a alguien por teléfono"),
   ("Stay in the car with your hands in plain sight","Rete nan machin nan ak men w kote yo ka wè yo","Rester dans la voiture, mains bien visibles","Quedarse en el auto con las manos a la vista"),
   ("Stay in the vehicle, keep your hands visible, turn off the engine, and wait until the officer asks before reaching for your license and registration. Do not use your phone.","Rete nan veyikil la, kenbe men w vizib, etenn motè a, epi tann polisye a mande anvan w chèche lisans ak anrejistreman w. Pa sèvi ak telefòn ou.","Restez dans le véhicule, mains visibles, moteur coupé, et attendez la demande du policier avant de chercher permis et immatriculation. N'utilisez pas votre téléphone.","Quédese en el vehículo, manos visibles, motor apagado, y espere a que le pidan la licencia y el registro antes de buscarlos. No use el teléfono.")),
  ("pm804",0,2,("skid","derapaj","dérapage","derrape"),
   ("Your car starts to skid on a slippery road. What should your feet do first?","Machin ou kòmanse derape sou yon wout ki glise. Kisa pye w dwe fè an premye?","Votre voiture commence à déraper sur une route glissante. Que doivent faire vos pieds d'abord ?","Su auto empieza a derrapar en un camino resbaloso. ¿Qué deben hacer primero sus pies?"),
   ("Ease off the gas and do not brake","Lage gaz la dousman epi pa fren","Lever doucement le pied de l'accélérateur sans freiner","Soltar el acelerador sin frenar"),
   ("Brake hard","Fren fò","Freiner fort","Frenar fuerte"),
   ("Press the gas to regain grip","Peze gaz la pou machin nan kenbe wout la","Accélérer pour retrouver l'adhérence","Acelerar para recuperar agarre"),
   ("Keep both feet on the floor","Kenbe tou de pye w atè","Garder les deux pieds au plancher","Dejar los dos pies en el piso"),
   ("In a skid, ease off the gas and do not use the brakes, then steer in the direction the rear of the car is sliding. You may need to steer back and forth a few times.","Lè w ap derape, lage gaz la dousman epi pa sèvi ak fren, apre sa vire nan direksyon dèyè machin nan ap glise a. Ou ka bezwen vire de bò kèk fwa.","En dérapage, levez le pied sans freiner, puis braquez dans le sens où glisse l'arrière. Il faudra peut-être corriger plusieurs fois.","En un derrape, suelte el acelerador sin frenar y gire hacia donde se desliza la parte trasera. Quizá deba corregir varias veces.")),
  ("pm805",3,2,("shoulder","bò wout","accotement","acotamiento"),
   ("Your right wheels drift off the pavement onto the shoulder. What should you do?","Wou dwat ou yo soti sou asfalt la epi tonbe sou bò wout la. Kisa ou dwe fè?","Vos roues droites quittent la chaussée pour l'accotement. Que faire ?","Sus ruedas derechas se salen del pavimento al acotamiento. ¿Qué debe hacer?"),
   ("Jerk the wheel back to the left right away to get back on","Vire volan an sou kou agoch touswit pou w remonte","Donner tout de suite un coup de volant à gauche pour remonter","Girar de golpe el volante a la izquierda enseguida para volver"),
   ("Brake hard","Fren fò","Freiner fort","Frenar fuerte"),
   ("Speed up so the tires can climb back onto the pavement","Akselere pou kawotchou yo ka remonte sou asfalt la","Accélérer pour que les pneus remontent sur la chaussée","Acelerar para que las llantas suban de nuevo al pavimento"),
   ("Hold the wheel firmly, ease off the gas, brake gently, then steer gently back","Kenbe volan an fèm, lage gaz la, fren dousman, apre sa dirije tou dousman retounen","Tenir fermement le volant, lever le pied, freiner doucement, puis revenir doucement","Sujetar firme el volante, soltar el acelerador, frenar suave y regresar con suavidad"),
   ("Hold the steering wheel tightly, slowly take your foot off the gas, brake gently to reduce speed, check traffic behind you, then steer gently back onto the road.","Kenbe volan an fèm, retire pye w sou gaz la dousman, fren dousman pou ralanti, gade machin ki dèyè w, apre sa dirije tou dousman retounen sou wout la.","Tenez fermement le volant, levez doucement le pied, freinez légèrement, vérifiez derrière, puis revenez doucement sur la route.","Sujete firme el volante, suelte poco a poco el acelerador, frene suave, revise atrás y regrese con suavidad al camino.")),
  ("pm806",2,2,("brake failure","fren ki pa mache","freins défaillants","falla de frenos"),
   ("Your car does NOT have antilock brakes, and the brakes suddenly do not respond. What should you try first?","Machin ou PA gen fren antiblokaj, epi fren yo pa reponn toudenkou. Kisa ou dwe eseye an premye?","Votre voiture n'a PAS de freins antiblocage et les freins ne répondent plus. Que faut-il essayer d'abord ?","Su auto NO tiene frenos antibloqueo y de pronto los frenos no responden. ¿Qué debe intentar primero?"),
   ("Turn off the engine","Etenn motè a","Couper le moteur","Apagar el motor"),
   ("Shift into park","Mete l nan pak","Passer en position stationnement","Poner en park"),
   ("Pump the brake pedal several times quickly","Ponpe pedal fren an plizyè fwa vit","Pomper rapidement la pédale de frein plusieurs fois","Bombear el pedal varias veces rápido"),
   ("Open the door and drag your foot","Louvri pòt la epi trennen pye w","Ouvrir la portière et freiner avec le pied","Abrir la puerta y arrastrar el pie"),
   ("Without antilock brakes, pump the pedal quickly to build pressure. Never pump antilock brakes. If that fails, downshift and apply the parking brake gently, and use horn and lights to warn others.","San fren antiblokaj, ponpe pedal la vit pou fè presyon. Pa janm ponpe fren antiblokaj. Si sa pa mache, desann vitès epi mete fren pakin nan dousman, epi sèvi ak klaksòn ak limyè pou avèti lòt moun.","Sans ABS, pompez vite pour rétablir la pression. Ne pompez jamais un ABS. Si ça échoue, rétrogradez, serrez doucement le frein de stationnement, et utilisez klaxon et phares pour avertir.","Sin ABS, bombee rápido para crear presión. Nunca bombee frenos ABS. Si no funciona, baje de cambio, ponga suave el freno de estacionamiento y use claxon y luces para avisar.")),
  ("pm807",0,2,("stuck gas pedal","pedal gaz ki kole","accélérateur coincé","acelerador atorado"),
   ("Your gas pedal sticks down. What should you do first?","Pedal gaz ou kole anba. Kisa ou dwe fè an premye?","Votre accélérateur reste enfoncé. Que faire en premier ?","Su acelerador se atoró abajo. ¿Qué debe hacer primero?"),
   ("Shift into neutral and press the brake","Mete machin nan nan net epi peze fren an","Passer au point mort et freiner","Poner neutral y pisar el freno"),
   ("Turn the key all the way off while moving","Etenn kle a nèt pandan machin nan ap mache","Couper complètement le contact en roulant","Apagar del todo la llave en marcha"),
   ("Pump the gas pedal","Ponpe pedal gaz la","Pomper l'accélérateur","Bombear el acelerador"),
   ("Reach down with your hand to free it","Bese pou w libere l ak men w","Se pencher pour le libérer à la main","Agacharse a liberarlo con la mano"),
   ("Put the car in neutral and brake to slow down. Try to free the pedal with your foot, keep your eyes on the road, and pull off and stop when it is safe.","Mete machin nan nan net epi fren pou ralanti. Eseye libere pedal la ak pye w, kenbe je w sou wout la, epi soti sou kote epi kanpe lè l san danje.","Passez au point mort et freinez. Essayez de libérer la pédale avec le pied, gardez les yeux sur la route, et rangez-vous quand c'est sûr.","Ponga neutral y frene. Intente liberar el pedal con el pie, mire el camino y salga y pare cuando sea seguro.")),
  ("pm808",1,2,("head-on","fas a fas","de face","de frente"),
   ("A car is coming straight at you in your lane. What should you do?","Yon machin ap vin dirèkteman sou ou nan vwa w. Kisa ou dwe fè?","Une voiture vient droit sur vous dans votre voie. Que faire ?","Un auto viene directo hacia usted en su carril. ¿Qué debe hacer?"),
   ("Swerve into the left lane","Vire sou kou nan liy goch la","Faire un écart dans la voie de gauche","Desviarse al carril izquierdo"),
   ("Slow down, pull to the right and sound your horn","Ralanti, rale adwat epi klaksonnen","Ralentir, serrer à droite et klaxonner","Bajar la velocidad, hacerse a la derecha y tocar el claxon"),
   ("Speed up to get past the car before it reaches you","Akselere pou w pase machin nan anvan l rive sou ou","Accélérer pour passer avant que la voiture vous atteigne","Acelerar para pasar antes de que el auto llegue a usted"),
   ("Stop in your lane and wait","Kanpe nan liy ou epi tann","S'arrêter dans votre voie et attendre","Detenerse en su carril y esperar"),
   ("If a vehicle comes toward you head on in your lane, slow down, pull to the right, and sound your horn to alert the other driver.","Si yon veyikil ap vin fas a fas sou ou nan vwa w, ralanti, rale adwat, epi klaksonnen pou avèti lòt chofè a.","Si un véhicule arrive de face dans votre voie, ralentissez, serrez à droite et klaxonnez pour avertir l'autre conducteur.","Si un vehículo viene de frente en su carril, baje la velocidad, hágase a la derecha y toque el claxon para avisar al otro conductor.")),
  ("pm809",3,2,("railroad tracks","ray tren","voie ferrée","vías del tren"),
   ("Your car stalls on railroad tracks and a train is coming. What do you do?","Machin ou kanpe sou ray tren epi gen yon tren k ap vini. Kisa ou fè?","Votre voiture cale sur une voie ferrée et un train arrive. Que faites-vous ?","Su auto se detiene en las vías y viene un tren. ¿Qué hace?"),
   ("Keep trying to start the engine until the train is very close","Kontinye eseye estat motè a jiskaske tren an tou pre","Continuer d'essayer de démarrer jusqu'à ce que le train soit tout proche","Seguir intentando arrancar el motor hasta que el tren esté muy cerca"),
   ("Stay in the car with everyone's seat belts fastened","Rete nan machin nan ak senti tout moun tache","Rester dans la voiture, tout le monde avec la ceinture attachée","Quedarse en el auto con todos los cinturones abrochados"),
   ("Have everyone get out, then push the car off the tracks together","Fè tout moun desann, apre sa nou tout pouse machin nan sot sou ray yo","Faire sortir tout le monde, puis pousser ensemble la voiture hors des rails","Que todos bajen y luego empujen juntos el auto fuera de las vías"),
   ("Get everyone out and run from the tracks toward the train, at an angle","Fè tout moun desann epi kouri kite ray yo nan direksyon tren an, an dyagonal","Faire sortir tout le monde et s'éloigner des rails en biais, vers le train","Sacar a todos y alejarse de las vías en diagonal, hacia el tren"),
   ("Get everyone out immediately. Run away from the tracks at a 45-degree angle in the direction the train is coming from, to avoid flying wreckage, then call 911.","Fè tout moun desann touswit. Kouri lwen ray yo nan yon ang 45 degre nan direksyon tren an ap soti a, pou evite debri k ap vole, apre sa rele 911.","Faites sortir tout le monde immédiatement. Éloignez-vous des rails à 45 degrés vers la direction d'où vient le train, pour éviter les débris, puis appelez le 911.","Saque a todos de inmediato. Corran alejándose de las vías a 45 grados hacia el lado de donde viene el tren, para evitar los restos, y llamen al 911.")),
  ("pm810",2,3,("vehicle in water","machin nan dlo","véhicule dans l'eau","vehículo en el agua"),
   ("Your car goes into deep water. How should you get out?","Machin ou tonbe nan yon dlo fon. Kijan ou dwe soti?","Votre voiture tombe en eau profonde. Comment sortir ?","Su auto cae en agua profunda. ¿Cómo debe salir?"),
   ("Open the door right away","Louvri pòt la touswit","Ouvrir la portière tout de suite","Abrir la puerta de inmediato"),
   ("Wait for the car to fill with water","Tann machin nan plen dlo","Attendre que la voiture se remplisse","Esperar a que el auto se llene"),
   ("Unfasten your belt and escape through a window","Demare senti w epi soti pa yon fenèt","Détacher la ceinture et sortir par une fenêtre","Quitarse el cinturón y salir por una ventana"),
   ("Climb onto the roof through the sunroof only","Monte sou do machin nan pa twou do a sèlman","Monter sur le toit seulement par le toit ouvrant","Subirse al techo solo por el quemacocos"),
   ("Unfasten your seat belt and escape through a window; open power windows quickly before they stop working. Do not open a door: water rushes in and the car can flip.","Demare senti w epi soti pa yon fenèt; louvri fenèt elektrik yo vit anvan yo sispann mache. Pa louvri yon pòt: dlo ap antre fò epi machin nan ka vire.","Détachez la ceinture et sortez par une fenêtre ; ouvrez vite les vitres électriques avant qu'elles ne cessent de fonctionner. N'ouvrez pas de portière : l'eau entre et la voiture peut se retourner.","Quítese el cinturón y salga por una ventana; abra rápido las ventanas eléctricas antes de que dejen de funcionar. No abra una puerta: entra el agua y el auto puede voltearse.")),
  ("pm811",0,3,("warning triangle","triyang avètisman","triangle de signalisation","triángulo de advertencia"),
   ("You break down on a divided highway. Where do you place your warning triangles?","Machin ou tonbe an pàn sou yon otowout divize. Ki kote ou mete triyang avètisman yo?","Vous tombez en panne sur une route divisée. Où placer les triangles ?","Se descompone en una carretera dividida. ¿Dónde pone los triángulos?"),
   ("10 feet and 100 feet behind the vehicle","10 pye ak 100 pye dèyè veyikil la","À 10 et 100 pieds derrière le véhicule","A 10 y 100 pies detrás del vehículo"),
   ("Only in front of the vehicle","Sèlman devan veyikil la","Seulement devant le véhicule","Solo delante del vehículo"),
   ("On the hood","Sou kapo a","Sur le capot","Sobre el cofre"),
   ("500 feet ahead","500 pye devan","À 500 pieds devant","A 500 pies adelante"),
   ("On a divided highway, place triangles or flares 10 feet and 100 feet behind your vehicle. On a two-way or undivided road, add one 100 feet in front.","Sou yon otowout divize, mete triyang oswa limyè avètisman 10 pye ak 100 pye dèyè veyikil ou. Sou yon wout de sans oswa ki pa divize, ajoute youn 100 pye devan.","Sur une route divisée, placez triangles ou fusées à 10 et 100 pieds derrière. Sur une route à double sens ou non divisée, ajoutez-en un à 100 pieds devant.","En carretera dividida, ponga triángulos o bengalas a 10 y 100 pies detrás. En camino de doble sentido o no dividido, agregue uno a 100 pies adelante.")),
  ("pm812",1,4,("crash report","rapò aksidan","rapport d'accident","informe de choque"),
   ("You are in a crash that causes $1,500 of damage and no injuries. What must you file, and when?","Ou nan yon aksidan ki fè $1,500 domaj san blese. Kisa ou dwe ranpli, e kilè?","Vous avez un accident causant 1 500 $ de dégâts sans blessé. Que devez-vous déposer, et quand ?","Tiene un choque con $1,500 de daños y sin heridos. ¿Qué debe presentar y cuándo?"),
   ("Nothing, since no one was hurt","Anyen, paske pèsonn pa blese","Rien, puisque personne n'a été blessé","Nada, ya que nadie salió herido"),
   ("A crash report with the RMV and local police within five days","Yon rapò aksidan pou RMV ak lapolis lokal nan senk jou","Un rapport d'accident au RMV et à la police locale dans les cinq jours","Un informe de choque al RMV y a la policía local en cinco días"),
   ("Only a call to your insurance company","Sèlman yon apèl bay konpayi asirans ou","Seulement un appel à l'assureur","Solo una llamada a su seguro"),
   ("A report with your insurance company within 30 days","Yon rapò ak konpayi asirans ou nan 30 jou","Une déclaration à votre assureur dans les 30 jours","Un informe a su aseguradora dentro de 30 días"),
   ("Any crash with injury, death or $1,000 or more in property damage must be reported to the RMV and local police within five days. Telling your insurer is not enough.","Nenpòt aksidan ki gen blese, lanmò oswa $1,000 oswa plis domaj dwe rapòte bay RMV ak lapolis lokal nan senk jou. Di asirans ou sèlman pa ase.","Tout accident avec blessé, décès ou au moins 1 000 $ de dégâts doit être déclaré au RMV et à la police locale dans les cinq jours. Prévenir l'assureur ne suffit pas.","Todo choque con heridos, muertos o $1,000 o más de daños debe informarse al RMV y a la policía local en cinco días. Avisar al seguro no basta.")),
  ("pm813",3,4,("Driver Removal Law","Lwa sou Retire Machin","loi sur le dégagement des véhicules","Ley de Retiro de Vehículos"),
   ("You have a minor crash and no one is hurt. What does the Driver Removal Law require?","Ou fè yon ti aksidan epi pèsonn pa blese. Kisa Lwa sou Retire Machin nan mande?","Petit accident sans blessé. Qu'exige la loi sur le dégagement des véhicules ?","Tiene un choque menor sin heridos. ¿Qué exige la Ley de Retiro de Vehículos?"),
   ("Leave the cars exactly where they are for police","Kite machin yo egzakteman kote yo ye pou lapolis","Laisser les voitures exactement en place pour la police","Dejar los autos exactamente donde están para la policía"),
   ("Drive home and report it later","Kondui ale lakay epi rapòte l pita","Rentrer chez soi et déclarer plus tard","Irse a casa e informarlo después"),
   ("Call a tow truck before moving","Rele yon remòkaj anvan w deplase","Appeler une dépanneuse avant de bouger","Llamar una grúa antes de moverse"),
   ("Move the vehicles out of the travel lanes to a safe place","Retire machin yo nan vwa sikilasyon yo pou mete yo yon kote ki san danje","Déplacer les véhicules hors des voies vers un lieu sûr","Sacar los vehículos de los carriles a un lugar seguro"),
   ("If there are no injuries, the Driver Removal Law requires moving the vehicles out of travel lanes to a safe place. Then exchange information. Never leave the scene.","Si pa gen blese, Lwa sou Retire Machin nan mande pou w retire machin yo nan vwa sikilasyon yo pou mete yo yon kote ki san danje. Apre sa bay youn lòt enfòmasyon. Pa janm kite sèn nan.","S'il n'y a pas de blessé, la loi exige de dégager les véhicules hors des voies vers un endroit sûr. Échangez ensuite les informations. Ne quittez jamais les lieux.","Si no hay heridos, la ley exige sacar los vehículos de los carriles a un lugar seguro. Luego intercambien información. Nunca se vaya del lugar.")),
  ("pm814",2,4,("downed wires","fil kouran ki tonbe","fils tombés","cables caídos"),
   ("After a crash, power lines have fallen on a car with people inside. What should they do?","Apre yon aksidan, fil kouran tonbe sou yon machin ki gen moun andedan. Kisa yo dwe fè?","Après un accident, des fils électriques sont tombés sur une voiture occupée. Que doivent faire les occupants ?","Después de un choque, cayeron cables eléctricos sobre un auto con personas dentro. ¿Qué deben hacer?"),
   ("Jump out right away","Sote soti touswit","Sauter dehors tout de suite","Saltar afuera de inmediato"),
   ("Try to move the wires with a stick","Eseye deplase fil yo ak yon bwa","Essayer de déplacer les fils avec un bâton","Tratar de mover los cables con un palo"),
   ("Stay inside until emergency personnel arrive","Rete andedan jiskaske moun ijans yo rive","Rester à l'intérieur jusqu'à l'arrivée des secours","Quedarse dentro hasta que llegue el personal de emergencia"),
   ("Drive the car out from under the wires","Kondui machin nan soti anba fil yo","Sortir la voiture de sous les fils","Mover el auto de debajo de los cables"),
   ("Do not go near fallen wires. If wires are on a vehicle, the people inside should stay there until emergency personnel arrive, and no one should touch the vehicle.","Pa pwoche fil ki tonbe yo. Si fil yo sou yon veyikil, moun ki andedan yo dwe rete jiskaske moun ijans yo rive, epi pèsonn pa dwe touche veyikil la.","Ne vous approchez pas des fils tombés. S'ils sont sur un véhicule, les occupants restent dedans jusqu'aux secours, et personne ne touche le véhicule.","No se acerque a cables caídos. Si están sobre un vehículo, quienes están dentro deben quedarse hasta que llegue ayuda, y nadie debe tocarlo.")),
  ("pm815",0,4,("hit and run","frape epi kouri","délit de fuite","choque y fuga"),
   ("You scrape a parked car and no one is around. What must you do?","Ou grate yon machin ki pake epi pa gen pèsonn bò la. Kisa ou dwe fè?","Vous éraflez une voiture garée et personne n'est là. Que devez-vous faire ?","Raya un auto estacionado y no hay nadie. ¿Qué debe hacer?"),
   ("Try to find the owner, or notify the local police","Eseye jwenn pwopriyetè a, oswa avèti lapolis lokal","Essayer de trouver le propriétaire, ou prévenir la police locale","Tratar de encontrar al dueño, o avisar a la policía local"),
   ("Leave, since no one saw it happen","Ale, paske pèsonn pa wè sa","Partir, puisque personne ne l'a vu","Irse, ya que nadie lo vio"),
   ("Leave a note on the windshield, without your name","Kite yon nòt sou vit devan an, san non w","Laisser un mot sur le pare-brise, sans votre nom","Dejar una nota en el parabrisas, sin su nombre"),
   ("Wait 10 minutes, then leave","Tann 10 minit, apre sa ale","Attendre 10 minutes puis partir","Esperar 10 minutos e irse"),
   ("If you damage a parked vehicle or property, try to locate the owner or notify the local police. Leaving the scene without identifying yourself is a criminal hit-and-run violation.","Si w fè domaj sou yon veyikil ki pake oswa yon pwopriyete, eseye jwenn pwopriyetè a oswa avèti lapolis lokal. Kite sèn nan san w pa idantifye tèt ou se yon vyolasyon kriminèl «frape epi kouri».","Si vous endommagez un véhicule garé ou un bien, cherchez le propriétaire ou prévenez la police locale. Partir sans vous identifier est un délit de fuite pénal.","Si daña un vehículo estacionado o una propiedad, busque al dueño o avise a la policía local. Irse sin identificarse es un delito de choque y fuga.")),
  ("pm816",1,4,("injured person","moun ki blese","blessé","persona herida"),
   ("You stop to help at a crash. A person is bleeding and conscious. What should you do?","Ou kanpe pou ede nan yon aksidan. Yon moun ap senyen epi l konsyan. Kisa ou dwe fè?","Vous vous arrêtez pour aider après un accident. Une personne saigne et est consciente. Que faire ?","Se detiene a ayudar en un choque. Una persona sangra y está consciente. ¿Qué debe hacer?"),
   ("Move them to your car right away","Pote l nan machin ou touswit","La transporter tout de suite dans votre voiture","Llevarla de inmediato a su auto"),
   ("Press directly on the wound and keep them still and warm","Peze dirèkteman sou blesi a epi kenbe l trankil ak cho","Appuyer directement sur la plaie et la garder immobile et au chaud","Presionar directo sobre la herida y mantenerla quieta y abrigada"),
   ("Give them something to drink","Ba l yon bagay pou l bwè","Lui donner à boire","Darle algo de beber"),
   ("Leave once police arrive without giving your name","Ale lè lapolis rive san w pa bay non w","Partir à l'arrivée de la police sans donner votre nom","Irse cuando llegue la policía sin dar su nombre"),
   ("Do not move an injured person unless necessary. Put pressure directly on bleeding until help arrives, and cover them to keep warm and prevent shock.","Pa deplase yon moun ki blese sof si sa nesesè. Peze dirèkteman sou kote k ap senyen an jiskaske èd rive, epi kouvri l pou l rete cho e pou evite chòk.","Ne déplacez pas un blessé sauf nécessité. Appuyez directement sur le saignement jusqu'aux secours et couvrez-le pour le garder au chaud et éviter le choc.","No mueva a un herido salvo que sea necesario. Presione directo sobre el sangrado hasta que llegue ayuda y cúbralo para mantenerlo abrigado y evitar el choque."))]))

